window.SDG4_GRADES = {"1": [{"ch": 0, "q": "¿De qué trata el Objetivo 4?", "options": ["Una buena escuela para todos", "Coches rápidos", "Ciudades grandes", "Solo deportes"], "answer": 0, "explain": "El Objetivo 4 se llama Educación de Calidad. Quiere que cada niño aprenda en una buena escuela.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuántos objetivos tiene el mundo?", "options": ["5", "17", "10", "50"], "answer": 1, "explain": "El mundo tiene 17 Objetivos de Desarrollo Sostenible. El Objetivo 4 trata de la educación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Quién acordó los objetivos?", "options": ["Una sola maestra", "Solo los niños", "Los países del mundo, juntos", "Una gran empresa"], "answer": 2, "explain": "Todos los países miembros de la ONU acordaron los objetivos juntos. La ONU es un grupo de países.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Puede ir a la escuela todo niño?", "options": ["Sí, todo niño puede", "Solo en las ciudades", "Solo en verano", "No, millones de niños no pueden"], "answer": 3, "explain": "Millones de niños y jóvenes no pueden ir a la escuela. El Objetivo 4 quiere que cada niño tenga un lugar.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué algunos niños no pueden ir a la escuela?", "options": ["Viven lejos o sus familias son pobres", "Son muy altos", "La escuela siempre está cerrada", "No les gusta aprender"], "answer": 0, "explain": "Las largas caminatas, los costos y la pobreza impiden que algunos niños vayan a la escuela. El Objetivo 4 quiere eliminar estas barreras.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué debería tener todo niño?", "options": ["Un coche", "Un lugar en una buena escuela cerca de casa", "Un teléfono", "Una casa en el cielo"], "answer": 1, "explain": "Todo niño debería tener un lugar en una buena escuela, cerca de casa.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué significa terminar la escuela?", "options": ["Irse el primer día", "Saltarse todas las clases", "Pasar por todos los grados y aprender", "No volver nunca"], "answer": 2, "explain": "Terminar la escuela significa completar todos los grados. Muchos niños se van antes del final.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Por qué es bueno que los niños terminen la escuela?", "options": ["Los cansa", "No es importante", "Detiene su aprendizaje", "Les ayuda a aprender y a conseguir trabajo después"], "answer": 3, "explain": "Terminar la escuela da a los niños más habilidades y más oportunidades en la vida.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿La mayoría de los niños termina la escuela en todos los países?", "options": ["No, muchos se van pronto", "Sí, todos terminan", "Nadie va a la escuela", "Solo las niñas terminan"], "answer": 0, "explain": "Muchos niños no terminan la escuela, por eso el Objetivo 4 quiere que más niños se queden hasta el final.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué aprenden los niños en la escuela?", "options": ["Solo dormir", "Leer, escribir y contar", "Solo jugar", "Nada útil"], "answer": 1, "explain": "En la escuela los niños aprenden a leer, escribir y contar. Estas habilidades les sirven toda la vida.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Basta con que los niños asistan a la escuela?", "options": ["Sí, asistir basta", "Solo los maestros deben aprender", "No, deben aprender de verdad", "No importa"], "answer": 2, "explain": "Estar en la escuela no basta. Los niños deben aprender cosas útiles de verdad.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué ayuda a los niños a aprender a leer?", "options": ["Solo música alta", "Ver televisión todo el día", "Quedarse en casa", "Libros y un buen maestro"], "answer": 3, "explain": "Los libros, un buen maestro y la práctica ayudan a los niños a aprender a leer.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué son las habilidades?", "options": ["Cosas que sabes hacer bien, como dibujar o contar", "Lugares donde vas a jugar con amigos después de la escuela", "Reglas que escribe tu maestro en el pizarrón cada mañana", "Tiendas que venden dulces y juguetes cerca de tu casa"], "answer": 0, "explain": "Las habilidades son cosas que aprendemos a hacer bien. El Objetivo 4 quiere que los jóvenes aprendan habilidades para el trabajo y la vida.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué necesitan habilidades los jóvenes?", "options": ["Para dejar de ir a la escuela", "Para conseguir trabajo y ayudar a su comunidad", "Para aburrirse", "No las necesitan"], "answer": 1, "explain": "Las habilidades ayudan a los jóvenes a encontrar trabajo y a ayudar a sus familias y comunidades.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Cuál de estas es una habilidad útil?", "options": ["Romper cosas", "Esconderse de los amigos", "Usar una computadora con seguridad", "Ignorar las reglas"], "answer": 2, "explain": "Aprender informática y otras habilidades útiles ayuda a los jóvenes en el trabajo y en la vida.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Deberían tener las niñas y los niños la misma oportunidad de ir a la escuela?", "options": ["No, solo los niños", "No, solo las niñas", "Solo en algunos países", "Sí, ambos deberían"], "answer": 3, "explain": "Las niñas y los niños deberían tener la misma oportunidad de aprender. El Objetivo 4 quiere acabar con las diferencias injustas entre ellos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa justo para las escuelas?", "options": ["Que todos tengan la oportunidad de aprender", "Solo aprenden los niños ricos", "Algunos niños no reciben nada", "Solo algunos niños son bienvenidos"], "answer": 0, "explain": "Justo significa que cada niño tenga la oportunidad de aprender, sin importar su familia, su hogar o su origen.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Quién debería poder ir a la escuela?", "options": ["Solo los niños con dinero", "Todo niño, sin importar lo que tenga su familia", "Solo los niños que viven en las ciudades", "Ningún niño"], "answer": 1, "explain": "El Objetivo 4 dice que la educación de calidad debe ser para todos, incluidos los niños pobres o que viven lejos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué ayuda más a una escuela?", "options": ["Una gran piscina", "Coches lujosos en el estacionamiento", "Maestros buenos y capacitados", "Aulas vacías"], "answer": 2, "explain": "Los buenos maestros ayudan a los niños a aprender. El Objetivo 4 quiere más maestros capacitados.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué necesitan los maestros para ayudar a los niños a aprender?", "options": ["Ninguna ayuda", "Trabajar sin pago", "Faltar a clase", "Capacitación y apoyo"], "answer": 3, "explain": "Los maestros necesitan buena capacitación y apoyo para ayudar a que todos los niños aprendan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "¿Deberían ser gratuitas la primaria y la secundaria?", "options": ["Sí, el Objetivo 4 quiere escuela gratuita", "No, la escuela debe costar mucho", "Solo para niños", "Solo en las ciudades"], "answer": 0, "explain": "El Objetivo 4 quiere que la primaria y la secundaria sean gratuitas para todos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "¿Quién ayuda a que la escuela sea posible para cada niño?", "options": ["Solo los padres con dinero", "Los gobiernos y las comunidades", "Nadie", "Solo los niños"], "answer": 1, "explain": "Los gobiernos y las comunidades ayudan a construir escuelas y a pagar a los maestros, para que cada niño pueda ir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Cuándo acordaron los países los objetivos?", "options": ["1900", "1950", "2015", "2050"], "answer": 2, "explain": "Los países acordaron los objetivos en 2015. Fijaron 2030 como el año para alcanzarlos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Para qué año deberían alcanzarse los objetivos?", "options": ["2010", "1990", "2100", "2030"], "answer": 3, "explain": "Los países fijaron 2030 como el año para alcanzar los objetivos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Por qué deberían ir los niños pequeños al preescolar?", "options": ["Para prepararse para la primaria", "Porque es vacación", "Para dejar de aprender", "No es útil"], "answer": 0, "explain": "El aprendizaje temprano ayuda a los niños pequeños a prepararse para la primaria y a crecer.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Cuándo ocurre el aprendizaje temprano?", "options": ["Solo a los 15 años", "Antes de la primaria", "Solo a los 30 años", "Nunca"], "answer": 1, "explain": "El aprendizaje en la primera infancia es para los años antes de la primaria.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "¿Qué es la alfabetización?", "options": ["Saber nadar", "Saber dibujar", "Saber leer y escribir", "Saber correr rápido"], "answer": 2, "explain": "La alfabetización significa leer y escribir. El Objetivo 4 quiere que todos los jóvenes sepan leer y escribir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "¿Qué es la alfabetización numérica?", "options": ["Saber cantar", "Saber cocinar", "Saber pintar", "Saber contar y hacer sumas"], "answer": 3, "explain": "La alfabetización numérica significa usar los números, como contar y sumar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Deberían ir los niños con discapacidad a la escuela con otros niños?", "options": ["Sí, las escuelas deben recibirlos", "No, deben quedarse en casa", "Solo los fines de semana", "Solo en lugares especiales"], "answer": 0, "explain": "El Objetivo 4 quiere escuelas que acojan e incluyan a todos los niños, incluidos los niños con discapacidad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Qué hace que una escuela sea inclusiva?", "options": ["Solo se permite a algunos niños", "Todos son bienvenidos y pueden aprender", "Los niños se mantienen separados", "Nadie puede entrar"], "answer": 1, "explain": "Una escuela inclusiva recibe a todos los niños, para que todos puedan aprender juntos.", "src": "UN 2030 Agenda (2015)"}], "2": [{"ch": 0, "q": "¿Qué número es Educación de Calidad?", "options": ["4", "2", "9", "12"], "answer": 0, "explain": "La Educación de Calidad es el Objetivo 4 de los 17 Objetivos Globales.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "El Objetivo 4 trata de ¿qué cosa?", "options": ["Solo deportes", "Buen aprendizaje para todos", "Solo vacaciones", "Solo grandes ciudades"], "answer": 1, "explain": "El Objetivo 4 quiere que todo niño y todo adulto reciban una buena educación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿En qué año acordaron los países los Objetivos Globales?", "options": ["1945", "2001", "2015", "2040"], "answer": 2, "explain": "En 2015 los líderes mundiales acordaron 17 Objetivos Globales que alcanzar para 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Por qué deberían ir los niños a la escuela?", "options": ["Para dormir", "Para llegar tarde", "Para estar solos", "Para aprender y crecer"], "answer": 3, "explain": "La escuela ayuda a los niños a aprender a leer, a contar y a hacer amigos.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "¿Debería tener todo niño derecho a ir a la escuela?", "options": ["Sí", "No", "Solo los niños", "Solo en las ciudades"], "answer": 0, "explain": "Todo niño tiene derecho a la educación.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "Un niño no puede llegar a la escuela porque queda muy lejos. Este es un problema de:", "options": ["Color", "Acceso", "Sueño", "Música"], "answer": 1, "explain": "El acceso significa poder llegar a una escuela y entrar.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué lugar ayuda a los niños a aprender juntos?", "options": ["Una zapatería", "Un estacionamiento", "Una escuela", "Un estante de supermercado"], "answer": 2, "explain": "Una escuela es un lugar donde los niños aprenden juntos con sus maestros.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué quieren los padres que sus hijos terminen la escuela?", "options": ["Hace que los niños no quieran leer libros en casa", "Significa que nunca hay que pagar las cuotas escolares", "Elimina la necesidad de aprender después de la escuela", "Terminar la escuela mejora el futuro trabajo y la salud del niño"], "answer": 3, "explain": "Terminar la escuela se relaciona con mejores trabajos, ingresos y salud en la vida adulta.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Por qué algunos niños dejan la escuela pronto?", "options": ["El dinero, la distancia o una enfermedad pueden impedírselo", "No les gusta aprender", "La escuela es muy corta", "Tienen demasiados libros"], "answer": 0, "explain": "Muchos niños se van pronto por dinero, transporte o enfermedad.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué es bueno seguir en la escuela?", "options": ["Te aburres", "Aprendes más cada año", "Pierdes amigos", "Dejas de aprender"], "answer": 1, "explain": "Cada año en la escuela te ayuda a aprender más y a desarrollar habilidades.", "src": "UNESCO"}, {"ch": 2, "q": "¿Cuál de estas cosas ayuda a los estudiantes a terminar la escuela?", "options": ["Faltar a todas las clases", "Saltarse comidas", "El apoyo de la familia y de los maestros", "Nunca hacer preguntas"], "answer": 2, "explain": "El apoyo de la familia y de los maestros ayuda a los estudiantes a seguir adelante.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es leer?", "options": ["Comer palabras", "Solo dibujar ilustraciones", "Correr rápido", "Entender las palabras de una página"], "answer": 3, "explain": "Leer significa entender las palabras y lo que dicen.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué habilidad te ayuda a sumar 2 y 3?", "options": ["Contar", "Nadar", "Solo cantar", "Cocinar"], "answer": 0, "explain": "Contar nos ayuda a saber cuántas cosas hay en total.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué actividad ayuda a los niños pequeños a desarrollar sus primeras habilidades de lectura?", "options": ["Ver muchas horas de televisión cada día", "Leer cuentos en voz alta y hablar de las ilustraciones", "Copiar en silencio largas listas de palabras al azar", "Leer solo problemas de matemáticas y nunca cuentos"], "answer": 1, "explain": "La lectura compartida y la conversación desarrollan el vocabulario y la alfabetización temprana.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es una biblioteca?", "options": ["Un lugar para vender autos", "Un lugar solo con juguetes", "Un lugar con muchos libros", "Un lugar para nadar"], "answer": 2, "explain": "Una biblioteca es un lugar donde la gente puede leer y pedir libros prestados.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es el trabajo en equipo?", "options": ["Trabajar siempre solo", "Ganar cada partido sin ayuda", "Esconderse de los amigos", "Trabajar juntos con otros"], "answer": 3, "explain": "El trabajo en equipo significa trabajar juntos para alcanzar una meta.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a decir cómo te sientes?", "options": ["La comunicación", "Saltar a la pata coja", "Dormir", "Pintar paredes"], "answer": 0, "explain": "La comunicación significa expresar tus ideas y escuchar a los demás.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué significa ser creativo?", "options": ["Copiar exactamente", "Crear ideas o cosas nuevas", "No intentar nunca", "Usar solo dinero"], "answer": 1, "explain": "Ser creativo significa crear algo nuevo, como un dibujo o un cuento.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a resolver un problema?", "options": ["Cerrar los ojos", "Salir corriendo", "Pensar con cuidado", "Ignorarlo"], "answer": 2, "explain": "Pensar con cuidado nos ayuda a encontrar soluciones a los problemas.", "src": "UNESCO"}, {"ch": 5, "q": "¿Deberían ir a la escuela tanto las niñas como los niños?", "options": ["Solo los niños", "Solo las niñas", "Ninguno debería", "Sí, ambos deberían"], "answer": 3, "explain": "Las niñas y los niños deberían tener las mismas oportunidades de ir a la escuela.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa igual en la educación?", "options": ["Todos tienen una oportunidad justa", "Todos usan los mismos zapatos", "Algunos niños no tienen maestros", "Solo aprenden los niños ricos"], "answer": 0, "explain": "La educación igualitaria significa que todos tienen una oportunidad justa de aprender.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Cuál es una forma justa de compartir libros en la escuela?", "options": ["Que solo lo tenga el niño más rápido", "Que todos tengan su turno", "Que solo los guarde el maestro", "Que solo lo tenga el niño más alto"], "answer": 1, "explain": "Compartir de forma justa significa que cada niño tiene la oportunidad de usar los libros.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué niños tienen derecho a ir a la escuela?", "options": ["Solo los niños cuyos padres pagan las cuotas más altas", "Solo los niños varones que viven en la capital", "Todo niño, sin importar su familia o su origen", "Solo los niños que ya leen muy bien"], "answer": 2, "explain": "Todo niño tiene derecho a la educación, sin importar su origen.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 6, "q": "¿Qué hace un maestro?", "options": ["Solo vende comida", "Solo maneja autobuses", "Limpia el cielo", "Ayuda a los niños a aprender"], "answer": 3, "explain": "Los maestros ayudan a los niños a aprender cosas nuevas y a crecer.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué necesitan las escuelas buenos maestros?", "options": ["Los maestros ayudan a los niños a aprender bien", "Los maestros detienen todo aprendizaje", "Los maestros solo dan deberes", "Los maestros no son necesarios"], "answer": 0, "explain": "Los buenos maestros ayudan a los niños a aprender y a sentirse seguros en la escuela.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué ayuda a los maestros a enseñar mejor?", "options": ["Menos sueldo para todos", "La capacitación y el apoyo", "Cerrar todas las escuelas", "Ignorar a los niños"], "answer": 1, "explain": "La capacitación ayuda a los maestros a conocer nuevas formas de enseñar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué puede mostrar un buen maestro a sus alumnos?", "options": ["Cómo ser crueles", "Cómo ser perezosos", "Cómo ser amables y curiosos", "Cómo esconderse"], "answer": 2, "explain": "Los buenos maestros ayudan a los niños a ser amables, curiosos y valientes.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué necesitan las escuelas para funcionar bien?", "options": ["Solo computadoras", "Solo música alta", "Solo una piscina", "Libros, pupitres y maestros"], "answer": 3, "explain": "Las escuelas necesitan muchas cosas, incluidos libros, pupitres y maestros.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué ayuda a que los niños estén seguros y sanos en la escuela?", "options": ["Agua limpia y baños", "Coches grandes", "No tener techo", "Solo altavoces ruidosos"], "answer": 0, "explain": "El agua limpia y los baños ayudan a que los niños se mantengan sanos en la escuela.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "¿Por qué algunas escuelas no tienen libros?", "options": ["Los libros no son necesarios", "No tienen suficiente dinero", "Los niños no leen", "Los libros pesan demasiado"], "answer": 1, "explain": "Se necesita dinero para comprar libros y otras cosas de la escuela.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué necesitan dinero las escuelas?", "options": ["Solo para comprar coches", "Solo para pagar vacaciones", "Para comprar cosas para aprender", "Las escuelas no necesitan dinero"], "answer": 2, "explain": "El dinero paga libros, maestros, pupitres y otras cosas de la escuela.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué documento dice que todos tienen derecho a la educación?", "options": ["Un libro de cocina con recetas para la familia", "Un mapa de los cráteres y mares de la Luna", "El horario escolar de todo el trimestre", "La Declaración Universal de los Derechos Humanos"], "answer": 3, "explain": "La Declaración Universal de los Derechos Humanos dice que todos tienen derecho a la educación.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿En qué año se aprobó la Declaración Universal de los Derechos Humanos?", "options": ["1948", "1900", "1975", "2030"], "answer": 0, "explain": "Fue aprobada en 1948 por la Asamblea General de las Naciones Unidas.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿Qué organización se creó para ayudar a los países a trabajar juntos por la paz y la educación?", "options": ["El circo", "Las Naciones Unidas", "El club deportivo", "La empresa de autos"], "answer": 1, "explain": "Las Naciones Unidas se formaron después de la Segunda Guerra Mundial para ayudar a los países a trabajar juntos.", "src": "United Nations"}, {"ch": 9, "q": "¿Cuál es una buena forma de que los niños pequeños aprendan?", "options": ["Sentarse quietos todo el día", "Permanecer en silencio", "Jugando y conversando", "Trabajar de noche"], "answer": 2, "explain": "Los niños pequeños aprenden mucho jugando y hablando con los adultos.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué ayuda a los bebés a aprender?", "options": ["Mantenerlos a oscuras", "No cargarlos nunca", "Darles solo dulces", "Hablarles y cantarles"], "answer": 3, "explain": "Hablar, cantar y jugar con los bebés les ayuda a aprender el lenguaje.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué ayuda a un niño a crecer bien antes de la escuela?", "options": ["El cariño y el cuidado de los adultos", "Estar abandonado", "Demasiados dulces", "No dormir"], "answer": 0, "explain": "El cariño, el cuidado y el juego en los primeros años ayudan a los niños a crecer fuertes y listos para aprender.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué significa alfabetización?", "options": ["Saber bailar", "Saber leer y escribir", "Saber nadar", "Saber solo dibujar"], "answer": 1, "explain": "La alfabetización significa saber leer y escribir.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué letra va después de la A en el abecedario?", "options": ["Z", "D", "B", "Q"], "answer": 2, "explain": "La B va después de la A en el abecedario.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Cuál de estas cosas ayuda a las personas a leer mejor?", "options": ["Nunca abrir un libro", "Solo ver videos", "Olvidar las letras", "Leer un poco cada día"], "answer": 3, "explain": "Leer un poco cada día ayuda a las personas a mejorar su lectura.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "¿Qué significa la inclusión en la escuela?", "options": ["Todos son bienvenidos y pueden aprender", "Solo algunos niños pueden entrar", "Todos los niños deben ser iguales", "Los niños deben quedarse en casa"], "answer": 0, "explain": "La inclusión significa que todo niño puede aprender en la escuela, incluidos los niños con discapacidad.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Deberían poder ir a la escuela los niños con discapacidad?", "options": ["No", "Sí", "Solo los domingos", "Solo si no tienen amigos"], "answer": 1, "explain": "Los niños con discapacidad tienen derecho a ir a la escuela con los demás.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué ayuda a un niño que usa silla de ruedas a aprender en la escuela?", "options": ["Una escuela sin puertas", "Una escuela solo con escaleras", "Una escuela con rampas", "Una escuela muy lejos"], "answer": 2, "explain": "Las rampas y las aulas sin escalones ayudan a los niños que usan silla de ruedas a moverse por la escuela.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Cuál es una forma amable de tratar a un compañero que es diferente?", "options": ["Dejarlo afuera", "Ponerle apodos", "Ignorarlo", "Incluirlo en el juego"], "answer": 3, "explain": "Incluir a los compañeros ayuda a que todos se sientan bienvenidos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "¿Para qué año se espera alcanzar los Objetivos Globales?", "options": ["2030", "1990", "2000", "2060"], "answer": 0, "explain": "Se espera alcanzar los Objetivos Globales para 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué ayuda a los niños a llegar a la escuela con seguridad?", "options": ["Calles cerradas", "Calles y caminos seguros", "Cruzar calles muy transitadas solos", "Quedarse en casa"], "answer": 1, "explain": "Las calles y los caminos seguros ayudan a los niños a llegar a la escuela con seguridad.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es una buena razón para seguir adelante cuando la escuela es difícil?", "options": ["Nadie lo notará", "La escuela nunca ayuda", "Puedes aprender y alcanzar tus metas", "Aprender no sirve de nada"], "answer": 2, "explain": "Seguir adelante te ayuda a alcanzar tus metas y aprender cosas nuevas.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué significa la sigla ONU?", "options": ["Enfermeros Unidos", "Notas Únicas", "Nombre Bajo", "Organización de las Naciones Unidas"], "answer": 3, "explain": "ONU significa Organización de las Naciones Unidas.", "src": "United Nations"}, {"ch": 9, "q": "¿Por qué es bueno jugar para los niños pequeños?", "options": ["Les ayuda a aprender y crecer", "Es una pérdida de tiempo", "Solo los cansa", "No está permitido"], "answer": 0, "explain": "El juego desarrolla el pensamiento, el lenguaje y las habilidades sociales.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Cuál es la primera letra del abecedario?", "options": ["Z", "A", "M", "K"], "answer": 1, "explain": "La A es la primera letra del abecedario.", "src": "UNESCO, International Literacy Day"}], "3": [{"ch": 0, "q": "¿Qué significa SDG?", "options": ["Objetivos de Desarrollo Sostenible", "Súper Juegos de Perros", "Guía Simple de Escritorio", "Grupo de Cena Dulce"], "answer": 0, "explain": "SDG significa Objetivos de Desarrollo Sostenible.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuántos Objetivos Globales hay?", "options": ["7", "17", "12", "27"], "answer": 1, "explain": "Hay 17 Objetivos Globales, y el Objetivo 4 trata de la educación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué palabra describe mejor el Objetivo 4?", "options": ["Velocidad", "Silencio", "Calidad", "Precio"], "answer": 2, "explain": "El Objetivo 4 se llama Educación de Calidad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué número de Objetivo corresponde al agua limpia y el saneamiento?", "options": ["2", "9", "15", "6"], "answer": 3, "explain": "El Objetivo 6 es Agua Limpia y Saneamiento.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué es una meta en los Objetivos Globales?", "options": ["Un propósito específico que alcanzar", "Un tipo de papel", "Un tipo de deporte", "Un tipo de comida"], "answer": 0, "explain": "Cada objetivo tiene metas que dicen exactamente qué lograr.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué obstáculo puede impedir que una niña vaya a la escuela?", "options": ["Demasiados libros", "Una larga caminata por un camino inseguro", "Demasiado sol", "Demasiados maestros"], "answer": 1, "explain": "La distancia y los caminos inseguros pueden impedir que los niños lleguen a la escuela.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "¿Qué significa que una escuela sea gratuita?", "options": ["Los niños deben pagar para entrar", "Los niños deben llevar dinero a cada clase", "Los niños no pagan cuotas para entrar", "Los niños solo pueden asistir los fines de semana"], "answer": 2, "explain": "Una escuela gratuita significa que los niños no tienen que pagar cuotas para asistir.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué derecho dice que todo niño debe poder ir a la escuela?", "options": ["El derecho a un coche", "El derecho a unas vacaciones", "El derecho a un equipo deportivo", "El derecho a la educación"], "answer": 3, "explain": "El derecho a la educación significa que todo niño puede ir a la escuela.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "¿Qué es una zona remota?", "options": ["Un lugar lejos de pueblos y ciudades", "Un lugar sin cielo", "Un lugar bajo el mar", "Un lugar sin personas"], "answer": 0, "explain": "Las zonas remotas están lejos de los pueblos, así que a los niños les puede costar llegar a la escuela.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es un desertor escolar?", "options": ["Un estudiante que termina temprano", "Un estudiante que deja la escuela antes de terminar", "Un maestro que se va", "Un estudiante que lee rápido"], "answer": 1, "explain": "Un desertor escolar deja la escuela antes de completarla.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué es importante que los niños completen la primaria?", "options": ["Significa que nunca más habrá aprendizaje", "Es solo para divertirse", "Les da lectura, escritura y matemáticas básicas", "Elimina la necesidad de hacer tareas"], "answer": 2, "explain": "Completar la primaria desarrolla habilidades básicas para la vida.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué puede ayudar a los estudiantes a seguir en la escuela?", "options": ["Faltar a clases", "Abandonar temprano", "Ignorar a los maestros", "La tutoría y el apoyo"], "answer": 3, "explain": "La tutoría y el apoyo ayudan a los estudiantes a quedarse en la escuela y seguir aprendiendo.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la asistencia?", "options": ["Estar presente en la escuela", "Ganar un premio", "Escribir una carta", "Comprar libros"], "answer": 0, "explain": "La asistencia significa estar en la escuela para las clases.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué debe hacer una escuela cuando un niño falta muchos días?", "options": ["Olvidarse de él", "Averiguar por qué y ayudarlo a volver", "Quitarlo de la lista sin razón", "Pedirle que pague una multa"], "answer": 1, "explain": "Las escuelas pueden apoyar a las familias para que los niños regresen.", "src": "UNESCO"}, {"ch": 3, "q": "¿De qué trata principalmente la competencia matemática básica?", "options": ["Pintar cuadros con colores brillantes y pinceles", "Cantar canciones sobre animales y las estaciones", "Usar números y matemáticas básicas en la vida diaria", "Memorizar los nombres de los países del mundo"], "answer": 2, "explain": "La competencia matemática básica significa usar los números con seguridad en la vida diaria.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es una buena forma de comprobar lo que aprendiste?", "options": ["No volver a intentarlo nunca", "Copiar sin pensar", "Dormir durante las clases", "Hacer preguntas y practicar"], "answer": 3, "explain": "Practicar y hacer preguntas te ayuda a entender cosas nuevas.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es un resultado de aprendizaje?", "options": ["Lo que una persona puede hacer después de aprender", "El precio de la escuela", "El clima el día del examen", "El número de pupitres"], "answer": 0, "explain": "Un resultado de aprendizaje es la habilidad o el conocimiento que adquiere el estudiante.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Para qué sirve un examen?", "options": ["Para decidir el clima", "Para comprobar lo que alguien ha aprendido", "Para hacer salir el sol", "Para elegir el menú del almuerzo"], "answer": 1, "explain": "Los exámenes ayudan a maestros y estudiantes a ver qué se ha aprendido.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Qué es la comprensión lectora?", "options": ["Leer muy rápido", "Leer en voz muy alta", "Entender lo que lees", "Leer solo las imágenes"], "answer": 2, "explain": "La comprensión lectora significa entender el significado de un texto.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a trabajar bien con personas de otros lugares?", "options": ["Ignorar a los demás", "Gritarles a los demás", "Esconderse de los demás", "El respeto hacia los demás"], "answer": 3, "explain": "El respeto ayuda a personas de distintos orígenes a trabajar y aprender juntas.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es el pensamiento crítico?", "options": ["Revisar si una idea tiene sentido", "Creer en todas las ideas a la vez", "No hacer nunca preguntas", "Olvidar lo que lees"], "answer": 0, "explain": "El pensamiento crítico significa hacer preguntas y comprobar los hechos.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué habilidad puede ayudarte a conseguir un trabajo algún día?", "options": ["Dormir muchas horas durante el día escolar", "Habilidades prácticas como la informática o la reparación", "Evitar todas las clases y la práctica en casa", "Negarse a aprender algo nuevo"], "answer": 1, "explain": "Las habilidades prácticas y laborales ayudan a las personas a trabajar y mantenerse.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué habilidad ayuda a un equipo a tomar una decisión?", "options": ["Gritar más fuerte que nadie", "Ignorar al equipo", "Escuchar a cada persona", "Salir de la sala"], "answer": 2, "explain": "Escuchar a todos ayuda a un equipo a elegir bien.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es una habilidad digital?", "options": ["Usar solo lápices", "Romper computadoras", "No usar nunca internet", "Usar computadoras e internet de forma segura"], "answer": 3, "explain": "Las habilidades digitales ayudan a usar la tecnología de forma segura y adecuada.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa equidad en la educación?", "options": ["Apoyo justo para que todo niño pueda aprender", "Que todo niño reciba exactamente lo mismo", "Que solo los mejores estudiantes reciban ayuda", "Que las escuelas no necesitan ayudar"], "answer": 0, "explain": "La equidad significa dar a cada niño el apoyo que necesita para aprender.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué grupo de niños suele quedar fuera de la escuela?", "options": ["Niños que disfrutan jugar fútbol en el recreo", "Niños de familias pobres o de zonas remotas", "Niños que les gusta cantar en el coro escolar", "Niños que siempre se sientan en la primera fila"], "answer": 1, "explain": "Los niños de familias pobres y de zonas remotas tienen más probabilidades de quedar fuera de la escuela.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué es la brecha de género en las escuelas?", "options": ["Un hueco en el patio donde juegan los niños", "Un breve descanso entre dos clases cada día", "Una diferencia entre niñas y niños en la escuela", "Un agujero en una pared de la escuela que hay que reparar"], "answer": 2, "explain": "La brecha de género es una diferencia entre niñas y niños en la escolarización o el aprendizaje.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Por qué las escuelas deberían recibir a niños de todas las lenguas y orígenes?", "options": ["Solo debería hablarse un idioma", "Solo debería permitirse un origen", "Los niños deberían ser enviados lejos", "Todos merecen una oportunidad justa de aprender"], "answer": 3, "explain": "La educación debe incluir a todos los niños de forma justa, sea cual sea su origen.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué grupo de estudiantes puede necesitar ayuda extra para estar seguro en la escuela?", "options": ["Niños vulnerables", "Niños que siempre están contentos", "Niños que pueden volar", "Niños que nunca faltan a clase"], "answer": 0, "explain": "Los niños vulnerables pueden correr más riesgo de quedar fuera o sufrir daño, así que necesitan ayuda adicional.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué es la escasez de maestros?", "options": ["Hay demasiados maestros para los niños", "No hay suficientes maestros capacitados para los niños", "Maestros que nunca trabajan", "Maestros con demasiadas vacaciones"], "answer": 1, "explain": "La escasez significa que no hay suficientes maestros capacitados.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué ayuda a un maestro nuevo a desempeñarse bien?", "options": ["Ningún apoyo", "Ser enviado a otro país", "La tutoría y la formación", "Pausas largas sin pago"], "answer": 2, "explain": "La tutoría y la formación ayudan a los maestros nuevos a crecer.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué importan las condiciones laborales de los maestros?", "options": ["No tienen ningún efecto", "Solo importan para los coches de los maestros", "Solo importan en las ciudades", "Afectan lo bien que aprenden los niños"], "answer": 3, "explain": "Buenas condiciones ayudan a los maestros a quedarse y enseñar bien.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué necesitan los maestros para planificar una clase?", "options": ["Objetivos claros y un buen plan", "No saber nada de la materia", "Una silla rota", "Unas vacaciones"], "answer": 0, "explain": "Los objetivos claros y un plan ayudan a los maestros a enseñar bien.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué necesitan los maestros para seguir aprendiendo?", "options": ["Nunca más aprender", "Formación continua", "Solo vacaciones", "Solo dinero"], "answer": 1, "explain": "Los maestros siguen aprendiendo mediante la formación continua.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es una cuota escolar?", "options": ["Un premio por buenas notas", "Un regalo del maestro", "Dinero que se paga para asistir a una escuela", "Una multa por llegar tarde"], "answer": 2, "explain": "Una cuota escolar es dinero que a veces pagan las familias para asistir a la escuela.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué gastan dinero los gobiernos en las escuelas?", "options": ["Solo para comprar más vacaciones", "Solo para construir más carreteras", "Para reducir los días de clase", "Para ayudar a los niños a aprender y crecer"], "answer": 3, "explain": "El dinero público paga a maestros, edificios y libros para que los niños aprendan.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué necesita un aula para ser un lugar seguro donde aprender?", "options": ["Buena iluminación, aire fresco y un techo firme", "Ninguna ventana, para que la sala quede oscura", "Ruido fuerte de la calle durante toda la clase", "Sillas rotas y un techo con goteras cada semana"], "answer": 0, "explain": "Los buenos edificios ayudan a los niños a aprender con comodidad y seguridad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 7, "q": "¿Qué puede pasar si una escuela no tiene dinero para libros?", "options": ["Los niños aprenden más rápido", "Los niños tienen menos oportunidades de aprender", "Los niños dejan de necesitar la escuela", "Los niños obtienen vacaciones extra"], "answer": 1, "explain": "Sin libros, a los niños les puede resultar más difícil aprender.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué año se aprobó la Convención de la ONU sobre los Derechos del Niño?", "options": ["1948", "1990", "1989", "2015"], "answer": 2, "explain": "Fue aprobada en 1989 por la Asamblea General de la ONU.", "src": "UN Convention on the Rights of the Child, 1989"}, {"ch": 8, "q": "¿Qué fueron los Objetivos de Desarrollo del Milenio?", "options": ["Un conjunto de objetivos de 1900", "Un conjunto de objetivos para la Luna", "Un conjunto de objetivos para el deporte", "Un conjunto de objetivos de 2000 a 2015"], "answer": 3, "explain": "Los ODM abarcaron de 2000 a 2015, antes de los Objetivos Globales.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "¿Qué reunión de 1990 se centró en la Educación para Todos?", "options": ["La Conferencia Mundial sobre Educación para Todos en Jomtien", "Una feria comercial internacional celebrada en Nueva York ese año", "Un festival mundial de cine celebrado en Cannes ese verano", "Una cumbre mundial sobre las reglas del fútbol en Brasil"], "answer": 0, "explain": "Los países se reunieron en Jomtien, Tailandia, en 1990 para comprometerse con la educación para todos.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué día celebra cada año a los maestros?", "options": ["1 de enero", "Día Mundial de los Docentes, 5 de octubre", "25 de diciembre", "8 de septiembre"], "answer": 1, "explain": "La UNESCO celebra el Día Mundial de los Docentes el 5 de octubre de cada año.", "src": "UNESCO"}, {"ch": 9, "q": "¿Qué es la primera infancia?", "options": ["Solo los años de la adolescencia", "Solo los años universitarios", "Los años desde el nacimiento hasta alrededor de los ocho años", "Solo el último año de la escuela"], "answer": 2, "explain": "La primera infancia suele referirse a los años desde el nacimiento hasta alrededor de los ocho años.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué importa el aprendizaje temprano?", "options": ["Los primeros años no importan", "Solo importan los años posteriores", "El aprendizaje temprano solo ayuda al deporte", "Las experiencias tempranas moldean cómo crece el cerebro"], "answer": 3, "explain": "Las experiencias tempranas moldean cómo crece el cerebro y cómo aprende.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Cuál es una buena actividad de aprendizaje temprano?", "options": ["Leer libros ilustrados juntos", "Ver televisión todo el día", "Dejar solo al niño durante horas", "Comer solo dulces"], "answer": 0, "explain": "Leer juntos desarrolla el lenguaje y el aprendizaje temprano.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es el aprendizaje basado en el juego?", "options": ["Aprender sentado sin moverse", "Aprender jugando", "Aprender solo copiando", "Aprender sin hacer nunca preguntas"], "answer": 1, "explain": "El aprendizaje basado en el juego ayuda a los niños pequeños a aprender haciendo.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Cuándo es el Día Internacional de la Alfabetización?", "options": ["1 de enero", "25 de diciembre", "8 de septiembre", "30 de abril"], "answer": 2, "explain": "La UNESCO conmemora el Día Internacional de la Alfabetización cada año el 8 de septiembre.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué ayuda a los adultos a aprender a leer?", "options": ["Que les obliguen a dejar de leer", "Dormir más", "Evitar los libros", "Clases de alfabetización para adultos"], "answer": 3, "explain": "Las clases de alfabetización para adultos les enseñan a leer y escribir.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Por qué a algunas personas les cuesta leer?", "options": ["No tuvieron la oportunidad de aprender", "Leer es ilegal", "Los libros son venenosos", "Las letras son demasiado grandes"], "answer": 0, "explain": "Muchas personas no aprenden a leer cuando no tienen la oportunidad en la escuela.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Cuándo es el Día Internacional de la Lengua Materna?", "options": ["1 de mayo", "21 de febrero", "31 de octubre", "14 de julio"], "answer": 1, "explain": "La UNESCO conmemora el Día Internacional de la Lengua Materna el 21 de febrero.", "src": "UNESCO, International Mother Language Day"}, {"ch": 11, "q": "¿Qué debe hacer una escuela por los niños con discapacidad?", "options": ["Mantenerlos separados de los demás", "Negarles la entrada", "Incluirlos y darles apoyo", "Enviarlos a casa"], "answer": 2, "explain": "Las escuelas inclusivas acogen a los niños con discapacidad y les dan apoyo.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es un ajuste razonable en la escuela?", "options": ["Una forma de evitar enseñar", "Un autobús especial a la ciudad", "Un tipo de cuota de examen", "Una adaptación que ayuda a un niño a participar"], "answer": 3, "explain": "Un ajuste razonable es una adaptación que ayuda a un niño a participar en la escuela.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Cuál de estos es un ejemplo de inclusión?", "options": ["Libros en braille en la biblioteca", "Una escuela sin entrada", "Maestros que ignoran a todos los estudiantes", "Una sala a la que solo algunos niños pueden entrar"], "answer": 0, "explain": "Los libros en braille ayudan a los niños ciegos a leer en clase.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué significa inclusivo?", "options": ["Que deja fuera a algunas personas", "Que acoge a todos", "Que acoge solo a un grupo", "Que hace que las personas se vayan"], "answer": 1, "explain": "Inclusivo significa acoger a todos y hacer espacio para cada persona.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es un cupo escolar?", "options": ["Un asiento en un coche", "Un lugar para dormir", "Un lugar para un niño en la escuela", "Una tienda de libros"], "answer": 2, "explain": "Un cupo escolar es un lugar para que un niño aprenda.", "src": "UNESCO"}], "4": [{"ch": 0, "q": "¿Qué busca el Objetivo 4?", "options": ["Calidad y aprendizaje permanente para todos", "Solo deporte para niños", "Solo empleos para adultos", "Menos escuela para todos"], "answer": 0, "explain": "El Objetivo 4 busca un aprendizaje inclusivo, de calidad y permanente para todos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuántas metas tiene el Objetivo 4?", "options": ["5", "10", "17", "169"], "answer": 1, "explain": "El Objetivo 4 tiene 10 metas: siete de resultados y tres de medios de implementación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuántas metas hay en los 17 Objetivos Globales?", "options": ["17", "50", "169", "300"], "answer": 2, "explain": "Los 17 Objetivos Globales tienen 169 metas en total.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué Objetivo trata sobre el fin de la pobreza?", "options": ["Objetivo 4", "Objetivo 9", "Objetivo 12", "Objetivo 1"], "answer": 3, "explain": "El Objetivo 1 es Fin de la Pobreza.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Por qué un niño de una aldea puede no asistir a la escuela?", "options": ["La escuela queda demasiado lejos", "La escuela queda demasiado cerca", "Hay demasiados autobuses", "Hay demasiados amigos"], "answer": 0, "explain": "Las grandes distancias son un obstáculo común para la escuela.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué algunas familias mantienen a los niños en casa?", "options": ["No quieren educación", "Necesitan ayuda con el trabajo o el dinero", "La escuela es ilegal", "Tienen demasiados coches"], "answer": 1, "explain": "Algunas familias necesitan que los niños ayuden a ganar dinero o a trabajar en casa.", "src": "UNESCO"}, {"ch": 1, "q": "¿Cuál de estas opciones ayuda a los niños de zonas rurales a llegar a la escuela?", "options": ["Cerrar los caminos", "Cruzar ríos solos sin ayuda", "Autobuses escolares o caminos seguros", "Quedarse en casa"], "answer": 2, "explain": "El transporte y los caminos seguros facilitan que los niños rurales asistan a clase.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es la educación preescolar?", "options": ["El aprendizaje después de la universidad", "El aprendizaje solo los fines de semana", "El aprendizaje solo en el lugar de trabajo", "El aprendizaje antes de la primaria"], "answer": 3, "explain": "La educación preescolar es el aprendizaje de los niños pequeños antes de la primaria.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Por qué es importante un edificio escolar seguro?", "options": ["Protege a los niños del peligro", "Hace que la escuela dure más", "Impide que los niños aprendan", "Solo sirve de decoración"], "answer": 0, "explain": "Los edificios seguros protegen a los niños y hacen posible el aprendizaje.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es la escuela primaria?", "options": ["La última etapa de la universidad", "La primera etapa principal de la escolarización", "Solo para maestros", "Un tipo de campamento de vacaciones"], "answer": 1, "explain": "La primaria suele ser la primera etapa principal de la educación formal.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la escuela secundaria?", "options": ["La etapa que precede al jardín de infantes", "Un tipo de campamento deportivo", "La etapa que sigue a la primaria", "Un lugar solo para adultos"], "answer": 2, "explain": "La secundaria sigue a la primaria.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué factor aumenta con frecuencia el abandono escolar temprano?", "options": ["El buen clima", "Demasiados libros", "Ganar premios", "La pobreza"], "answer": 3, "explain": "La pobreza es una de las causas más importantes de que los niños dejen la escuela pronto.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué significa la tasa de finalización?", "options": ["La proporción de niños que terminan un nivel escolar", "La proporción de maestros que duermen", "El número de timbres escolares", "El precio de las mochilas escolares"], "answer": 0, "explain": "La tasa de finalización es la proporción de niños que completan un nivel escolar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué ayuda a que los niños terminen la escuela?", "options": ["Cerrar las escuelas temprano", "Ayudar a las familias con los gastos y el transporte", "Quitar los libros", "Alargar los exámenes cada día"], "answer": 1, "explain": "El apoyo con los gastos y el transporte ayuda a que los niños sigan en la escuela.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué puede hacer una escuela para que los estudiantes sigan asistiendo?", "options": ["Ignorar a los alumnos ausentes y esperar a que regresen", "Dar menos clases a quienes faltan a la escuela", "Hacer seguimiento de la asistencia y contactar a las familias", "Cerrar la escuela temprano todos los viernes"], "answer": 2, "explain": "Las escuelas pueden hacer seguimiento de la asistencia y trabajar con las familias para apoyar al alumnado.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué significa un buen nivel de lectura?", "options": ["Leer solo números", "No leer nunca en voz alta", "Leer más rápido que un coche", "Leer y entender textos acordes con tu edad"], "answer": 3, "explain": "Un buen nivel de lectura significa entender un texto sencillo acorde con tu edad.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué asignatura trata de números, patrones y figuras?", "options": ["Matemáticas", "Música", "Teatro", "Historia del arte"], "answer": 0, "explain": "Las matemáticas son la asignatura de números, patrones y figuras.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es un currículo?", "options": ["Un tipo de uniforme escolar", "El conjunto de asignaturas y lo que aprenden los estudiantes", "Un estacionamiento escolar", "Una lista de vacaciones"], "answer": 1, "explain": "El currículo indica lo que los estudiantes deben aprender en cada asignatura.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué es útil aprender en tu primera lengua?", "options": ["Nunca es útil", "Significa aprender menos", "Los niños entienden mejor las clases", "Hace que la escuela sea más corta"], "answer": 2, "explain": "Los niños aprenden con más facilidad cuando entienden el idioma que se usa en clase.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "¿Qué es una habilidad en educación?", "options": ["Algo que se pierde", "Un tipo de comida", "Solo una asignatura escolar", "Algo que una persona sabe hacer bien"], "answer": 3, "explain": "Una habilidad es una capacidad que se puede practicar y mejorar.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué significa resolver problemas?", "options": ["Encontrar una forma de resolver una pregunta difícil", "Ignorar los problemas", "Hacer los problemas más grandes", "Esperar eternamente a otros"], "answer": 0, "explain": "Resolver problemas significa encontrar la manera de responder o arreglar algo.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a compartir tus ideas con claridad en un grupo?", "options": ["Ocultar tu voz", "Hablar con claridad ante un grupo", "Hablar muy bajito", "No hablar nunca"], "answer": 1, "explain": "Presentar te ayuda a compartir tus ideas con claridad con los demás.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es el liderazgo?", "options": ["Ordenar a otros que guarden silencio", "Llevarse todo el crédito", "Guiar a otros de forma útil", "Evitar responsabilidades"], "answer": 2, "explain": "El liderazgo consiste en ayudar y guiar a otros hacia una meta.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la alfabetización digital?", "options": ["Usar la tecnología para romper cosas", "No usar nunca una computadora", "Escribir solo cartas", "Usar la tecnología para buscar y compartir información"], "answer": 3, "explain": "La alfabetización digital significa usar herramientas digitales de forma segura para aprender y comunicarse.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es una habilidad profesional?", "options": ["Una habilidad práctica para un oficio, como la carpintería", "Una habilidad para dormir", "Una habilidad para evitar el trabajo", "Una habilidad para esconderse"], "answer": 0, "explain": "Las habilidades profesionales son habilidades prácticas que se usan en un oficio.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa la igualdad de género en la escuela?", "options": ["Solo los niños pueden aprender", "Niñas y niños tienen las mismas oportunidades", "Solo las niñas pueden aprender", "Las niñas deben quedarse en casa"], "answer": 1, "explain": "La igualdad de género significa que niñas y niños tienen los mismos derechos y oportunidades en la educación.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué grupo nombra el Objetivo 4 para el acceso en igualdad de condiciones?", "options": ["Solo las personas altas", "Solo las personas de ciudad", "Personas con discapacidad", "Solo las personas a las que les gusta el deporte"], "answer": 2, "explain": "El Objetivo 4 menciona a las personas con discapacidad entre los grupos que necesitan acceso en igualdad de condiciones.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Por qué a veces las niñas faltan a la escuela?", "options": ["A las niñas no les gusta aprender", "La escuela es muy corta", "Las niñas tienen demasiados libros", "Matrimonio temprano, quehaceres domésticos o trayectos inseguros"], "answer": 3, "explain": "El matrimonio temprano, las tareas del hogar y los trayectos inseguros pueden impedir que las niñas asistan a la escuela.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué es un grupo vulnerable en educación?", "options": ["Grupos que enfrentan más obstáculos para aprender", "Grupos que nunca aprenden", "Grupos que solo leen", "Grupos que son muy ricos"], "answer": 0, "explain": "Los grupos vulnerables enfrentan más obstáculos, por lo que pueden necesitar apoyo adicional.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es una comunidad indígena?", "options": ["Un tipo de edificio escolar", "Los primeros pueblos que vivieron en un lugar", "Un tipo de maestro", "Un tipo de mochila escolar"], "answer": 1, "explain": "Los pueblos indígenas son los pueblos originarios de una región, a menudo con sus propias lenguas y culturas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es una escuela amigable para las niñas?", "options": ["Una escuela solo para niñas en la ciudad", "Una escuela donde no se permite a las niñas entrar", "Una escuela con baños seguros y sin acoso", "Una escuela que enseña solo baile"], "answer": 2, "explain": "Las escuelas amigables para las niñas son seguras, tienen buenas instalaciones y maestros respetuosos.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "¿Por qué las escuelas necesitan suficientes maestros?", "options": ["No se necesitan maestros", "Para que los niños dejen de aprender", "Para que la escuela termine antes", "Para que cada clase tenga quien enseñe"], "answer": 3, "explain": "Suficientes maestros significan que cada clase puede enseñarse bien.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un maestro titulado?", "options": ["Un maestro que ha recibido formación para enseñar", "Un maestro sin formación", "Un maestro que solo cuenta chistes", "Un maestro que nunca enseña"], "answer": 0, "explain": "Los maestros titulados tienen la formación necesaria para su trabajo.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué puede ayudar a los maestros a permanecer en su trabajo?", "options": ["Largas jornadas sin descanso", "Salario justo y buenas condiciones", "Ningún apoyo en absoluto", "Ser trasladado lejos cada día"], "answer": 1, "explain": "Un salario justo y buenas condiciones ayudan a los maestros a quedarse en la profesión.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un maestro tutor?", "options": ["Un maestro que huye", "Un maestro que solo se sienta", "Un maestro con experiencia que ayuda a uno más nuevo", "Un maestro que solo escribe poesía"], "answer": 2, "explain": "Los tutores orientan a los maestros nuevos y los ayudan a mejorar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué los maestros necesitan entender a sus estudiantes?", "options": ["Para dar más deberes", "Para dejar de enseñar", "Para evitar a los padres", "Para enseñar de maneras que ayuden a cada niño"], "answer": 3, "explain": "Entender al alumnado ayuda a los maestros a planificar clases que funcionen para ellos.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es una escuela pública?", "options": ["Una escuela financiada con dinero del gobierno", "Una escuela que vende solo comida", "Una escuela dirigida por una sola familia", "Una escuela sin estudiantes"], "answer": 0, "explain": "Las escuelas públicas se financian principalmente con fondos públicos.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es un presupuesto para la educación?", "options": ["Una lista de fechas de vacaciones", "Dinero planificado para la educación", "Un juego sobre dinero", "El precio de un uniforme escolar"], "answer": 1, "explain": "Un presupuesto para la educación es el dinero que el gobierno planea gastar en las escuelas.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué puede pasar cuando una escuela tiene muy poco dinero?", "options": ["Aparecen más maestros", "Los libros se abaratan", "Menos maestros y menos libros", "Las escuelas crecen"], "answer": 2, "explain": "Un dinero limitado puede significar menos maestros y menos materiales de aprendizaje.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué gastos pueden seguir teniendo las familias aunque la matrícula sea gratuita?", "options": ["Ninguno en absoluto", "Solo aire", "Solo sol", "Uniformes, transporte y útiles"], "answer": 3, "explain": "Las familias pueden pagar uniformes, transporte y útiles escolares aunque la matrícula sea gratuita.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es una beca escolar?", "options": ["Dinero entregado para ayudar a una escuela o a un estudiante", "Una multa por tarea atrasada", "Un tipo de examen", "Solo un boleto de autobús escolar"], "answer": 0, "explain": "Una beca es dinero que se entrega para ayudar a una escuela o a un estudiante, por lo general sin devolución.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué año comenzaron los Objetivos de Desarrollo del Milenio?", "options": ["1948", "2000", "1990", "2015"], "answer": 1, "explain": "Los ODM comenzaron en 2000.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "¿Dónde se reunieron los países en 1990 para iniciar el movimiento Educación para Todos?", "options": ["París, Francia", "El Cairo, Egipto", "Jomtien, Tailandia", "Tokio, Japón"], "answer": 2, "explain": "Los países se reunieron en Jomtien, Tailandia, en 1990 por la Educación para Todos.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué marco estableció objetivos educativos en Dakar en 2000?", "options": ["Las reglas de fútbol de Dakar", "La hoja de ruta de Dakar", "El plan alimentario de Dakar", "El Marco de Acción de Dakar"], "answer": 3, "explain": "El Marco de Acción de Dakar se acordó en 2000 en el Foro Mundial sobre la Educación.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué documento dice que la educación primaria debe ser obligatoria y gratuita?", "options": ["La Convención de la ONU sobre los Derechos del Niño", "Un menú escolar con opciones de almuerzo para la semana", "Una guía turística de las mejores playas de Bali", "Un reglamento deportivo para partidos de fútbol escolar"], "answer": 0, "explain": "El artículo 28 establece que la educación primaria debe ser obligatoria y gratuita para todos.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "¿Cómo se llama el acuerdo educativo de 2015?", "options": ["La Declaración de Tokio", "La Declaración de Incheon", "El Pacto de El Cairo", "El Plan de Lima"], "answer": 1, "explain": "La Declaración de Incheon de 2015 fijó los objetivos educativos para 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 9, "q": "¿Cómo aprenden a menudo los niños pequeños?", "options": ["A través de largos exámenes", "A través de horas de silencio", "A través del juego, las canciones y los cuentos", "A través de turnos nocturnos"], "answer": 2, "explain": "El aprendizaje temprano suele darse mediante el juego, las canciones y los cuentos.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué los primeros años de vida son importantes para el cerebro?", "options": ["El cerebro deja de crecer", "El cerebro no cambia", "El cerebro solo crece de noche", "El cerebro crece muy rápido"], "answer": 3, "explain": "El cerebro se desarrolla muy rápido en los primeros años.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué incluye la atención a la primera infancia?", "options": ["Salud, nutrición y aprendizaje", "Solo sueño", "Solo deporte", "Solo dinero"], "answer": 0, "explain": "La atención a la primera infancia apoya la salud, la alimentación y el aprendizaje a la vez.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es una guardería?", "options": ["Un lugar solo para cultivar árboles", "Un lugar donde se cuida a niños muy pequeños", "Un lugar para enviar correo", "Un lugar para construir coches"], "answer": 1, "explain": "Las guarderías cuidan a niños muy pequeños y les ayudan a aprender.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué actividad ayuda a un niño pequeño a aprender palabras?", "options": ["Guardar silencio todo el día", "Solo ver anuncios", "Nombrar objetos y hablar con ellos", "Estar en una habitación oscura"], "answer": 2, "explain": "Hablar y nombrar cosas ayuda a los niños pequeños a construir el lenguaje.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es la tasa de alfabetización?", "options": ["El precio de los libros", "El número de bibliotecas", "El número de maestros", "La proporción de personas que saben leer y escribir"], "answer": 3, "explain": "La tasa de alfabetización muestra la proporción de personas que saben leer y escribir.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Por qué los adultos necesitan saber leer y escribir?", "options": ["Para leer instrucciones de trabajo e información de salud", "Para no hacer ningún trabajo en la fábrica", "Para ganar todos los juegos de la competencia escolar", "Para dejar de aprender cosas nuevas al salir de la escuela"], "answer": 0, "explain": "Leer ayuda a los adultos a trabajar, mantenerse sanos y participar en la vida.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es un rincón de lectura en el aula?", "options": ["Un lugar para guardar zapatos", "Un espacio con libros para leer", "Un lugar solo para almorzar", "Un lugar para guardar bicicletas"], "answer": 1, "explain": "Los rincones de lectura dan a los niños un lugar para leer y disfrutar de los libros.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué ayuda a un niño que tiene dificultades para leer?", "options": ["Menos tiempo leyendo", "Que le digan que no es listo", "Ayuda adicional y práctica de lectura", "Que nunca le den libros"], "answer": 2, "explain": "La ayuda adicional y la práctica pueden ayudar a los niños a ponerse al día.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "¿Qué significa educación inclusiva?", "options": ["Una educación solo para los mejores estudiantes", "Una educación solo para un grupo", "Una educación sin maestros", "Una educación que acoge a todo el alumnado"], "answer": 3, "explain": "La educación inclusiva acoge y apoya a todo el alumnado.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué las escuelas deben tener rampas y baños accesibles?", "options": ["Para que todos puedan usar la escuela", "Para que los niños corran más rápido", "Para que las escuelas parezcan más altas", "Para que las clases sean más cortas"], "answer": 0, "explain": "Los edificios accesibles permiten que todos usen las instalaciones escolares.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Para qué se usa la lengua de señas en las escuelas?", "options": ["Solo para bailar", "Para comunicarse con estudiantes sordos", "Solo para cocinar", "Solo para exámenes de matemáticas"], "answer": 1, "explain": "La lengua de señas ayuda a los estudiantes sordos a comunicarse y aprender.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Quién se beneficia de una escuela inclusiva?", "options": ["Solo los maestros", "Solo los padres", "Todas las personas de la escuela", "Solo la directora o el director"], "answer": 2, "explain": "Las escuelas inclusivas ayudan a que cada niño aprenda y crezca junto a los demás.", "src": "UN CRPD (2006), Article 24"}, {"ch": 3, "q": "¿Qué es un plan de clase?", "options": ["Un plan para las vacaciones familiares de verano", "Una lista de meriendas que se venden en la cantina escolar", "Un mapa de las aulas y los pasillos de la escuela", "Un plan que muestra qué se enseñará y cómo"], "answer": 3, "explain": "Un plan de clase define los objetivos y los pasos de una lección.", "src": "UNESCO Global Report on Teachers (2024)"}], "5": [{"ch": 0, "q": "¿Cuántas metas de resultados tiene el Objetivo 4?", "options": ["Siete", "Tres", "Diez", "Diecisiete"], "answer": 0, "explain": "El Objetivo 4 tiene siete metas de resultados, numeradas del 4.1 al 4.7.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cómo se llaman las tres metas de «medios de implementación» del Objetivo 4?", "options": ["4.1, 4.2 y 4.3", "4.a, 4.b y 4.c", "4.5, 4.6 y 4.7", "4.8, 4.9 y 4.10"], "answer": 1, "explain": "Las metas 4.a, 4.b y 4.c abarcan instalaciones, becas y maestros.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué Objetivo Global es la Igualdad de Género?", "options": ["Objetivo 2", "Objetivo 8", "Objetivo 5", "Objetivo 11"], "answer": 2, "explain": "El Objetivo 5 es Igualdad de Género.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué significa no dejar a nadie atrás?", "options": ["Dejar fuera a las personas más lentas", "Ayudar solo a los países ricos", "Poner fin a toda ayuda", "Incluir a las personas más excluidas"], "answer": 3, "explain": "La Agenda 2030 promete llegar primero a quienes están más rezagados.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Por qué se llaman globales los Objetivos Globales?", "options": ["Se aplican a todos los países", "Son solo para un país", "Son solo para las escuelas", "Son solo para el deporte"], "answer": 0, "explain": "Los Objetivos Globales se aplican a todos los países, ricos y pobres.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuál es el año meta de los Objetivos Globales?", "options": ["2015", "2030", "2050", "2100"], "answer": 1, "explain": "Los Objetivos Globales buscan alcanzarse para 2030.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué grupo tiene más probabilidades de estar fuera de la escuela en muchos países?", "options": ["Niños a los que les encanta leer", "Niños que juegan al fútbol", "Niños en zonas de conflicto", "Niños que visitan bibliotecas"], "answer": 2, "explain": "Los niños en zonas de conflicto y crisis suelen ser los que más dificultades tienen para asistir a la escuela.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué significa fuera de la escuela?", "options": ["Aprender en una biblioteca", "Ir a la escuela los domingos", "Ganar un premio escolar", "No matriculado en ninguna escuela"], "answer": 3, "explain": "Los niños fuera de la escuela son aquellos que no están matriculados en ninguna escuela.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué muchos niños trabajan en lugar de ir a la escuela?", "options": ["Las familias necesitan sus ingresos", "Prefieren trabajar", "La escuela es gratuita", "En la escuela se enseña a trabajar"], "answer": 0, "explain": "Las familias pobres pueden necesitar que los niños trabajen para ganar dinero.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es el trabajo infantil?", "options": ["Cualquier juego tranquilo en casa con amigos después de clase", "Trabajo que daña la salud de los niños o interrumpe su escolarización", "Ayudar a un padre con los deberes y tareas sencillas en casa", "Leer cuentos en voz alta a un hermano o hermana menor"], "answer": 1, "explain": "El trabajo infantil es el trabajo que daña a los niños e impide que aprendan.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es un programa de alimentación escolar?", "options": ["Comida que se vende en las tiendas", "Un tipo de deporte escolar", "Comidas que se dan a los niños en la escuela", "Un festival de comida"], "answer": 2, "explain": "Las comidas escolares pueden animar a los niños a asistir y aprender.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué pueden ayudar las comidas escolares a los niños?", "options": ["Hacen que dejen de aprender", "Se quedan con todo el dinero", "Reemplazan a los libros", "Animan a los niños a asistir"], "answer": 3, "explain": "Las comidas pueden facilitar que los niños vayan a la escuela y se concentren.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la transición de la primaria a la secundaria?", "options": ["Pasar de un nivel escolar al siguiente", "Solo mudarse de casa", "Cambiar de asiento en la misma clase", "Dejar la escuela para siempre"], "answer": 0, "explain": "Transición significa pasar de una etapa escolar a la siguiente.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué algunos niños repiten un año escolar?", "options": ["Repetir siempre es unas vacaciones", "Necesitan más tiempo para aprender los contenidos", "Repetir es un premio", "Tienen demasiados amigos"], "answer": 1, "explain": "Algunos niños repiten un año cuando necesitan más tiempo para aprender.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué significa graduarse?", "options": ["Empezar una nueva escuela", "Mudarse a otro país", "Terminar un nivel de educación", "Dejar de asistir a clases"], "answer": 2, "explain": "Graduarse significa completar con éxito un nivel de estudios.", "src": "UNESCO"}, {"ch": 2, "q": "¿Cuál es el objetivo de terminar la secundaria?", "options": ["Solo conseguir vacaciones", "Solo saltarse exámenes", "Solo dejar de leer", "Habilidades para el trabajo y los estudios posteriores"], "answer": 3, "explain": "La educación secundaria desarrolla habilidades para el trabajo y los estudios posteriores.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué significa retención en las escuelas?", "options": ["Mantener a los estudiantes en la escuela hasta que terminen", "Mantener a los estudiantes dentro de una caja", "Guardar los libros para siempre", "Mantener la escuela cerrada"], "answer": 0, "explain": "La retención significa que los estudiantes permanecen en la escuela hasta completar el nivel.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué factor ayuda a los estudiantes a quedarse en la escuela?", "options": ["Ser obligado a dejar la escuela", "Un camino seguro hasta la escuela", "No tener libros", "Faltar a todas las pruebas"], "answer": 1, "explain": "Los caminos seguros facilitan que los niños se queden en la escuela.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué significa evaluación del aprendizaje?", "options": ["Medir los edificios escolares", "Contar los pupitres", "Medir lo que los estudiantes han aprendido", "Contar los coches de los maestros"], "answer": 2, "explain": "Las evaluaciones del aprendizaje comprueban lo que los estudiantes saben y pueden hacer.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la pobreza de aprendizaje?", "options": ["No tener lápiz ni cuaderno para las clases", "No tener computadora en casa para hacer los deberes", "Vivir lejos de la biblioteca más cercana", "No poder leer un texto sencillo a los diez años"], "answer": 3, "explain": "La pobreza de aprendizaje significa que un niño no puede leer ni entender un texto sencillo a los diez años.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "¿Qué es una habilidad fundamental?", "options": ["Una habilidad básica como leer o contar", "Una asignatura universitaria difícil", "Un tipo de deporte", "Un tipo de música"], "answer": 0, "explain": "Las habilidades fundamentales, como leer y contar, sustentan todo el aprendizaje posterior.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Por qué es importante la lectura temprana?", "options": ["Solo ayuda en arte", "Apoya el aprendizaje en todas las asignaturas", "No hace falta en la escuela", "Solo ayuda en el deporte"], "answer": 1, "explain": "Los niños que leen bien pueden aprender con más facilidad en todas las asignaturas.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la evaluación formativa?", "options": ["Solo un examen final", "Una prueba de la estatura de un estudiante", "Comprobar el aprendizaje durante las clases", "Una prueba de habilidades culinarias"], "answer": 2, "explain": "La evaluación formativa ayuda a los maestros a comprobar el progreso y ajustar las clases.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la evaluación sumativa?", "options": ["Una pregunta que se hace solo al principio", "Un juego sin puntuación", "Una prueba que se da cada mañana", "Una prueba al final de una unidad o de un año"], "answer": 3, "explain": "La evaluación sumativa mide el aprendizaje al final de un periodo.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "¿Qué es la creatividad en el aprendizaje?", "options": ["Crear ideas nuevas y útiles", "Copiar exactamente", "Usar solo ideas antiguas", "Evitar todas las ideas"], "answer": 0, "explain": "La creatividad consiste en encontrar formas nuevas y útiles de pensar y hacer.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a trabajar con personas de distintas culturas?", "options": ["Esconderse de las diferencias", "Comprensión intercultural", "Negarse a hablar", "Ignorar otros idiomas"], "answer": 1, "explain": "La comprensión intercultural ayuda a respetar y trabajar con otras personas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la resiliencia?", "options": ["Rendirse ante el primer desafío", "Nunca enfrentar problemas", "Recuperarse después de una dificultad", "Evitar todo lo nuevo"], "answer": 2, "explain": "La resiliencia significa recuperarse y aprender de los momentos difíciles.", "src": "UNESCO"}, {"ch": 4, "q": "¿Por qué se enseñan habilidades para la vida en algunas escuelas?", "options": ["Para reemplazar todas las clases de matemáticas por clases de arte", "Para alargar el día escolar de todos", "Para eliminar todos los exámenes del año escolar", "Para ayudar a los estudiantes a afrontar los retos diarios"], "answer": 3, "explain": "Las habilidades para la vida ayudan a los estudiantes a tomar buenas decisiones y resolver problemas cotidianos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la educación financiera?", "options": ["Comprender el dinero y cómo administrarlo", "Coleccionar monedas solo por diversión", "Ignorar los precios", "Gastar todo el dinero de una vez"], "answer": 0, "explain": "La educación financiera significa saber usar y ahorrar el dinero con sensatez.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué habilidad te ayuda a usar información de muchas fuentes?", "options": ["Cantar", "Habilidades de investigación", "Hacer malabares", "Solo la jardinería"], "answer": 1, "explain": "Las habilidades de investigación ayudan a los estudiantes a encontrar y comprobar información.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es el índice de paridad de género?", "options": ["Una medida de la altura de la escuela", "Un recuento de las mascotas de los maestros", "Un número que compara la matrícula de niñas y niños", "Una lista de los colores de la escuela"], "answer": 2, "explain": "Un índice de paridad cercano a 1 significa que niñas y niños están matriculados por igual.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué significa un índice de paridad de 1?", "options": ["No hay niñas en la escuela", "Solo hay niñas en la escuela", "Hay el doble de niños", "Igual número de niñas y niños"], "answer": 3, "explain": "Un valor de 1 indica que niñas y niños están matriculados en igual número.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué grupo puede enfrentar barreras adicionales por una discapacidad?", "options": ["Niños con discapacidad", "Niños a los que les gusta dibujar", "Niños que juegan", "Niños que usan gafas"], "answer": 0, "explain": "Los niños con discapacidad pueden enfrentar barreras adicionales sin apoyo.", "src": "UN CRPD (2006), Article 24"}, {"ch": 5, "q": "¿Qué es la discriminación en las escuelas?", "options": ["Trato justo para todos", "Trato injusto por quién es alguien", "Elegir libros por su color", "Dar los mismos deberes a todos"], "answer": 1, "explain": "La discriminación es un trato injusto basado en el grupo o el origen de una persona.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Por qué las escuelas deben estar libres de violencia?", "options": ["La violencia ayuda a los niños a concentrarse", "La violencia es algo normal en la escuela", "La violencia impide que los niños aprendan", "La violencia hace a los niños más fuertes"], "answer": 2, "explain": "Los niños no pueden aprender bien cuando se sienten inseguros.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué hacen las políticas inclusivas?", "options": ["Cierran escuelas para algunos grupos", "Hacen que las escuelas sean solo para los ricos", "Eliminan a todos los maestros", "Abren la educación a todos los grupos"], "answer": 3, "explain": "Las políticas inclusivas ayudan a que todos los grupos accedan a la educación y se beneficien de ella.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué es la proporción maestro-alumno?", "options": ["Cuántos alumnos tiene cada maestro", "Cuántos maestros cobran un sueldo", "Cuántos pupitres hay en una sala", "Cuántas escuelas visita un maestro"], "answer": 0, "explain": "La proporción maestro-alumno indica cuántos estudiantes comparten un mismo maestro.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué importa una proporción maestro-alumno baja?", "options": ["Los maestros no tienen nada que hacer", "Los maestros pueden prestar más atención a cada niño", "Significa que las clases son más ruidosas", "Hace que los maestros sean más ricos"], "answer": 1, "explain": "Las clases más pequeñas permiten a los maestros ayudar más a cada niño.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la motivación docente?", "options": ["Que te paguen por dormir", "Trabajar lo menos posible", "El impulso y el entusiasmo por enseñar bien", "Evitar a los estudiantes"], "answer": 2, "explain": "Los maestros motivados tienen más probabilidades de quedarse y enseñar bien.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué es importante la formación docente?", "options": ["Reemplaza las lecciones", "Elimina la necesidad de estudiantes", "Solo añade vacaciones", "Mejora la calidad de la enseñanza"], "answer": 3, "explain": "Una buena formación ayuda a los maestros a enseñar de forma eficaz.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es una escuela normal?", "options": ["Un lugar donde se forma a los maestros", "Un lugar solo para vender material didáctico", "Una escuela para mascotas", "Un lugar para construir carreteras"], "answer": 0, "explain": "Las escuelas normales preparan a las personas para convertirse en maestros.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué puede apoyar a los maestros en zonas rurales?", "options": ["Ningún apoyo en absoluto", "Vivienda, transporte y formación", "Ser trasladado cada día", "Menos sueldo y más trabajo"], "answer": 1, "explain": "Apoyos como la vivienda y el transporte ayudan a los maestros a servir a las comunidades rurales.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es el gasto público en educación?", "options": ["El dinero que las familias gastan en juguetes", "El dinero gastado solo en deportes", "El dinero que los gobiernos gastan en las escuelas", "El dinero gastado solo en carreteras"], "answer": 2, "explain": "El gasto público en educación es el dinero que los gobiernos usan para financiar las escuelas.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es un bono escolar?", "options": ["Un tipo de uniforme escolar", "Un boleto para un museo", "Un mapa de rutas de autobús", "Una ayuda que paga la escuela"], "answer": 3, "explain": "Los bonos pueden ayudar a las familias a pagar los gastos escolares en algunos países.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué gasto puede dejar a los niños pobres fuera de la escuela?", "options": ["Cuotas y uniformes", "Libros gratuitos", "Comidas gratuitas", "Transporte gratuito"], "answer": 0, "explain": "Las cuotas y los uniformes pueden ser demasiado caros para algunas familias.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué suele significar la educación gratuita?", "options": ["Vacaciones gratuitas", "Sin cuotas de matrícula", "Coches gratuitos", "Dulces gratuitos"], "answer": 1, "explain": "La educación gratuita suele significar que no hay cuotas de matrícula, aunque puede haber otros gastos.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué año se acordó la Educación para Todos en Jomtien?", "options": ["1948", "1989", "1990", "2000"], "answer": 2, "explain": "La Educación para Todos se acordó en Jomtien en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué buscaba el Marco de Dakar de 2000?", "options": ["Educación solo para adultos", "Ninguna escuela", "Educación solo en las ciudades", "La Educación para Todos para 2015"], "answer": 3, "explain": "El Marco de Dakar fijó objetivos para lograr la Educación para Todos en 2015.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué Objetivo de Desarrollo del Milenio trataba la educación primaria universal?", "options": ["Objetivo 2", "Objetivo 1", "Objetivo 5", "Objetivo 8"], "answer": 0, "explain": "El ODM 2 buscaba la educación primaria universal.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "¿Qué es el Foro Mundial sobre la Educación?", "options": ["Un partido de fútbol entre dos selecciones de Asia", "Una reunión de países y socios sobre educación", "Un concurso de cocina para estudiantes y familias", "Un festival de cine para jóvenes directores y actores"], "answer": 1, "explain": "El Foro Mundial sobre la Educación reúne a países y socios para debatir sobre educación.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué marco respalda la Declaración de Incheon?", "options": ["El Marco Deporte 2030", "El Plan Cocina 2030", "El Marco de Acción Educación 2030", "El Plan Música 2030"], "answer": 2, "explain": "El Marco de Acción Educación 2030 orienta a los países para alcanzar el ODS 4.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "¿En qué año terminaron los Objetivos de Desarrollo del Milenio?", "options": ["2000", "2030", "2010", "2015"], "answer": 3, "explain": "Los ODM terminaron en 2015 y fueron seguidos por los Objetivos Globales.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "¿Qué es el desarrollo infantil temprano?", "options": ["Crecimiento en salud, aprendizaje y bienestar desde el nacimiento", "Crecimiento solo en altura y peso, año tras año", "Aprender solo en la universidad tras muchos años", "Jugar solo al aire libre cada día"], "answer": 0, "explain": "El desarrollo infantil temprano abarca la salud, el aprendizaje y el bienestar desde el nacimiento.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es el «servir y responder» en la primera infancia?", "options": ["Un tipo de partido de tenis sobre césped en verano", "Interacción de ida y vuelta entre un niño y un adulto", "Una forma de devolver juguetes a una tienda benéfica", "Un tipo de sueño largo que los bebés tienen cada tarde"], "answer": 1, "explain": "«Servir y responder» es la interacción de ida y vuelta que construye el cerebro.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué los niños pequeños necesitan adultos que respondan?", "options": ["Los adultos no hacen falta", "Los adultos solo dan órdenes", "Aprenden de ellos el lenguaje y las emociones", "Los adultos deben guardar silencio"], "answer": 2, "explain": "Los adultos que responden ayudan a los niños a desarrollar el lenguaje, los sentimientos y el pensamiento.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué meta del ODS 4 trata sobre la primera infancia?", "options": ["Meta 4.1", "Meta 4.6", "Meta 4.c", "Meta 4.2"], "answer": 3, "explain": "La meta 4.2 trata del desarrollo, la atención y la educación preescolar en la primera infancia.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Para qué sirve la educación preescolar?", "options": ["Preparar a los niños pequeños para la primaria", "Prepararlos para la universidad", "Reemplazar la primaria", "Hacer que los niños trabajen"], "answer": 0, "explain": "La educación preescolar da a los niños pequeños habilidades antes de la primaria.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Por qué es importante la nutrición en la primera infancia?", "options": ["La comida no afecta al cerebro", "Una buena alimentación favorece un crecimiento sano del cerebro", "Los niños solo necesitan dulces", "Los niños deben comer una vez por semana"], "answer": 1, "explain": "Una alimentación sana sostiene el cerebro y el cuerpo durante el rápido crecimiento.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "¿Qué es la alfabetización funcional?", "options": ["Leer solo revistas y cómics por diversión", "Escribir solo poemas y canciones para las funciones escolares", "Leer y escribir lo suficiente para la vida diaria", "Leer solo los números impresos en facturas y boletos"], "answer": 2, "explain": "La alfabetización funcional significa leer y escribir lo suficiente para realizar tareas cotidianas.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Cuáles son las dos habilidades básicas en el centro de la Meta 4.6?", "options": ["Cantar y dibujar", "Cocinar y conducir", "Caminar y correr", "Alfabetización y nociones de cálculo"], "answer": 3, "explain": "La meta 4.6 trata de que jóvenes y adultos logren la alfabetización y las nociones básicas de cálculo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "¿Por qué ayudan las bibliotecas a la alfabetización?", "options": ["Dan acceso gratuito a los libros", "Solo venden libros caros", "Están cerradas para los niños", "Solo guardan muebles"], "answer": 0, "explain": "Las bibliotecas dan a las personas acceso gratuito a libros y espacios de lectura.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué es la fluidez lectora?", "options": ["Leer sin comprender", "Leer con soltura y precisión", "Leer al revés", "Leer solo en silencio"], "answer": 1, "explain": "La fluidez consiste en leer con soltura, precisión y entonación.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "¿Qué es una sala de recursos en una escuela?", "options": ["Una sala que solo guarda muebles viejos", "Una sala que vende uniformes escolares", "Una sala que ofrece apoyo adicional a los estudiantes que lo necesitan", "Una sala que guarda trofeos deportivos"], "answer": 2, "explain": "Una sala de recursos brinda apoyo extra a estudiantes con necesidades de aprendizaje o discapacidad.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué significa el diseño universal para las escuelas?", "options": ["Un solo tipo de edificio para una ciudad", "Edificios sin puertas", "Edificios solo para animales", "Edificios y herramientas que funcionan para todos"], "answer": 3, "explain": "El diseño universal hace que los edificios y las herramientas sean utilizables por el mayor número posible de personas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué a veces los niños con discapacidad necesitan dispositivos de apoyo?", "options": ["Les ayudan a oír, ver o moverse", "Les hacen dormir", "Reemplazan a los maestros", "Impiden que los niños aprendan"], "answer": 0, "explain": "Los dispositivos de apoyo, como audífonos o sillas de ruedas, ayudan a los niños a participar en la escuela.", "src": "UN CRPD (2006), Article 24"}], "6": [{"ch": 0, "q": "¿Qué meta del ODS 4 trata sobre la educación primaria y secundaria gratuita, equitativa y de calidad?", "options": ["Meta 4.1", "Meta 4.2", "Meta 4.4", "Meta 4.7"], "answer": 0, "explain": "La meta 4.1 busca una educación primaria y secundaria gratuita, equitativa y de calidad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta menciona las competencias técnicas y profesionales para el empleo?", "options": ["Meta 4.1", "Meta 4.4", "Meta 4.5", "Meta 4.b"], "answer": 1, "explain": "La meta 4.4 se centra en las competencias, incluidas las técnicas y profesionales, para el empleo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta trata sobre becas para estudiantes de países en desarrollo?", "options": ["Meta 4.a", "Meta 4.c", "Meta 4.b", "Meta 4.6"], "answer": 2, "explain": "La meta 4.b pide más becas para estudiantes de países en desarrollo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta trata sobre la oferta de maestros calificados?", "options": ["Meta 4.b", "Meta 4.2", "Meta 4.7", "Meta 4.c"], "answer": 3, "explain": "La meta 4.c busca aumentar la oferta de maestros calificados.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta trata sobre la construcción y mejora de las instalaciones educativas?", "options": ["Meta 4.a", "Meta 4.1", "Meta 4.3", "Meta 4.5"], "answer": 0, "explain": "La meta 4.a pide instalaciones de aprendizaje seguras, inclusivas y eficaces.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿De qué trata la Meta 4.7?", "options": ["Solo deportes, juegos y forma física durante todo el año escolar", "Conocimientos y habilidades para el desarrollo sostenible y la ciudadanía mundial", "Solo dinero, banca y cuentas de empresas para adultos", "Solo cocina, alimentos y nutrición para el comedor escolar"], "answer": 1, "explain": "La meta 4.7 abarca el desarrollo sostenible, los derechos humanos, la igualdad de género y la ciudadanía mundial.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué meta se centra en el desarrollo infantil temprano y la educación preescolar?", "options": ["Meta 4.1", "Meta 4.6", "Meta 4.2", "Meta 4.c"], "answer": 2, "explain": "La meta 4.2 trata del desarrollo infantil temprano, la atención y la educación preescolar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué significa equitativo en la Meta 4.1?", "options": ["Solo para las familias más ricas del país", "Solo para quienes viven en las grandes ciudades", "Solo para adultos que ya terminaron su escolarización", "Justo para todos, incluidos los más desfavorecidos"], "answer": 3, "explain": "La educación equitativa llega a todos por igual, incluidas las personas en desventaja.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué grupo se menciona en la Meta 4.5 como necesitado de igualdad de acceso?", "options": ["Pueblos indígenas", "Solo las personas con dinero", "Solo las personas de las grandes ciudades", "Solo las personas que hablan un idioma"], "answer": 0, "explain": "La meta 4.5 menciona a las personas con discapacidad, los pueblos indígenas y los niños en situaciones vulnerables.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Por qué es importante la educación primaria gratuita?", "options": ["Aumenta las cuotas escolares", "Elimina una barrera importante para las familias pobres", "Impide que los niños aprendan", "Hace que las escuelas sean menos útiles"], "answer": 1, "explain": "La educación primaria gratuita ayuda a las familias que no pueden pagar las cuotas.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué significa la educación primaria universal?", "options": ["Que solo algunos niños asisten a la primaria", "Que solo los adultos asisten a la primaria", "Que todos los niños pueden asistir a la primaria", "Que la primaria es optativa para todos"], "answer": 2, "explain": "La educación primaria universal significa que todo niño tiene una plaza en la primaria.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 1, "q": "¿Qué niños pueden seguir fuera de la escuela aunque se eliminen las cuotas?", "options": ["Niños muy altos", "Niños a los que les gusta leer", "Niños que nunca comen", "Niños con discapacidad o en zonas remotas"], "answer": 3, "explain": "Los costos no son la única barrera; la discapacidad, la distancia y la discriminación también mantienen a los niños fuera.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Para qué sirve hacer un seguimiento de las tasas de finalización?", "options": ["Para ver si los niños terminan la escuela", "Para elegir los mejores destinos de vacaciones para las excursiones escolares", "Para vender más libros escolares en las tiendas locales", "Para medir el tamaño de los pupitres de cada aula"], "answer": 0, "explain": "Las tasas de finalización muestran si los niños llegan al final de cada nivel.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Por qué importan las tasas de finalización de la secundaria?", "options": ["Muestran cuántos maestros duermen", "Muestran el avance hacia la Meta 4.1", "Muestran el precio de las mochilas escolares", "Muestran el clima"], "answer": 1, "explain": "Las tasas de finalización ayudan a medir el avance hacia el Objetivo 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es la educación de segunda oportunidad?", "options": ["Aprendizaje solo después de terminar una licenciatura", "Aprendizaje solo mediante deportes y juegos en el campo", "Oportunidades de aprendizaje para personas que perdieron la escuela", "Aprendizaje prohibido en la mayoría de países hoy"], "answer": 2, "explain": "La educación de segunda oportunidad ayuda a las personas a recuperar el aprendizaje que se perdieron.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es un programa puente?", "options": ["Un programa para construir puentes sobre ríos y carreteras", "Un programa que cierra cada año las escuelas de aldeas remotas", "Un programa de deportes y juegos de fin de semana para todos", "Un programa que ayuda a los estudiantes a pasar entre niveles o sistemas"], "answer": 3, "explain": "Los programas puente ayudan a los estudiantes a pasar con fluidez de la escuela a la formación.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué abandonan los estudiantes la secundaria inferior?", "options": ["Costos, trabajo y distancia", "Terminan demasiado rápido", "Reciben demasiados premios", "No tienen deberes"], "answer": 0, "explain": "Los costos, el trabajo y la distancia son razones frecuentes para dejar la escuela pronto.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué puede ayudar a un estudiante a volver a la escuela tras dejarla?", "options": ["La expulsión permanente", "Un programa flexible y apoyo", "Verse obligado a repetir el mismo año", "El castigo de los maestros"], "answer": 1, "explain": "Los programas flexibles y el apoyo ayudan a los estudiantes a retomar el aprendizaje.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué tipo de aprendizaje busca la Meta 4.1?", "options": ["Solo buena letra", "Solo buenas notas en deporte", "Aprendizaje pertinente y eficaz", "Solo lectura más rápida"], "answer": 2, "explain": "La meta 4.1 busca resultados de aprendizaje pertinentes y eficaces, no solo la asistencia.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Por qué es más difícil medir el aprendizaje que contar la asistencia?", "options": ["El aprendizaje siempre es fácil de contar", "La asistencia nunca puede contarse", "El aprendizaje se mide solo por la estatura", "El aprendizaje debe evaluarse, no solo contarse"], "answer": 3, "explain": "La asistencia muestra la presencia, pero el aprendizaje requiere evaluar las habilidades y la comprensión.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es un nivel mínimo de competencia?", "options": ["El nivel más bajo que debe alcanzar un estudiante", "El nivel más alto de aprendizaje", "Un nivel solo para maestros", "Un nivel para los edificios escolares"], "answer": 0, "explain": "El nivel mínimo de competencia es la habilidad básica que todo estudiante debe alcanzar.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Por qué muchos países evalúan la lectura y las matemáticas?", "options": ["Para elegir el almuerzo", "Para ver si los estudiantes alcanzan las competencias básicas", "Para comprobar el clima", "Para decidir las vacaciones"], "answer": 1, "explain": "Las pruebas muestran si los estudiantes alcanzan las competencias básicas esenciales.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la equidad en el aprendizaje?", "options": ["Que solo aprendan los mejores estudiantes", "Que todos reciban exactamente el mismo apoyo sin importar sus necesidades", "Que todo estudiante tenga una oportunidad justa de aprender bien", "Que el aprendizaje ocurra solo en algunas escuelas"], "answer": 2, "explain": "La equidad en el aprendizaje significa dar más apoyo donde más se necesita.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué habilidad relaciona las letras con los sonidos para ayudar a leer a los niños?", "options": ["Hacer malabares", "Pintar", "Solo bailar", "La fonética"], "answer": 3, "explain": "La fonética relaciona las letras con los sonidos y ayuda a los niños a leer.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "¿Qué es el pensamiento computacional?", "options": ["Dividir un problema en pasos para resolverlo", "Usar la calculadora para todo", "Adivinar las respuestas", "Evitar los acertijos"], "answer": 0, "explain": "El pensamiento computacional divide los problemas en pasos, una habilidad útil en la programación y más allá.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la educación emprendedora?", "options": ["Aprender a dormir bien y descansar durante el día", "Aprender a iniciar y gestionar un negocio o una idea", "Aprender a evitar el trabajo y quedarse en casa", "Aprender a cantar en un coro cada semana"], "answer": 1, "explain": "La educación emprendedora ayuda a los estudiantes a crear y gestionar sus propias ideas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la ciudadanía mundial?", "options": ["Vivir solo en un pueblo", "Negarse a aprender sobre otros países", "Comprender y preocuparse por el mundo en general", "Ignorar a otras personas"], "answer": 2, "explain": "La ciudadanía mundial anima a las personas a comprender y respetar el mundo en general.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué habilidad ayuda a juzgar si una noticia es verdadera?", "options": ["Hacer malabares", "Jardinería", "Cocina", "Alfabetización mediática"], "answer": 3, "explain": "La alfabetización mediática ayuda a las personas a verificar la información de distintas fuentes.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la colaboración en el aprendizaje?", "options": ["Trabajar juntos para alcanzar una meta compartida", "Trabajar solo para ganar a los demás", "Copiar de los compañeros", "Evitar las tareas en grupo"], "answer": 0, "explain": "La colaboración significa que los estudiantes trabajan juntos y comparten la responsabilidad.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué significa cultura de paz en la Meta 4.7?", "options": ["Vivir separados de los demás", "Convivir sin violencia", "Ganar todas las discusiones", "Ignorar otras culturas"], "answer": 1, "explain": "Una cultura de paz promueve la no violencia, el respeto y la comprensión.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué factor puede mantener a las niñas fuera de la secundaria?", "options": ["El buen clima", "Los libros gratuitos", "El matrimonio temprano y las tareas del hogar", "Demasiados maestros"], "answer": 2, "explain": "El matrimonio temprano y las tareas del hogar pueden impedir que las niñas terminen la secundaria.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué son los datos desagregados?", "options": ["Datos que se mantienen en secreto para siempre", "Datos que nunca se usan para tomar decisiones", "Datos sobre el clima de la región cada día", "Datos separados por grupo, como sexo o discapacidad"], "answer": 3, "explain": "Los datos desagregados ayudan a revelar quién se queda atrás.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Por qué son útiles los datos desagregados?", "options": ["Muestran qué grupos necesitan ayuda", "Ocultan los problemas", "Nunca son precisos", "Solo ayudan a las empresas"], "answer": 0, "explain": "Separar los datos por grupo muestra dónde se necesita apoyo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es la violencia de género relacionada con la escuela?", "options": ["Una regla deportiva sobre cómo pueden placar los jugadores", "Violencia vinculada al género dentro o alrededor de las escuelas", "Un tipo de examen que se hace al final del año", "Un periodo de vacaciones escolares de dos semanas completas"], "answer": 1, "explain": "Esta violencia está vinculada al género y perjudica el aprendizaje de los niños.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué pueden hacer las escuelas para proteger a los niños de la violencia?", "options": ["Ignorar las quejas de los estudiantes y sus padres", "Castigar a los niños que informan de problemas al personal", "Crear sistemas seguros de denuncia y formar al personal", "Cerrar la escuela cada vez que se presenta una queja"], "answer": 2, "explain": "Los sistemas seguros de denuncia y la formación del personal ayudan a proteger a los niños.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es un entorno de aprendizaje seguro?", "options": ["Un lugar sin maestros", "Un lugar sin reglas en absoluto", "Un lugar donde los estudiantes siempre están solos", "Un lugar donde los estudiantes se sienten seguros para aprender"], "answer": 3, "explain": "Los entornos de aprendizaje seguros permiten a los estudiantes aprender sin miedo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Por qué es importante pagar a los maestros de forma justa?", "options": ["Ayuda a mantener a maestros calificados en las escuelas", "Hace que las escuelas sean más pobres", "Reduce el aprendizaje", "Hace que los maestros dejen de preocuparse"], "answer": 0, "explain": "Un salario justo ayuda a retener a maestros capacitados en las escuelas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la rotación docente?", "options": ["Maestros que son ascendidos", "Maestros que abandonan la profesión", "Maestros que toman vacaciones", "Maestros que ganan premios"], "answer": 1, "explain": "La rotación significa que los maestros abandonan la profesión, lo que perjudica el aprendizaje.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es una trayectoria profesional docente?", "options": ["Un camino solo hasta la puerta de la escuela", "Un camino solo para estudiantes", "Un camino de crecimiento y ascenso", "Un camino sin salario"], "answer": 2, "explain": "Las trayectorias profesionales ofrecen a los maestros formas de desarrollarse y avanzar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el desarrollo profesional continuo para los maestros?", "options": ["Un solo día de formación en toda la vida", "Ninguna formación después de graduarse", "Formación solo para los directores", "Formación continua durante la carrera docente"], "answer": 3, "explain": "El desarrollo continuo mantiene a los maestros capacitados a lo largo de su carrera.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué importa la calidad de los maestros?", "options": ["Es uno de los factores clave en cómo aprenden los niños", "No tiene ningún efecto en cómo aprenden los niños", "Solo importa para el deporte y la educación física", "Solo importa por el aspecto del edificio escolar"], "answer": 0, "explain": "La calidad docente es uno de los factores clave del aprendizaje de los niños.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué a menudo a las zonas rurales les cuesta retener maestros?", "options": ["Las zonas rurales tienen demasiados maestros", "Muy pocos maestros quieren trabajar allí", "Los maestros prefieren las vacaciones", "Los maestros nunca viajan"], "answer": 1, "explain": "Las zonas rurales suelen tener dificultades para atraer y retener suficientes maestros.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es la financiación nacional para la educación?", "options": ["Dinero procedente de la Luna", "Dinero solo de clubes deportivos", "Dinero que un país recauda por sí mismo para las escuelas", "Dinero solo de uniformes escolares"], "answer": 2, "explain": "La financiación nacional es el dinero que un país recauda con sus propios impuestos e ingresos.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué porcentaje del PIB sugiere el Marco de Incheon para la educación?", "options": ["Del 0,5 al 1 por ciento", "Del 20 al 30 por ciento", "Del 50 al 60 por ciento", "Del 4 al 6 por ciento"], "answer": 3, "explain": "El Marco de Incheon sugiere del 4 al 6 % del PIB y/o del 15 al 20 % del gasto público.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué porcentaje del gasto público sugiere el Marco de Incheon para la educación?", "options": ["Del 15 al 20 por ciento", "Del 1 al 2 por ciento", "Del 40 al 50 por ciento", "Del 90 al 100 por ciento"], "answer": 0, "explain": "Incheon sugiere entre el 15 y el 20 % del gasto público total en educación.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué es una brecha de financiación en la educación?", "options": ["Dinero ahorrado para las vacaciones familiares y los viajes de verano", "La diferencia entre el dinero necesario y el disponible", "La distancia entre dos edificios escolares de la ciudad", "Dinero que hoy no tiene ningún uso real en ninguna escuela"], "answer": 1, "explain": "Una brecha de financiación es la cantidad que aún falta para cubrir los objetivos educativos.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué las escuelas de zonas pobres suelen tener menos dinero?", "options": ["Tienen demasiados estudiantes", "Eligen no recibir dinero", "Menos ingresos fiscales y financiación desigual", "No necesitan libros"], "answer": 2, "explain": "La financiación desigual puede dejar a las zonas más pobres con menos recursos.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "¿Qué es la financiación por alumno?", "options": ["Dinero que se entrega para el coche de cada maestro", "Dinero que se entrega para cada autobús escolar", "Dinero que se entrega para cada trofeo deportivo", "Dinero que se entrega a las escuelas por cada estudiante"], "answer": 3, "explain": "La financiación por alumno paga a las escuelas según el número de estudiantes.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué objetivos reemplazaron a los Objetivos de Desarrollo del Milenio?", "options": ["Los Objetivos de Desarrollo Sostenible", "Los Objetivos Olímpicos", "Los Objetivos Comerciales", "Los Objetivos Espaciales"], "answer": 0, "explain": "Los ODS (Objetivos Globales) reemplazaron a los ODM en 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿En qué año se adoptó el Marco de Acción Educación 2030?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "El Marco de Acción Educación 2030 se adoptó en 2015.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "¿Qué dijo la declaración de 1948 sobre la educación?", "options": ["Las escuelas deben cerrarse", "La educación es solo para adultos", "Todas las personas tienen derecho a la educación", "La educación es un lujo"], "answer": 2, "explain": "La Declaración Universal de Derechos Humanos afirma que la educación es un derecho humano.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿Qué dice el artículo 26 de la Declaración Universal sobre la educación primaria?", "options": ["Debe ser cara", "Debe ser optativa para todos", "Debe ser solo para niños", "Debe ser gratuita y obligatoria"], "answer": 3, "explain": "El artículo 26 establece que la educación elemental debe ser obligatoria y gratuita.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿Qué ocurrió en el Foro Mundial sobre la Educación de 2015 en Incheon?", "options": ["Los países acordaron objetivos educativos para 2030", "Los países cerraron todas las escuelas", "Los países acordaron un nuevo deporte", "Los países pusieron fin a los programas de alfabetización"], "answer": 0, "explain": "La Declaración de Incheon fijó los objetivos educativos para 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Qué pidió la conferencia de Jomtien de 1990?", "options": ["Educación solo para los ricos", "Educación para todos", "Educación solo en inglés", "Escuelas sin maestros"], "answer": 1, "explain": "La conferencia de Jomtien de 1990 pidió educación para todos.", "src": "UNESCO"}, {"ch": 9, "q": "¿Por qué se relaciona el cuidado de la primera infancia con el aprendizaje posterior?", "options": ["Los primeros años no tienen relación", "Solo importa el aprendizaje de los adultos", "Las habilidades tempranas favorecen el éxito escolar posterior", "El aprendizaje posterior no tiene relación"], "answer": 2, "explain": "Unas bases tempranas sólidas facilitan el aprendizaje posterior.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es la preparación para la escuela?", "options": ["Estar listo para dejar la escuela", "Ser lo bastante alto para los pupitres", "Saber conducir", "Estar listo para aprender al comenzar la escuela"], "answer": 3, "explain": "La preparación escolar significa que los niños tienen las habilidades y la salud para empezar la escuela.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué papel tiene el juego en el aprendizaje temprano?", "options": ["Desarrolla el pensamiento, el lenguaje y las habilidades sociales", "No tiene ningún papel", "Reemplaza todo el aprendizaje para siempre", "Solo hace perder el tiempo"], "answer": 0, "explain": "El juego ayuda a los niños a desarrollar el pensamiento, el lenguaje y las habilidades sociales.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué necesitan los bebés una atención que responda a sus necesidades?", "options": ["Los malcría", "Ayuda al desarrollo de su cerebro y sus emociones", "No es necesaria", "Solo les da sueño"], "answer": 1, "explain": "La atención que responde a sus necesidades favorece un desarrollo sano del cerebro y las emociones.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué son los primeros mil días?", "options": ["El primer día de clase", "La primera semana de vacaciones", "El periodo desde el embarazo hasta los dos años", "El primer año de universidad"], "answer": 2, "explain": "Los primeros mil días, desde el embarazo hasta los dos años, son muy importantes para el desarrollo.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué actividad de la primera infancia favorece el crecimiento del cerebro?", "options": ["Silencio total", "Solo ver pantallas todo el tiempo", "Dejarlos solos durante horas", "Hablar y leer con los niños"], "answer": 3, "explain": "Hablar y leer con los niños favorece el lenguaje y el crecimiento del cerebro.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es la postalfabetización?", "options": ["Aprendizaje que se basa en la alfabetización básica", "Leer solo cómics", "La alfabetización solo para maestros", "Leer solo revistas"], "answer": 0, "explain": "La postalfabetización ayuda a las personas a mantener y ampliar sus habilidades básicas de lectura y escritura.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué es la alfabetización para todos?", "options": ["Alfabetización solo para niños", "Oportunidades de alfabetización para todos", "Alfabetización solo para personas ricas", "Alfabetización solo en un idioma"], "answer": 1, "explain": "La alfabetización para todos busca dar a todos la oportunidad de leer y escribir.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Por qué son útiles los programas de alfabetización multilingüe?", "options": ["Impiden aprender una segunda lengua", "Eliminan la necesidad de libros", "Ayudan a los estudiantes a leer primero en su propia lengua", "Solo funcionan en el deporte"], "answer": 2, "explain": "Aprender a leer en una lengua que el niño entiende favorece el aprendizaje posterior.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "¿Cuál es la relación entre alfabetización y salud?", "options": ["Leer hace enfermar a las personas", "No existe ninguna relación", "La salud depende solo del deporte", "Leer ayuda a las personas a entender los consejos de salud"], "answer": 3, "explain": "La alfabetización ayuda a leer las etiquetas de los medicamentos y las orientaciones sanitarias.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué busca una campaña de alfabetización?", "options": ["Enseñar a leer y escribir a muchas personas", "Vender más periódicos a las familias ocupadas cada semana", "Impedir que las personas lean libros y revistas", "Construir más carreteras y puentes en todo el país"], "answer": 0, "explain": "Una campaña de alfabetización trabaja para reducir el analfabetismo en las comunidades.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué habilidad es básica para la alfabetización?", "options": ["Hacer malabares con pelotas", "Reconocer las letras y sus sonidos", "Conducir un bus", "Cocinar arroz"], "answer": 1, "explain": "Reconocer las letras y sus sonidos es una habilidad básica de la alfabetización.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "¿Qué garantiza la Meta 4.5 para los grupos vulnerables?", "options": ["Acceso solo para los mejores estudiantes", "Acceso solo para familias ricas", "Acceso igualitario a la educación", "Acceso solo en las grandes ciudades"], "answer": 2, "explain": "La meta 4.5 garantiza el acceso igualitario para los grupos vulnerables.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Qué es un plan educativo individual para un estudiante?", "options": ["Un plan para las vacaciones", "Un plan para evitar la clase", "Un plan para trasladar a los estudiantes a otra escuela", "Un plan adaptado a las necesidades de un estudiante"], "answer": 3, "explain": "Los planes educativos individuales ayudan a los maestros a atender las necesidades específicas de cada estudiante.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué exige a las escuelas el ajuste razonable?", "options": ["Adaptaciones que ayudan a los estudiantes a participar", "Ignorar las necesidades de los estudiantes", "Cobrar cuotas adicionales", "Eliminar todo apoyo"], "answer": 0, "explain": "Las escuelas deben hacer ajustes razonables para que los alumnos con discapacidad puedan participar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué son importantes los materiales accesibles?", "options": ["Dificultan el aprendizaje para todos", "Permiten que todos los estudiantes usen el mismo contenido", "Son solo para los maestros", "Reemplazan a los maestros"], "answer": 1, "explain": "Los materiales accesibles, como la letra grande o el braille, ayudan a los estudiantes a seguir las lecciones.", "src": "UN CRPD (2006), Article 24"}], "7": [{"ch": 0, "q": "¿Qué Objetivo Global trata sobre la acción por el clima?", "options": ["Objetivo 13", "Objetivo 3", "Objetivo 14", "Objetivo 10"], "answer": 0, "explain": "El Objetivo 13 es Acción por el Clima.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta trata sobre eliminar las disparidades de género en la educación?", "options": ["Meta 4.1", "Meta 4.5", "Meta 4.4", "Meta 4.a"], "answer": 1, "explain": "La meta 4.5 busca eliminar las disparidades de género y garantizar el acceso igualitario.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Por qué es importante medir los resultados de aprendizaje?", "options": ["Solo cuenta cuántos edificios escolares hay en la ciudad", "Fija el precio de los libros escolares en cada tienda", "Muestra lo que los niños realmente aprenden, no solo la matrícula", "Mide la altura y el peso de cada alumno"], "answer": 2, "explain": "Hacer seguimiento de los resultados de aprendizaje muestra si los niños realmente aprenden.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "¿Cuál es la finalidad de los indicadores del ODS 4?", "options": ["Elegir los colores de la escuela", "Clasificar a los maestros por su estatura", "Fijar las fechas de vacaciones", "Medir el avance de cada meta"], "answer": 3, "explain": "Los indicadores miden el avance hacia cada meta.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Por qué el Objetivo 4 está vinculado a otros Objetivos Globales?", "options": ["La educación apoya la salud, el empleo y la igualdad", "La educación no tiene vínculos con otros objetivos", "La educación solo importa para el deporte", "La educación es solo para las ciudades"], "answer": 0, "explain": "La educación favorece el avance en muchos objetivos, como la salud, el trabajo y la igualdad de género.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta busca la alfabetización y la competencia matemática de jóvenes y adultos?", "options": ["Meta 4.1", "Meta 4.6", "Meta 4.5", "Meta 4.c"], "answer": 1, "explain": "La meta 4.6 busca la alfabetización y la competencia matemática de todos los jóvenes y de una parte considerable de los adultos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué mide el indicador 4.1.1?", "options": ["El número de autobuses escolares en cada carretera principal", "El precio medio de los uniformes escolares en cada ciudad", "Los niños que alcanzan el nivel mínimo de competencia en lectura y matemáticas", "La altura media de cada aula de la escuela"], "answer": 2, "explain": "El indicador 4.1.1 mide la proporción de niños que alcanzan los niveles mínimos de competencia.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "¿Qué es la brecha digital?", "options": ["Una separación entre dos aulas del mismo gran edificio escolar", "Una pausa entre dos clases largas en un día escolar ajetreado", "Una división entre dos idiomas que solo se hablan en casa", "La diferencia entre quienes tienen acceso a internet y quienes no"], "answer": 3, "explain": "La brecha digital es la diferencia en el acceso a dispositivos e internet.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué la educación a distancia puede ayudar a algunos estudiantes?", "options": ["Llega a quienes viven en zonas remotas", "Reemplaza a todos los maestros", "Hace que se deje de aprender", "Es solo para adultos"], "answer": 0, "explain": "La educación a distancia y en línea puede llegar a personas que viven lejos de las escuelas.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es un centro de aprendizaje en una comunidad remota?", "options": ["Un centro comercial con muchas tiendas y cafeterías", "Un espacio donde los estudiantes pueden estudiar con apoyo", "Una sala de hospital donde los pacientes descansan y se recuperan", "Un estadio deportivo para grandes partidos de fútbol"], "answer": 1, "explain": "Los centros de aprendizaje dan a los estudiantes de zonas remotas un lugar para estudiar y recibir ayuda.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es el mapeo escolar?", "options": ["Dibujar mapas de rutas de vacaciones para viajes familiares al extranjero", "Trazar los campos deportivos usados en los partidos escolares", "Identificar dónde hacen falta escuelas y quién puede llegar a ellas", "Diseñar logotipos y carteles nuevos para cada escuela"], "answer": 2, "explain": "El mapeo escolar ayuda a los gobiernos a planificar dónde se necesitan nuevas escuelas y transporte.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué barrera frecuente impide asistir a la escuela en las ciudades?", "options": ["Demasiados espacios verdes", "Demasiadas bibliotecas", "Demasiados maestros", "El alto costo de vida para las familias pobres"], "answer": 3, "explain": "En las ciudades, las familias pobres pueden tener dificultades con el transporte y el costo de vida.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué significa acceso para los estudiantes con discapacidad?", "options": ["Poder entrar y usar las instalaciones escolares", "Poder dejar la escuela en cualquier momento", "Poder saltarse las clases", "Poder evitar los exámenes"], "answer": 0, "explain": "Acceso significa que los estudiantes con discapacidad pueden entrar y usar los espacios escolares y los materiales de aprendizaje.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "¿Qué es una brecha de finalización?", "options": ["Un hueco en una pared de la escuela que necesita reparación urgente", "Una diferencia en la finalización de la escuela entre grupos", "Un espacio entre dos pupitres en un aula abarrotada", "Un hueco en el horario escolar todas las tardes de viernes"], "answer": 1, "explain": "Una brecha de finalización muestra que algunos grupos terminan la escuela con menos frecuencia que otros.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Por qué los niños de familias con más ingresos suelen terminar más la escuela?", "options": ["Sus hijos son menos inteligentes", "Sus hijos nunca hacen exámenes", "Sus familias pueden pagar los costos y el transporte", "Sus hijos evitan los deberes"], "answer": 2, "explain": "Los ingresos ayudan a las familias a cubrir costos y transporte, lo que hace más probable terminar.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué mide la tasa de supervivencia hasta el último grado?", "options": ["La proporción que gana carreras", "La proporción que tiene bicicleta", "La proporción que habla dos idiomas", "La proporción de niños que llegan al último grado"], "answer": 3, "explain": "La tasa de supervivencia mide cuántos estudiantes llegan al último grado de un nivel.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué el matrimonio infantil afecta la finalización escolar?", "options": ["Puede poner fin a la escolarización de una niña", "Mejora la asistencia escolar", "No tiene ningún efecto", "Afecta solo a los niños"], "answer": 0, "explain": "El matrimonio temprano suele interrumpir la educación de las niñas antes de que terminen la escuela.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "¿Qué es la reincorporación a la escuela?", "options": ["Entrar a una escuela por primera vez", "Volver a la escuela después de haberla dejado", "Dejar la escuela para siempre", "Cambiar el uniforme escolar"], "answer": 1, "explain": "Las políticas de reincorporación ayudan a los jóvenes a volver a la escuela tras abandonarla.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la transición de la escuela al trabajo?", "options": ["Cambiar de edificio escolar", "Cambiar de maestros", "Pasar de la escuela al empleo o la formación", "Mudarse solo a otro país"], "answer": 2, "explain": "La transición de la escuela al trabajo es el paso de la educación al empleo o la formación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Qué es la pérdida de aprendizaje?", "options": ["Perder el estuche en el autobús cada mañana", "Olvidar la contraseña del ordenador de la escuela", "Perder un partido de fútbol contra una escuela rival", "Perder habilidades tras una larga interrupción del aprendizaje"], "answer": 3, "explain": "La pérdida de aprendizaje significa que las habilidades se desvanecen cuando las escuelas cierran o el aprendizaje se interrumpe.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué ayuda a los estudiantes a recuperarse de la pérdida de aprendizaje?", "options": ["Las tutorías específicas y las clases de recuperación", "Dar menos clases", "Eliminar todos los exámenes", "Solo vacaciones más largas"], "answer": 0, "explain": "El apoyo específico ayuda a los estudiantes a recuperar lo que se perdieron.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es el aprendizaje por dominio?", "options": ["Los estudiantes nunca repiten un tema", "Los estudiantes avanzan solo después de comprender un tema", "Los estudiantes se saltan todos los temas difíciles", "Los estudiantes solo memorizan respuestas"], "answer": 1, "explain": "El aprendizaje por dominio asegura que los estudiantes comprendan antes de avanzar.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué es importante la lengua de instrucción?", "options": ["No tiene ningún efecto", "Solo debería usarse un idioma", "Los estudiantes entienden mejor las clases en un idioma que conocen", "Solo importa en el deporte"], "answer": 2, "explain": "Usar un idioma que los estudiantes comprenden favorece el aprendizaje.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "¿Qué es la educación bilingüe?", "options": ["Enseñar solo con juegos", "Enseñar sin ningún idioma", "Enseñar en un solo idioma para la danza", "Enseñar en dos idiomas"], "answer": 3, "explain": "La educación bilingüe usa dos idiomas para ayudar a los estudiantes a comprender y crecer.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "¿Qué es la lectura crítica?", "options": ["Cuestionar y evaluar un texto", "Leer sin pensar", "Leer solo el título", "Leer solo las imágenes"], "answer": 0, "explain": "La lectura crítica se pregunta si el texto es preciso, justo y está bien argumentado.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué significa TIC en educación?", "options": ["Fondo Internacional de Cocina", "Tecnologías de la información y la comunicación", "Interesante Recorrido por el Campus", "Importante Prueba del Aula"], "answer": 1, "explain": "TIC significa tecnologías de la información y la comunicación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la educación profesional?", "options": ["Educación sin habilidades prácticas ni formación práctica", "Educación solo para quienes ya trabajan como maestros", "La educación que prepara para oficios o empleos específicos", "Educación solo para estudiantes que van a la universidad"], "answer": 2, "explain": "La educación profesional desarrolla habilidades prácticas para empleos concretos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué significa EFTP?", "options": ["Examen en video de maestros", "Herramienta total de educación visual", "Tema de educación en video terciaria", "Educación y formación técnica y profesional"], "answer": 3, "explain": "EFTP significa educación y formación técnica y profesional.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué se enseña programación en algunas escuelas?", "options": ["Desarrolla la resolución de problemas y las habilidades digitales", "Reemplaza a todas las demás asignaturas", "Es solo para jugar", "Hace que se deje de aprender"], "answer": 0, "explain": "La programación enseña lógica y habilidades digitales útiles en muchos empleos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la ciudadanía digital?", "options": ["Usar la tecnología para dañar a otros", "Usar la tecnología de forma segura, responsable y respetuosa", "Evitar toda tecnología", "Usar la tecnología solo para jugar"], "answer": 1, "explain": "La ciudadanía digital significa comportarse bien en línea y respetar a los demás.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es una competencia emergente?", "options": ["Una habilidad que ya no se necesita", "Una habilidad solo para lenguas antiguas", "Una habilidad que cobra importancia en nuevos empleos", "Una habilidad para dormir"], "answer": 2, "explain": "Las competencias emergentes cobran importancia a medida que surgen nuevos tipos de trabajo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es la brecha de género en las STEM?", "options": ["Hoy las niñas estudian más matemáticas que los niños en casi todos los países", "No existe ninguna brecha en las clases de ciencias en ningún lugar", "Solo a los niños se les permite estudiar materias científicas en la escuela", "Hay menos niñas que niños que estudian ciencias, tecnología, ingeniería y matemáticas"], "answer": 3, "explain": "Muchos países muestran menos niñas en las asignaturas STEM, lo que limita sus opciones.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Por qué pueden importar las maestras en algunos lugares?", "options": ["Pueden ser modelos a seguir y ayudar a que las niñas permanezcan en la escuela", "No se necesitan en ninguna escuela del mundo", "Solo enseñan deportes y actividades físicas al aire libre", "Impiden que los niños aprendan cualquier materia nueva"], "answer": 0, "explain": "Las maestras pueden animar a las niñas y ayudar a crear entornos seguros.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué es una escuela que responde al género?", "options": ["Una escuela solo para niñas", "Una escuela que atiende las necesidades de niñas y niños", "Una escuela que ignora el género", "Una escuela sin baños"], "answer": 1, "explain": "Las escuelas que responden al género planifican según las distintas necesidades de niñas y niños.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué significa marginado?", "options": ["Colocado en el centro de atención", "Recibir dinero extra automáticamente", "Empujado al margen de la sociedad y dejado fuera", "Tener derecho a hacer todas las reglas"], "answer": 2, "explain": "Los grupos marginados suelen quedar excluidos de la educación y de las oportunidades.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Por qué corren riesgo de quedarse atrás los hablantes de lenguas minoritarias?", "options": ["Siempre son los mejores estudiantes", "Su lengua nunca se habla", "Nunca van a la escuela", "Es posible que las escuelas no enseñen en su lengua"], "answer": 3, "explain": "Cuando las clases usan un idioma que los niños no hablan, muchos se quedan atrás.", "src": "UNESCO, International Mother Language Day"}, {"ch": 5, "q": "¿Qué es la acción afirmativa en educación?", "options": ["Apoyo adicional a grupos que enfrentan desventajas", "Castigar a los grupos que tienen buenos resultados", "Ignorar todas las diferencias", "Cerrar escuelas para algunos grupos"], "answer": 0, "explain": "La acción afirmativa ofrece apoyo adicional para ayudar a los grupos desfavorecidos a ponerse al día.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa estatus socioeconómico?", "options": ["Un tipo de examen escolar", "La posición social y económica de una persona", "El color de una mochila escolar", "Un número de victorias deportivas"], "answer": 1, "explain": "El estatus socioeconómico describe los ingresos, la educación y la posición social de una familia.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "¿Qué es una brecha docente?", "options": ["Maestros extra que no hacen nada", "Maestros sin clases", "El número de maestros adicionales necesarios para cubrir la demanda", "Maestros que nunca salen de la escuela"], "answer": 2, "explain": "La brecha docente es el número de maestros adicionales necesarios para alcanzar las metas educativas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué la oferta de maestros es un desafío en muchos países?", "options": ["Demasiadas personas quieren enseñar", "Nunca se necesitan maestros", "Los maestros solo tienen demasiados alumnos", "Muy pocas personas se forman o permanecen como docentes"], "answer": 3, "explain": "La escasez se debe a muy pocos candidatos en formación, salarios bajos y alta rotación.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el estatus docente?", "options": ["Cómo se valora a los maestros en la sociedad", "La estatura de un maestro", "El coche de un maestro", "La mochila de un maestro"], "answer": 0, "explain": "El estatus docente influye en que las personas elijan la docencia y permanezcan en ella.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un maestro en una zona de crisis?", "options": ["Un maestro que solo trabaja en las ciudades", "Un maestro que trabaja donde han golpeado un conflicto o un desastre", "Un maestro que nunca enseña", "Un maestro que solo trabaja en vacaciones"], "answer": 1, "explain": "Los maestros en zonas de crisis trabajan en condiciones difíciles para que los niños sigan aprendiendo.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué algunos maestros abandonan la profesión?", "options": ["Salarios demasiado altos y demasiadas vacaciones pagadas", "Muy poco trabajo y demasiados días libres", "Salarios bajos, cargas de trabajo pesadas o poco apoyo", "Demasiados premios y demasiados elogios"], "answer": 2, "explain": "Los salarios bajos y las cargas de trabajo pesadas expulsan a algunos maestros de la profesión.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la carga de trabajo de un maestro?", "options": ["El peso de la mochila de un maestro", "El número de vacaciones de los maestros", "El precio del coche de un maestro", "La cantidad de trabajo que tiene que hacer un maestro"], "answer": 3, "explain": "La carga de trabajo incluye la enseñanza, la planificación, la corrección y otras tareas.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Para qué se usa la tasa de pobreza de aprendizaje?", "options": ["Para hacer seguimiento a los niños que no saben leer a los diez años", "Para hacer seguimiento a los edificios escolares", "Para hacer seguimiento al precio de los bolígrafos", "Para hacer seguimiento a las vacaciones de los maestros"], "answer": 0, "explain": "La tasa de pobreza de aprendizaje muestra la proporción de niños que no pueden leer un texto sencillo a los diez años.", "src": "World Bank, learning poverty"}, {"ch": 7, "q": "¿Por qué es importante el gasto público en educación?", "options": ["No tiene ninguna finalidad", "Paga a los maestros, los edificios y los materiales", "Paga solo las vacaciones", "Solo compra equipo deportivo"], "answer": 1, "explain": "El dinero público mantiene las escuelas en funcionamiento y hace que el aprendizaje esté disponible para todos.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la ejecución presupuestaria en educación?", "options": ["Cancelar todas las clases", "Suspender todas las excursiones escolares", "Gastar el dinero según lo planeado", "Vender los edificios escolares"], "answer": 2, "explain": "La ejecución presupuestaria comprueba si el dinero previsto para educación se gasta realmente.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la corresponsabilidad de costos en educación?", "options": ["Escuelas que pagan a las familias", "Maestros que pagan a los estudiantes", "Estudiantes que pagan a los maestros", "Familias que pagan parte del costo de la escuela"], "answer": 3, "explain": "La corresponsabilidad de costos significa que las familias contribuyen, lo que puede limitar el acceso de los niños más pobres.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es un impuesto educativo?", "options": ["Un impuesto destinado a financiar las escuelas", "Una tarifa solo por hacer exámenes", "Un impuesto solo sobre los libros escolares", "Una multa por faltar a la escuela"], "answer": 0, "explain": "Algunos países recaudan un impuesto educativo para financiar las escuelas.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué las escuelas necesitan reparaciones periódicas?", "options": ["Los edificios nuevos siempre necesitan reparaciones", "Los edificios antiguos pueden volverse inseguros", "Las reparaciones hacen que las escuelas sean más grandes", "Las reparaciones impiden que los niños aprendan"], "answer": 1, "explain": "Las reparaciones periódicas mantienen los edificios seguros y adecuados para aprender.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la relación calidad-precio en el gasto educativo?", "options": ["Gastar la mayor cantidad de dinero posible cada año", "Gastar dinero solo en equipo deportivo", "Obtener buenos resultados de aprendizaje por el dinero gastado", "No gastar nada de dinero cada año"], "answer": 2, "explain": "La relación calidad-precio significa gastar con criterio para mejorar el aprendizaje.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué conferencia adoptó la Agenda 2030?", "options": ["Una reunión regional celebrada en Tokio, 2005", "Una reunión en El Cairo sobre población, 1994", "Una conferencia en Lima sobre agricultura, 2014", "La cumbre de la ONU en Nueva York, 2015"], "answer": 3, "explain": "Los líderes mundiales adoptaron la Agenda 2030 en una cumbre de la ONU en Nueva York en 2015.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿En qué año se celebró la Conferencia Mundial sobre Educación para Todos de Jomtien?", "options": ["1990", "1975", "2005", "2020"], "answer": 0, "explain": "La conferencia de Jomtien se celebró en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué año tuvo lugar el Foro Mundial sobre la Educación de Dakar?", "options": ["1995", "2000", "2010", "2015"], "answer": 1, "explain": "El Foro Mundial sobre la Educación de Dakar tuvo lugar en el año 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿En qué se centró la declaración de Jomtien de 1990?", "options": ["Solo en el aprendizaje universitario", "Solo en el deporte", "En satisfacer las necesidades básicas de aprendizaje de todos", "Solo en los exámenes"], "answer": 2, "explain": "La declaración de 1990 se centró en satisfacer las necesidades básicas de aprendizaje de todas las personas.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué se centraron los ODM en educación?", "options": ["En coches gratis", "Solo en becas universitarias", "En ligas deportivas", "En la educación primaria universal"], "answer": 3, "explain": "El ODM 2 se centró en la educación primaria universal.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "¿Cuál es la finalidad de un informe mundial sobre educación?", "options": ["Hacer seguimiento del avance y compartir evidencias", "Cerrar escuelas", "Elegir vacaciones", "Vender libros de texto"], "answer": 0, "explain": "Los informes mundiales hacen seguimiento del avance y comparten evidencias para orientar las políticas.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "¿Qué abarca el desarrollo infantil en los primeros años?", "options": ["Solo el crecimiento en tamaño", "El crecimiento del cuerpo, la mente y las habilidades sociales", "Solo el crecimiento en dinero", "Solo el crecimiento en velocidad"], "answer": 1, "explain": "El desarrollo infantil abarca el crecimiento físico, el pensamiento, el lenguaje y lo social.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es el estrés tóxico en la primera infancia?", "options": ["Un tipo de alimento saludable que los niños comen a diario", "Un juego divertido que los niños suelen practicar en el parque", "Un estrés intenso y prolongado que puede dañar el desarrollo", "Una asignatura escolar para niños pequeños"], "answer": 2, "explain": "El estrés tóxico puede dañar el cerebro en desarrollo cuando es prolongado y no recibe apoyo.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué los programas de primera infancia ayudan a los niños desfavorecidos?", "options": ["Crean brechas", "Son solo para niños ricos", "Reemplazan a las familias", "Reducen las brechas antes de que empiece la escuela"], "answer": 3, "explain": "Los programas tempranos pueden igualar el punto de partida de los niños de hogares desfavorecidos.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué aporta el apoyo a la crianza al aprendizaje temprano?", "options": ["Ayuda a los padres a apoyar el aprendizaje de sus hijos", "Reemplaza por completo a los padres en la vida de sus hijos", "Impide que los niños aprendan en casa y en la escuela", "Solo compra juguetes para que jueguen los niños"], "answer": 0, "explain": "El apoyo a la crianza da a los adultos ideas para hablar, jugar y cuidar a los niños pequeños.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué incluye un entorno de aprendizaje en el hogar?", "options": ["Solo la televisión", "Libros, conversación y juego en casa", "Solo el silencio", "Solo los deberes"], "answer": 1, "explain": "Un entorno de aprendizaje familiar favorable fomenta la lectura, la conversación y el juego.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué es importante la atención en la primera infancia para las niñas?", "options": ["No es necesaria para las niñas", "Solo importa después de la escuela", "Las ayuda a empezar la escuela preparadas para aprender", "Solo importa para los niños"], "answer": 2, "explain": "La atención temprana favorece la salud, el aprendizaje y la confianza de las niñas.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "¿Qué es la alfabetización familiar?", "options": ["Alfabetización solo para los abuelos", "Leer sin los niños", "Escribir solo para las personas mayores", "Padres e hijos que aprenden a leer juntos"], "answer": 3, "explain": "La alfabetización familiar ayuda a padres e hijos a desarrollar juntos sus habilidades de lectura.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es la brecha de lectura entre países?", "options": ["Diferencias en los niveles de lectura entre países", "El espacio entre los libros de las estanterías", "El hueco entre los pupitres", "La distancia entre dos escuelas"], "answer": 0, "explain": "La brecha de lectura muestra cuánto difieren los niveles de lectura entre lugares.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es la fluidez en la escritura?", "options": ["Escribir sin palabras", "Escribir con claridad y rapidez", "Escribir solo en mayúsculas", "Escribir solo con ordenador"], "answer": 1, "explain": "La fluidez en la escritura es escribir con soltura para expresar las ideas.", "src": "UNESCO"}, {"ch": 10, "q": "¿Qué es el lenguaje oral?", "options": ["Solo el lenguaje escrito", "El lenguaje usado solo en los libros", "El lenguaje hablado", "El lenguaje usado solo por los animales"], "answer": 2, "explain": "El lenguaje oral es el idioma hablado que los niños aprenden primero.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Por qué el lenguaje oral es importante antes de leer?", "options": ["No tiene relación con la lectura", "Impide que los niños lean", "Es solo para cantar", "Construye el vocabulario que sustenta la lectura"], "answer": 3, "explain": "Un buen lenguaje oral ayuda a los niños a entender lo que leen.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Cuál es la finalidad del Día Internacional de la Alfabetización?", "options": ["Sensibilizar sobre la alfabetización y sus beneficios", "Cerrar todas las bibliotecas del país", "Vender más libros en las tiendas de todo el país", "Suspender todas las clases de lectura en primaria"], "answer": 0, "explain": "El Día Internacional de la Alfabetización sensibiliza sobre la alfabetización y lo que hace posible.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "¿Qué pide la educación inclusiva a los maestros?", "options": ["Enseñar solo a los mejores estudiantes", "Adaptar las clases a los distintos estudiantes", "Ignorar a los estudiantes que necesitan ayuda", "Negarse a recibir formación adicional"], "answer": 1, "explain": "La enseñanza inclusiva adapta los métodos para que cada estudiante pueda participar.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es el diseño universal para el aprendizaje?", "options": ["Un diseño de edificios escolares sin ninguna aula", "Una enseñanza que usa una sola vía para todos los estudiantes", "Una enseñanza pensada para funcionar con muchos tipos de estudiantes", "Un tipo de uniforme escolar que todos los alumnos usan a diario"], "answer": 2, "explain": "El diseño universal para el aprendizaje ofrece múltiples formas de aprender y demostrar lo comprendido.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué los estudiantes con discapacidad necesitan ajustes razonables?", "options": ["Para librarse del trabajo", "Para evitar los exámenes", "Para tener vacaciones", "Para participar en las clases en igualdad de condiciones"], "answer": 3, "explain": "Los ajustes permiten a los estudiantes con discapacidad participar en igualdad de condiciones.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué hace un intérprete de lengua de signos en clase?", "options": ["Traduce entre la lengua de signos y la lengua hablada", "Enseña danza y música a toda la clase", "Vende libros y material de papelería a los estudiantes", "Conduce el autobús escolar en la ruta de la mañana"], "answer": 0, "explain": "Los intérpretes ayudan a los estudiantes sordos a seguir las clases.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿En qué ayuda el braille a los estudiantes?", "options": ["A escuchar música", "A leer con el tacto", "A nadar más rápido", "A crecer más"], "answer": 1, "explain": "El braille permite a las personas ciegas leer tocando los puntos en relieve.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué la inclusión beneficia a todos en una escuela?", "options": ["Hace las clases más pequeñas sin motivo", "Reduce el aprendizaje", "Genera comprensión y respeto", "Impide las amistades"], "answer": 2, "explain": "Las aulas inclusivas enseñan respeto y comprensión entre todos los estudiantes.", "src": "UN CRPD (2006), Article 24"}], "8": [{"ch": 0, "q": "¿Cuántas metas del ODS 4 tratan sobre los medios de implementación?", "options": ["Tres", "Siete", "Diez", "Cuatro"], "answer": 0, "explain": "Las metas 4.a a 4.c son los tres medios de implementación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿De qué trata la Meta 4.c?", "options": ["Construir nuevos campos deportivos", "Aumentar la oferta de maestros calificados", "Dar libros gratis a los adultos", "Hacer las escuelas más pequeñas"], "answer": 1, "explain": "La meta 4.c pide más maestros calificados, también mediante la formación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué meta se centra en el desarrollo sostenible y la ciudadanía mundial?", "options": ["Meta 4.1", "Meta 4.2", "Meta 4.7", "Meta 4.b"], "answer": 2, "explain": "La meta 4.7 abarca los conocimientos para el desarrollo sostenible y la ciudadanía mundial.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿En qué se centra un indicador de competencia?", "options": ["En cuántos edificios tiene una escuela", "En cuántas vacaciones hay al año", "En lo altos que son los estudiantes", "En si los estudiantes alcanzan un nivel establecido en habilidades clave"], "answer": 3, "explain": "Los indicadores de competencia comprueban si los estudiantes alcanzan un nivel establecido en habilidades como la lectura y las matemáticas.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "¿Qué significa desagregar los datos por sexo, edad y discapacidad?", "options": ["Desglosar los datos por cada uno de estos grupos", "Mantener los datos en secreto", "Recoger datos solo de los hombres", "Recoger datos solo sobre edificios"], "answer": 0, "explain": "La desagregación muestra si el avance llega a todos los grupos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué Objetivo trata sobre la reducción de las desigualdades?", "options": ["Objetivo 6", "Objetivo 10", "Objetivo 13", "Objetivo 15"], "answer": 1, "explain": "El Objetivo 10 es Reducción de las Desigualdades.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué es la tasa de niños fuera de la escuela?", "options": ["La proporción de estudiantes que se saltan el almuerzo", "La proporción de escuelas sin techo", "La proporción de niños en edad escolar que no asisten a la escuela", "La proporción de maestros de baja"], "answer": 2, "explain": "La tasa de niños fuera de la escuela mide a los niños en edad escolar que no están matriculados.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué hace que una escuela sea accesible en cuanto a la distancia?", "options": ["Está lejos de todas las casas", "Solo se puede llegar en avión", "Está cerrada entre semana", "Está a una distancia segura de las casas de los niños"], "answer": 3, "explain": "La accesibilidad significa que los niños pueden llegar a la escuela de forma segura y regular.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué costo suele ser oculto para las familias pobres?", "options": ["El ingreso que se pierde por el trabajo de los niños", "Cuadernos gratuitos", "Almuerzos escolares gratuitos", "Transporte gratuito"], "answer": 0, "explain": "Las familias pobres pueden perder ingresos cuando los niños van a la escuela en lugar de trabajar.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es el reto de la última milla en educación?", "options": ["Correr la carrera más larga", "Llegar a los niños más remotos", "Hacer el último examen", "Cerrar la última escuela"], "answer": 1, "explain": "Los retos de la última milla se centran en llegar a los niños más difíciles de alcanzar.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué los gobiernos hacen seguimiento de los datos de matrícula?", "options": ["Para elegir los colores de la escuela", "Para clasificar a los estudiantes por estatura", "Para planificar maestros, edificios y plazas", "Para elegir las fechas de vacaciones"], "answer": 2, "explain": "Los datos de matrícula ayudan a los gobiernos a planificar maestros, aulas y transporte.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué mide una tasa de transición?", "options": ["La velocidad de los autobuses escolares en la carretera principal", "El número de timbres que suenan en un día entero", "El precio de cuadernos y bolígrafos vendidos en la cantina", "La proporción de estudiantes que pasan de un nivel al siguiente"], "answer": 3, "explain": "Las tasas de transición muestran cuántos estudiantes avanzan al siguiente nivel.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué algunos estudiantes no logran pasar a la secundaria?", "options": ["Costos, distancia y un aprendizaje previo débil", "La secundaria siempre es gratuita", "La secundaria no tiene requisitos de ingreso", "Los estudiantes son demasiado altos"], "answer": 0, "explain": "Los costos, la distancia y las lagunas del aprendizaje en primaria pueden impedir que los estudiantes avancen.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué significa completar la secundaria superior?", "options": ["Terminar el primer año de preescolar", "Terminar la última etapa de la secundaria", "Terminar un curso de deporte", "Terminar un campamento de vacaciones"], "answer": 1, "explain": "Completar la secundaria superior significa terminar la última etapa de la secundaria.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué grupo tiene más probabilidades de enfrentar varias barreras para completar la educación a la vez?", "options": ["Niños de familias ricas y urbanas", "Niños sin ninguna barrera", "Niñas de familias pobres y rurales con discapacidad", "Solo adultos"], "answer": 2, "explain": "Las desventajas superpuestas dificultan completar la educación para algunos estudiantes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es una vía de aprendizaje alternativa?", "options": ["Un camino hacia una titulación sin ningún examen escrito", "Un camino abierto solo a maestros titulados", "Un camino que impide que los estudiantes terminen sus estudios", "Un camino hacia la misma titulación por una ruta distinta"], "answer": 3, "explain": "Las vías alternativas permiten obtener titulaciones de forma flexible.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es un sistema de alerta temprana en las escuelas?", "options": ["Detectar a los estudiantes en riesgo de abandono para empezar a ayudarlos pronto", "Avisar a los estudiantes de los exámenes finales de fin de curso", "Hacer sonar alarmas fuertes a la hora del almuerzo para llamar a los alumnos", "Tocar el timbre de la escuela más fuerte y durante más tiempo en las asambleas"], "answer": 0, "explain": "Los sistemas de alerta temprana señalan problemas de asistencia y aprendizaje para que las escuelas puedan actuar.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es una evaluación internacional del aprendizaje?", "options": ["Una competición deportiva escolar", "Una prueba que compara el aprendizaje entre países", "Una prueba para contratar maestros", "Un plan de presupuesto del gobierno"], "answer": 1, "explain": "Las evaluaciones internacionales como PISA, TIMSS y PIRLS comparan el aprendizaje entre países.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es PISA?", "options": ["Un sistema de autobuses escolares para niños de zonas rurales", "Un tipo de uniforme escolar que usan los alumnos de la ciudad", "Una prueba de las habilidades de estudiantes de 15 años en lectura, matemáticas y ciencias", "Un torneo deportivo mundial para jóvenes atletas cada año"], "answer": 2, "explain": "PISA es una prueba de la OCDE para estudiantes de 15 años en lectura, matemáticas y ciencias.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Por qué las evaluaciones del aprendizaje necesitan un diseño cuidadoso?", "options": ["Para que nunca se necesiten pruebas", "Para que las pruebas sean más largas", "Para que los estudiantes nunca las vean", "Para medir de forma justa entre idiomas y culturas"], "answer": 3, "explain": "Las buenas evaluaciones se diseñan para ser justas y comparables entre grupos.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es una crisis del aprendizaje?", "options": ["Muchos niños van a la escuela pero no aprenden", "Los niños aprenden demasiado rápido", "Las escuelas tienen demasiados libros", "Los niños nunca van a la escuela"], "answer": 0, "explain": "La crisis del aprendizaje describe a niños que asisten a la escuela pero no adquieren habilidades básicas.", "src": "World Bank, learning poverty"}, {"ch": 3, "q": "¿Qué es una evaluación de lectura en los primeros grados?", "options": ["Una prueba solo para adultos, realizada tras su jornada laboral", "Una prueba de lectura en los primeros años de escuela", "Una prueba de habilidades deportivas para el equipo de fútbol de la escuela", "Una prueba de habilidades culinarias para niños pequeños en casa"], "answer": 1, "explain": "Las evaluaciones de lectura en los primeros grados comprueban si los niños pequeños están aprendiendo a leer.", "src": "UNESCO"}, {"ch": 3, "q": "¿En qué ayuda la comprensión a los estudiantes con un problema de matemáticas?", "options": ["A adivinar la respuesta sin leer", "A saltarse la pregunta", "A entender qué pide el problema", "A copiar de un compañero"], "answer": 2, "explain": "La comprensión ayuda a los estudiantes a entender un problema antes de resolverlo.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la alfabetización en datos?", "options": ["Recoger datos sobre mascotas", "Ocultar datos a otros", "Guardar datos solo en papel", "Leer, entender y usar datos"], "answer": 3, "explain": "La alfabetización en datos significa entender y usar datos para tomar decisiones.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué los estudiantes necesitan entender la inteligencia artificial?", "options": ["Para usarla con criterio y comprender sus límites", "Para reemplazar a todos los maestros", "Para dejar de usar computadoras", "Para evitar toda tecnología"], "answer": 0, "explain": "Los estudiantes necesitan usar las herramientas de IA de forma responsable y entender qué pueden y qué no pueden hacer.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es una mentalidad emprendedora?", "options": ["Evitar todo riesgo y quedarse siempre en el mismo lugar", "Detectar oportunidades y asumir riesgos sensatos", "Trabajar solo para otros y nunca para uno mismo", "No probar nunca cosas ni ideas nuevas en la vida"], "answer": 1, "explain": "Una mentalidad emprendedora consiste en detectar oportunidades y actuar sobre ellas con responsabilidad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué son las habilidades blandas?", "options": ["Habilidades para levantar objetos pesados", "Habilidades solo para hornear pan", "Habilidades como el trabajo en equipo, la empatía y la comunicación", "Habilidades para dormir"], "answer": 2, "explain": "Las habilidades blandas ayudan a las personas a trabajar y convivir bien con los demás.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es el aprendizaje a lo largo de la vida?", "options": ["Aprender solo hasta los diez años", "Aprender solo en la universidad", "Aprender solo los domingos", "Aprender durante toda la vida, no solo en la escuela"], "answer": 3, "explain": "El aprendizaje a lo largo de la vida significa seguir aprendiendo durante toda la vida.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué el aprendizaje a lo largo de la vida es importante para el trabajo?", "options": ["El trabajo cambia, así que las personas necesitan nuevas habilidades", "Los empleos nunca cambian", "El aprendizaje es inútil después de la escuela", "Los empleos no necesitan ninguna habilidad"], "answer": 0, "explain": "Las nuevas tecnologías y sectores hacen que las personas sigan aprendiendo nuevas habilidades.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué significa aprender a aprender?", "options": ["No memorizar nada y esperar aprobar de todos modos", "Saber cómo se aprende mejor y planificar el aprendizaje", "Copiar respuestas rápidamente del cuaderno de un compañero", "Nunca hacer preguntas en clase ni en casa"], "answer": 1, "explain": "Aprender a aprender ayuda a las personas a ser estudiantes independientes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es la interseccionalidad en educación?", "options": ["Un tipo de edificio escolar con muchos pisos y aulas", "Un tipo de horario escolar usado en todas las clases", "Cómo las identidades superpuestas pueden aumentar la desventaja", "Una forma de separar las clases según la estatura de cada niño"], "answer": 2, "explain": "La interseccionalidad reconoce que el género, la pobreza, la discapacidad y otros factores pueden superponerse.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué busca la educación transformadora de género?", "options": ["Mantener sin cambios las normas de género", "Enseñar solo a un género", "Ignorar el género en todas las materias", "Cambiar las normas de género dañinas"], "answer": 3, "explain": "La educación transformadora de género desafía los estereotipos y los roles desiguales.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Por qué algunas niñas corren mayor riesgo de abandonar la escuela durante un conflicto?", "options": ["Inseguridad, desplazamiento y violencia de género", "Las niñas siempre están más seguras", "El conflicto no afecta a las escuelas", "A las niñas les gustan los conflictos"], "answer": 0, "explain": "Los conflictos pueden aumentar riesgos como el desplazamiento y la violencia, que empujan a las niñas fuera de la escuela.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué ayuda a prevenir la violencia de género en las escuelas?", "options": ["Ocultar los incidentes a los padres y al público", "Políticas, códigos de conducta y formación", "Culpar a las víctimas de lo que les ocurrió", "Ignorar todas las denuncias que recibe la escuela"], "answer": 1, "explain": "La prevención incluye códigos de conducta claros, formación y sistemas de denuncia.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué es la participación equitativa en el aula?", "options": ["Solo hablan los estudiantes más ruidosos", "Solo los niños hablan en clase", "Todos los estudiantes pueden participar y ser escuchados", "Solo habla el maestro"], "answer": 2, "explain": "La participación equitativa significa que cada estudiante tiene una oportunidad justa de contribuir.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es el lenguaje discriminatorio en una escuela?", "options": ["Palabras que elogian el trabajo duro", "Palabras que explican una lección", "Palabras que describen el tiempo", "Palabras que humillan a las personas por lo que son"], "answer": 3, "explain": "El lenguaje discriminatorio daña a los estudiantes y crea un entorno inseguro.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa estigma para los estudiantes?", "options": ["Juicios negativos que excluyen a las personas", "Un tipo de premio escolar", "Un tipo de uniforme escolar", "Una forma de elogio"], "answer": 0, "explain": "El estigma lleva a tratar a las personas de forma injusta, lo que puede impedir que aprendan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué son los estándares profesionales docentes?", "options": ["Una lista de vacaciones de los maestros", "Expectativas sobre lo que los maestros deben saber y hacer", "Una lista de meriendas escolares", "Solo una lista de salarios de maestros"], "answer": 1, "explain": "Los estándares profesionales describen cómo es una buena enseñanza.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué la contratación de docentes es un reto político?", "options": ["Requiere contratar solo a familiares", "No requiere ninguna planificación", "Requiere atraer y seleccionar a personas capaces", "Requiere cerrar escuelas"], "answer": 2, "explain": "Una buena contratación encuentra a personas capaces y las coloca donde se necesitan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la asignación de docentes?", "options": ["Enviar a los maestros de vacaciones", "Enviar a los maestros solo a otros países", "Sacar a los maestros de las escuelas", "Colocar a los maestros donde más se necesitan"], "answer": 3, "explain": "La asignación consiste en destinar a los maestros a las escuelas y zonas donde más se necesitan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la retención docente?", "options": ["Mantener a los maestros en la profesión", "Mantener a los maestros en clase sin descansos", "Impedir que los estudiantes se conviertan en maestros", "Mantener a los maestros lejos de los niños"], "answer": 0, "explain": "Las estrategias de retención mantienen a los maestros formados en sus puestos.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué los maestros necesitan cierta autonomía?", "options": ["Para evitar todas las normas", "Para adaptar las clases a sus estudiantes", "Para no enseñar nada", "Para trabajar sin apoyo"], "answer": 1, "explain": "Cierta autonomía ayuda a los maestros a adaptar sus clases a las necesidades reales del aula.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un sindicato docente?", "options": ["Un grupo que cierra escuelas", "Un grupo que vende libros de texto", "Una organización que representa los intereses de los maestros", "Un grupo que fija solo las fechas de exámenes"], "answer": 2, "explain": "Los sindicatos docentes representan a los maestros en las negociaciones sobre salarios y condiciones de trabajo.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el absentismo docente?", "options": ["Maestros que asisten a formación", "Maestros que ayudan en clubes", "Maestros que leen libros", "Maestros que faltan al trabajo sin una buena razón"], "answer": 3, "explain": "El absentismo reduce el tiempo de aprendizaje, por lo que es una preocupación de política educativa.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿En qué afecta el bienestar docente?", "options": ["A qué tan bien enseñan los maestros y si permanecen en su puesto", "Solo al precio de los autobuses escolares", "Solo al clima", "Nada importante"], "answer": 0, "explain": "El bienestar docente afecta la calidad de la enseñanza y la retención.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es la transparencia presupuestaria en educación?", "options": ["Ocultar el gasto al público", "Publicar cómo se gasta el dinero de la educación", "Gastar el dinero en secreto", "Ignorar los presupuestos"], "answer": 1, "explain": "La transparencia permite a los ciudadanos comprobar cómo se usan los fondos de educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la financiación focalizada para la educación?", "options": ["Fondos iguales para cada escuela, sin importar sus necesidades", "Fondos gastados solo en deportes, juegos y excursiones escolares", "Fondos adicionales para escuelas o estudiantes con mayores necesidades", "Fondos enviados solo a escuelas que ya son muy ricas"], "answer": 2, "explain": "La financiación focalizada dirige más recursos a donde las necesidades son mayores.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "¿Qué es la eficiencia en el gasto escolar?", "options": ["Gastar la mayor cantidad de dinero posible", "Gastar en las cosas menos útiles", "Gastar solo en edificios", "Obtener el máximo aprendizaje por el dinero gastado"], "answer": 3, "explain": "El gasto eficiente logra mejores resultados de aprendizaje con la misma cantidad de dinero.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué muchos países financian las escuelas con impuestos locales?", "options": ["Para dar a las comunidades locales voz en el gasto", "Los impuestos locales son ilegales", "Los impuestos locales reemplazan todo el dinero del gobierno", "Los impuestos locales son solo para deportes"], "answer": 0, "explain": "La financiación local puede hacer que las escuelas respondan mejor, aunque también puede aumentar la desigualdad.", "src": "UNESCO"}, {"ch": 7, "q": "¿Cuál es el riesgo de depender solo de los impuestos locales?", "options": ["Las zonas más pobres siempre reciben más dinero", "Las zonas más ricas pueden financiar mejor sus escuelas", "Las escuelas nunca necesitan dinero", "Los impuestos locales siempre acaban con la desigualdad"], "answer": 1, "explain": "Depender solo de los impuestos locales puede ampliar la brecha entre zonas ricas y pobres.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "¿Qué es un presupuesto de capital para escuelas?", "options": ["Dinero solo para salarios de maestros", "Dinero para vacaciones", "Dinero para edificios y equipamiento", "Dinero solo para uniformes escolares"], "answer": 2, "explain": "Un presupuesto de capital financia bienes a largo plazo como edificios y equipamiento.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es un presupuesto corriente para escuelas?", "options": ["Dinero para construir una sola escuela nueva", "Dinero para un único examen", "Dinero para eventos deportivos puntuales", "Dinero para los gastos diarios de funcionamiento, como los salarios"], "answer": 3, "explain": "El presupuesto corriente cubre costos continuos como los salarios de los maestros y los materiales.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es el costo unitario en educación?", "options": ["El costo de educar a un estudiante durante un año", "El costo de un autobús escolar", "El costo de un uniforme escolar completo", "El costo de una sola hoja de examen"], "answer": 0, "explain": "El costo unitario ayuda a los gobiernos a planificar cuánto dinero necesita cada estudiante.", "src": "UNESCO"}, {"ch": 8, "q": "¿En qué año se reunió el Foro Mundial sobre la Educación en Incheon?", "options": ["1990", "2015", "2000", "2030"], "answer": 1, "explain": "El Foro Mundial sobre la Educación se celebró en Incheon, República de Corea, en 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Dónde se celebró el Foro Mundial sobre la Educación de 2015?", "options": ["Dakar, Senegal", "Jomtien, Tailandia", "Incheon, República de Corea", "París, Francia"], "answer": 2, "explain": "Incheon, en la República de Corea, acogió el foro de 2015.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Dónde se celebró el Foro Mundial sobre la Educación de 2000?", "options": ["Incheon, República de Corea", "Jomtien, Tailandia", "Nairobi, Kenia", "Dakar, Senegal"], "answer": 3, "explain": "El foro de Dakar de 2000 adoptó el Marco de Acción de Dakar.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué abarca el artículo 26 de la Declaración Universal de Derechos Humanos?", "options": ["El derecho a la educación", "El derecho a tener un coche", "El derecho a unas vacaciones", "El derecho a votar en las escuelas"], "answer": 0, "explain": "El artículo 26 establece el derecho a la educación.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿En qué se basa la Educación 2030?", "options": ["Solo en los Juegos Olímpicos y las reglas para los atletas", "En los Objetivos de Desarrollo del Milenio y en la Educación para Todos", "Solo en la exploración espacial y los estudios de cohetería", "Solo en las reglas del deporte y los resultados de torneos de fútbol"], "answer": 1, "explain": "La Educación 2030 se basa en compromisos globales anteriores en materia de educación.", "src": "Incheon Framework for Action (2015)"}, {"ch": 8, "q": "¿Por qué el mundo pasó de los ODM a los ODS?", "options": ["Para cancelar todas las metas educativas de la siguiente década", "Para centrarse en un solo país e ignorar a los demás", "Para abarcar una gama más amplia de temas para todos los países", "Para eliminar todas las metas que los países habían fijado"], "answer": 2, "explain": "Los ODS son universales y abarcan más temas que los ODM.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Qué periodo abarcaron los ODM?", "options": ["De 1990 a 2000", "De 2015 a 2030", "De 2000 a 2030", "De 2000 a 2015"], "answer": 3, "explain": "Los ODM abarcaron de 2000 a 2015.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "¿Qué es el cuidado receptivo?", "options": ["Que los adultos reaccionen con calidez y de forma adecuada a las señales de un niño", "Ignorar las señales de un niño y dejarlo llorar", "Solo dar órdenes y nunca escuchar a los niños", "Mantener a los niños separados de los adultos en todos los entornos"], "answer": 0, "explain": "El cuidado receptivo genera confianza y favorece el aprendizaje.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué importa la salud del niño para el aprendizaje?", "options": ["La salud no tiene ningún efecto en el aprendizaje", "La enfermedad y el hambre pueden impedir que los niños aprendan", "Solo el deporte necesita salud", "Los niños sanos nunca necesitan la escuela"], "answer": 1, "explain": "La buena salud y la nutrición ayudan a los niños a aprender y concentrarse.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es el retraso del crecimiento?", "options": ["Crecer muy rápido y volverse mucho más alto que la mayoría de sus compañeros", "Una norma disciplinaria escolar sobre el uniforme, el pelo y los zapatos", "Ser mucho más bajo de lo esperado para la edad por una mala nutrición", "Ser muy alto para la edad y crecer más rápido que la mayoría de sus compañeros"], "answer": 2, "explain": "El retraso del crecimiento es un signo de desnutrición crónica y puede afectar al aprendizaje.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es la estimulación temprana?", "options": ["Mantener a un bebé en silencio total muchas horas al día", "Dar a los niños pequeños solo dulces en cada comida", "Mantener a los bebés en habitaciones oscuras casi todo el día", "Actividades que estimulan los sentidos y el pensamiento de un bebé"], "answer": 3, "explain": "La estimulación temprana incluye hablar, cantar, el contacto y el juego.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué los servicios de primera infancia necesitan personal capacitado?", "options": ["El personal formado apoya mejor el desarrollo de los niños", "No se necesita personal", "La formación es un desperdicio de dinero", "El personal capacitado hace que los niños dejen de aprender"], "answer": 0, "explain": "El personal de primera infancia bien formado entiende cómo aprenden los niños pequeños.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es un programa de transición de la primera infancia a la primaria?", "options": ["Un puente sobre un río", "Un programa que ayuda a los niños a adaptarse", "Una carretera para autobuses escolares", "Un campo deportivo"], "answer": 1, "explain": "Los programas de transición ayudan a los niños pequeños a adaptarse a la primaria.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es la conciencia fonémica?", "options": ["Conocer los nombres de los colores", "Escribir solo en mayúsculas", "Darse cuenta de los sonidos de las palabras habladas", "Leer la contraportada de un libro"], "answer": 2, "explain": "La conciencia fonémica ayuda a los niños a relacionar sonidos con letras.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es el vocabulario en la lectura inicial?", "options": ["El precio de los libros", "El número de páginas", "El tamaño de las letras", "Las palabras que un niño conoce y usa"], "answer": 3, "explain": "Un vocabulario amplio ayuda a los niños a entender lo que leen.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es la educación básica de adultos?", "options": ["Lectura, escritura y cálculo básicos para adultos", "Estudios universitarios avanzados de física y derecho", "Entrenamiento deportivo para un equipo de fútbol local", "Clases de conducir para adultos que quieren un carné"], "answer": 0, "explain": "La educación básica de adultos ayuda a aprender la alfabetización y el cálculo esenciales.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es un entorno rico en textos impresos?", "options": ["Un lugar sin palabras impresas", "Un lugar con muchas palabras impresas para leer", "Un lugar donde todos los libros están bajo llave", "Un lugar con solo imágenes"], "answer": 1, "explain": "Los entornos ricos en textos exponen a los niños a letras y palabras en la vida diaria.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Por qué las zonas rurales suelen tener niveles más bajos de alfabetización?", "options": ["Las personas del campo nunca leen", "La ley no permite enseñar alfabetización en zonas rurales", "Hay menos escuelas, libros y lugares de lectura cerca", "Las personas del campo no necesitan leer"], "answer": 2, "explain": "Muchos países muestran una alfabetización más baja en zonas rurales, donde las escuelas y los libros son más difíciles de alcanzar.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Por qué es importante la lectura por placer?", "options": ["Es una pérdida de tiempo", "Es solo para maestros", "Hace que los niños dejen de leer después", "Crea hábitos de lectura y un conocimiento más amplio"], "answer": 3, "explain": "La lectura por placer crea hábitos que favorecen el aprendizaje a lo largo de la vida.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "¿Qué fomenta el diseño universal para el aprendizaje?", "options": ["Múltiples formas de presentar, motivar y evaluar el aprendizaje", "Una única forma de enseñar que todos los estudiantes deben seguir", "Eliminar todas las evaluaciones del año escolar", "Enseñar solo en silencio, sin ningún debate"], "answer": 0, "explain": "El diseño universal ofrece opciones para que los estudiantes accedan al aprendizaje y demuestren lo que saben.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es un plan de apoyo al aprendizaje?", "options": ["Un plan de vacaciones escolares para todos los estudiantes", "Un plan que establece apoyos para las necesidades de un estudiante", "Un plan para terminar las clases temprano todos los días", "Un plan para sacar a algunos estudiantes de la escuela"], "answer": 1, "explain": "Los planes de apoyo establecen ajustes y ayudas para estudiantes concretos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué deberían participar las familias de estudiantes con discapacidad?", "options": ["Las familias no deberían participar", "Las familias solo pagan cuotas", "Ellas conocen mejor las necesidades del estudiante", "Las familias causan problemas"], "answer": 2, "explain": "Las familias aportan conocimientos que ayudan a las escuelas a apoyar a los estudiantes.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la evaluación inclusiva?", "options": ["Pruebas que solo pueden aprobar los mejores", "Pruebas que nunca se aplican", "Pruebas que solo miden la velocidad", "Pruebas que permiten a todos los estudiantes demostrar lo que saben"], "answer": 3, "explain": "La evaluación inclusiva adapta la forma de mostrar el aprendizaje para que todos puedan demostrarlo.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es el apoyo entre iguales en una escuela inclusiva?", "options": ["Compañeros que se ayudan a aprender", "Compañeros que compiten para excluir a otros", "Compañeros que trabajan solo por su cuenta", "Compañeros que se evitan"], "answer": 0, "explain": "El apoyo entre iguales ayuda a los estudiantes a sentirse incluidos y a aprender juntos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué las escuelas inclusivas reducen la discriminación?", "options": ["Separan a los niños por capacidad", "Enseñan el respeto y hacen que la diferencia sea normal", "Eliminan toda diversidad", "Aumentan el miedo"], "answer": 1, "explain": "Cuando los niños aprenden juntos, desarrollan respeto y comprensión.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la segregación en las escuelas?", "options": ["Reunir a todos los niños en la misma aula cada día", "Compartir libros y materiales por igual entre los alumnos", "Separar a los niños por discapacidad, género o origen", "Dar a todos un turno justo en el patio"], "answer": 2, "explain": "La segregación separa a los estudiantes de forma injusta y la educación inclusiva se opone a ella.", "src": "UN CRPD (2006), Article 24"}, {"ch": 1, "q": "¿Qué es el área de captación de una escuela?", "options": ["Un tipo de deporte escolar", "El techo de una escuela", "Una comida escolar", "La zona que la escuela está planificada para atender"], "answer": 3, "explain": "El área de captación es la zona de niños que la escuela está prevista para atender.", "src": "UNESCO"}], "9": [{"ch": 0, "q": "¿Qué ODS trata sobre las alianzas para lograr los objetivos?", "options": ["Objetivo 17", "Objetivo 7", "Objetivo 12", "Objetivo 1"], "answer": 0, "explain": "El Objetivo 17 es Alianzas para lograr los objetivos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿A qué se refieren los medios de implementación?", "options": ["A los nombres de todos los objetivos escritos en un gran cartel", "A los recursos y herramientas necesarios para alcanzar los objetivos", "A las fechas de las reuniones celebradas cada año en el ayuntamiento", "A los colores de los carteles colgados en el salón de la escuela"], "answer": 1, "explain": "Los medios de implementación incluyen finanzas, tecnología, capacidades y alianzas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuál es el problema de la brecha de datos en el seguimiento de los ODS?", "options": ["Hay muchísimos datos para que alguien pueda leerlos bien", "Los datos solo se guardan en papel, en viejos archivadores", "Muchos países carecen de datos fiables para seguir el avance", "Los datos siempre son perfectos y nunca necesitan revisión"], "answer": 2, "explain": "Las lagunas de datos dificultan medir el avance e identificar a quienes quedan atrás.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "¿Por qué los ODS usan indicadores?", "options": ["Para fijar los horarios escolares", "Para elegir el himno nacional", "Para reemplazar a los maestros", "Para medir el avance de forma coherente"], "answer": 3, "explain": "Los indicadores hacen comparable el avance entre países y a lo largo del tiempo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué es la Agenda 2030?", "options": ["Un plan aprobado en 2015 para alcanzar los objetivos en 2030", "Un plan para los Juegos Olímpicos celebrados en París en 2030", "Un horario escolar que dura cada trimestre hasta 2030", "Un calendario de vacaciones para todas las escuelas del año 2030"], "answer": 0, "explain": "La Agenda 2030 es el plan de la ONU aprobado en 2015 para los Objetivos Globales.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué hace un plan nacional de los ODS 4?", "options": ["Cierra todas las escuelas", "Establece cómo alcanzará un país el ODS 4", "Cancela todos los exámenes", "Elimina las cuotas escolares solo por decreto"], "answer": 1, "explain": "Un plan nacional fija prioridades, presupuestos y acciones para alcanzar el ODS 4.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué es la exclusión escolar?", "options": ["Recibir un premio", "Cambiarse de escuela por elección propia", "Ser apartado o mantenido fuera de la escuela", "Recibir clases extra"], "answer": 2, "explain": "La exclusión impide que los niños aprendan, lo que vulnera su derecho a la educación.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 1, "q": "¿Cuál es el impacto del matrimonio infantil en la escolarización?", "options": ["Siempre mejora la escuela", "No tiene ningún efecto", "Hace que la escuela sea gratuita", "A menudo pone fin a la escolarización de forma temprana"], "answer": 3, "explain": "El matrimonio infantil es una causa importante de que las niñas abandonen la escuela pronto.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "¿Qué es el desplazamiento para la educación?", "options": ["Verse obligado a abandonar el hogar, lo que suele interrumpir la escolarización", "Mover un pupitre al otro lado del aula", "Elegir cada año una nueva escuela para el siguiente trimestre", "Un tipo de examen escolar que se hace al inicio del trimestre"], "answer": 0, "explain": "Los niños desplazados pueden perder años de escolarización sin apoyo.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es la educación de los refugiados?", "options": ["Educación solo para maestros de una escuela concreta", "Educación para niños y jóvenes que han huido de sus hogares", "Educación solo en deporte y actividades al aire libre para toda la escuela", "Educación solo para adultos que vuelven a estudiar más tarde"], "answer": 1, "explain": "La educación de los refugiados ayuda a los estudiantes desplazados a seguir aprendiendo.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué importa la educación en situaciones de emergencia?", "options": ["No tiene ningún valor en las crisis", "Es solo para turistas", "Ofrece estabilidad y protección a los niños", "Reemplaza toda la ayuda alimentaria"], "answer": 2, "explain": "Las escuelas en emergencias ofrecen seguridad, rutina y esperanza a los niños.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué es un espacio de aprendizaje temporal?", "options": ["Un edificio para guardar coches y maquinaria pesada", "Una tienda que vende libros, bolígrafos y papel a todos los estudiantes", "Un lugar solo para que los adultos descansen por la tarde", "Un lugar seguro para aprender, montado rápidamente tras una crisis"], "answer": 3, "explain": "Los espacios de aprendizaje temporales mantienen a los niños aprendiendo cuando las escuelas permanentes no son utilizables.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Con qué se suele medir la distancia a la escuela?", "options": ["Con el tiempo o la distancia que debe recorrer un niño", "Con el número de libros", "Con el color de la escuela", "Con el número de maestros de la ciudad"], "answer": 0, "explain": "El tiempo de viaje y la distancia son medidas habituales de acceso.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué los niños con discapacidad suelen faltar a la escuela?", "options": ["No quieren aprender", "Las escuelas no son accesibles ni cuentan con apoyo", "Son demasiado listos para la escuela", "Tienen demasiados juguetes"], "answer": 1, "explain": "La falta de edificios accesibles, de enseñanza adaptada y de apoyo deja fuera a muchos niños.", "src": "UN CRPD (2006), Article 24"}, {"ch": 2, "q": "¿Qué es la tasa de repetición?", "options": ["La proporción que gana carreras", "La proporción que ingresa antes de tiempo", "La proporción de estudiantes que repiten un grado", "La proporción que estudia música"], "answer": 2, "explain": "Las tasas de repetición muestran con qué frecuencia los estudiantes repiten un grado.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué la repetición suele ser una mala solución?", "options": ["Siempre mejora el aprendizaje", "Es gratuita para todos", "Elimina todas las lagunas", "Puede aumentar el riesgo de abandono"], "answer": 3, "explain": "Repetir un año suele aumentar la probabilidad de que el estudiante abandone la escuela.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la promoción de grado?", "options": ["Pasar al grado siguiente", "Vender uniformes escolares", "Mudarse a otro país", "Dejar la escuela"], "answer": 0, "explain": "La promoción significa que el estudiante pasa al grado siguiente.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es un certificado de fin de estudios?", "options": ["Una entrada para un gran partido de fútbol en el estadio nacional", "Un documento que acredita que el estudiante ha terminado un nivel", "Una multa para cualquier estudiante que falte a clase con frecuencia", "Un mapa que indica dónde está cada escuela de la ciudad"], "answer": 1, "explain": "Un certificado de fin de estudios registra la finalización de un nivel educativo.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué buscan las metas nacionales de finalización?", "options": ["Reducir el número total de escuelas de todo el país", "Impedir que los niños pasen nunca al siguiente nivel", "Aumentar la proporción de niños que terminan cada nivel", "Dar menos exámenes a todos los estudiantes de la escuela"], "answer": 2, "explain": "Las metas nacionales se centran en ayudar a que más niños terminen cada nivel.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es la certificación de competencias?", "options": ["Un tipo de mochila con muchos bolsillos pequeños", "Un calendario de vacaciones para toda la familia cada verano", "Una receta de cocina para una cena familiar especial", "Reconocimiento oficial de las habilidades que tiene una persona"], "answer": 3, "explain": "La certificación demuestra a los empleadores y a otros que una persona tiene una habilidad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es el reconocimiento del aprendizaje previo?", "options": ["Dar crédito por el aprendizaje ya adquirido fuera de la escuela", "Ignorar todo el aprendizaje anterior y empezar desde cero cada vez", "Contar solo los exámenes realizados en una universidad o escuela superior", "Eliminar titulaciones que las personas ya han obtenido"], "answer": 0, "explain": "Reconocer el aprendizaje previo ayuda a avanzar sin repetir lo que ya se sabe.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es un estándar de aprendizaje?", "options": ["Un tipo de edificio escolar con muchas aulas", "Una declaración de lo que los estudiantes deben saber y hacer", "Un tipo de autobús escolar que circula cada mañana", "Un código de vestimenta escolar para estudiantes y maestros"], "answer": 1, "explain": "Los estándares de aprendizaje describen los resultados esperados en cada nivel.", "src": "UNESCO"}, {"ch": 3, "q": "¿En qué se centra el Informe de Seguimiento de la Educación en el Mundo?", "options": ["En la venta de libros de texto", "En elegir los deportes escolares", "En el seguimiento del avance educativo en todo el mundo", "En planificar vacaciones"], "answer": 2, "explain": "El Informe GEM hace seguimiento del avance educativo y comparte evidencias.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es un perfil de aprendizaje?", "options": ["Una foto de un estudiante", "Una lista de vacaciones escolares", "Un mapa de la escuela", "Un registro de las fortalezas y necesidades de un estudiante"], "answer": 3, "explain": "Los perfiles de aprendizaje ayudan a los maestros a planificar el apoyo a cada estudiante.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué los maestros usan evaluaciones diagnósticas?", "options": ["Para saber qué ya saben los estudiantes y qué necesitan", "Para poner calificaciones solo al final de cada curso", "Para evitar dar clase a toda la clase durante todo el día", "Para castigar a los niños cada vez que se equivocan"], "answer": 0, "explain": "Las evaluaciones diagnósticas ayudan a los maestros a planificar lecciones que se ajusten a las necesidades de los estudiantes.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la reforma curricular?", "options": ["Cambiar el color de la escuela", "Cambiar lo que se enseña y cómo se enseña", "Cerrar todas las escuelas", "Suprimir todas las asignaturas"], "answer": 1, "explain": "La reforma curricular actualiza las materias, las competencias y los métodos de enseñanza.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es el aprendizaje basado en competencias?", "options": ["Centrarse solo en memorizar datos", "Centrarse solo en el deporte", "Centrarse en lo que los estudiantes pueden hacer", "Centrarse solo en el tiempo que se pasa en clase"], "answer": 2, "explain": "El aprendizaje por competencias mide habilidades y capacidades, no solo conocimientos.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué es importante la alfabetización científica?", "options": ["Reemplaza todas las habilidades de lectura y escritura", "Solo ayuda a los científicos en sus laboratorios", "No tiene ninguna utilidad real en la vida cotidiana", "Ayuda a las personas a entender y valorar la evidencia"], "answer": 3, "explain": "La alfabetización científica ayuda a tomar decisiones informadas sobre la salud y el medio ambiente.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Qué es el razonamiento matemático?", "options": ["Explicar por qué funciona un método", "Adivinar la respuesta", "Copiar la respuesta", "Saltarse el procedimiento"], "answer": 0, "explain": "El razonamiento muestra que el estudiante comprende el método, no solo la respuesta.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es la ganancia de aprendizaje?", "options": ["Un aumento de peso", "El progreso que logra un estudiante durante un periodo", "Un beneficio de las ventas escolares", "Un aumento de vacaciones"], "answer": 1, "explain": "Las ganancias de aprendizaje miden cuánto mejora un estudiante con el tiempo.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "¿Qué es una competencia verde?", "options": ["Una habilidad para pintar paredes de verde", "Una habilidad solo para cultivar césped", "Una habilidad que ayuda a proteger el medio ambiente", "Una habilidad para jugar a juegos verdes"], "answer": 2, "explain": "Las competencias verdes apoyan la protección del medio ambiente y los empleos sostenibles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué la educación climática se relaciona con la Meta 4.7?", "options": ["El clima no tiene relación con el aprendizaje", "La educación climática está prohibida", "La educación climática reemplaza a las matemáticas", "Apoya la educación para el desarrollo sostenible"], "answer": 3, "explain": "La meta 4.7 incluye la educación para el desarrollo sostenible, que abarca el clima.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la educación para la paz?", "options": ["Aprender a resolver conflictos sin violencia", "Aprender a provocar conflictos", "Aprender solo historia de guerras", "Aprender a evitar a las personas"], "answer": 0, "explain": "La educación para la paz enseña respeto, diálogo y no violencia.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué enseña la educación en derechos humanos?", "options": ["Solo las reglas de los juegos", "Los derechos y responsabilidades de los estudiantes", "Solo la historia de los trenes", "Solo a cocinar"], "answer": 1, "explain": "La educación en derechos humanos ayuda a los estudiantes a conocer y respetar los derechos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la educación cívica?", "options": ["Aprender solo sobre coches", "Aprender solo sobre árboles", "Aprender sobre la ciudadanía y la vida pública", "Aprender solo sobre deporte"], "answer": 2, "explain": "La educación cívica ayuda a los estudiantes a participar de forma responsable en su comunidad.", "src": "UNESCO"}, {"ch": 4, "q": "¿Por qué se enseña la comprensión cultural?", "options": ["Impide que las personas viajen", "Hace que todas las culturas sean idénticas", "Es solo para turistas", "Ayuda a respetar distintas formas de vida"], "answer": 3, "explain": "La comprensión cultural reduce los prejuicios y fomenta el respeto.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es el aprendizaje basado en problemas?", "options": ["Aprender resolviendo problemas reales", "Aprender memorizando listas", "Aprender evitando las preguntas", "Aprender copiando solo apuntes"], "answer": 0, "explain": "El aprendizaje basado en problemas desarrolla el pensamiento al enfrentarse a retos reales.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué significa pobreza en educación?", "options": ["Tener demasiados libros en la estantería del aula", "Falta de dinero que limita el acceso al aprendizaje", "Tener demasiados maestros para el número de alumnos", "Tener demasiadas vacaciones durante el curso"], "answer": 1, "explain": "La pobreza puede limitar el acceso a la escuela, la comida, el transporte y los materiales.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué es una disparidad étnica en educación?", "options": ["Diferencias en el color de las mochilas", "Diferencias solo en las vacaciones escolares", "Diferencias en los resultados escolares entre grupos étnicos", "Diferencias en los zapatos del colegio"], "answer": 2, "explain": "Las disparidades étnicas muestran que algunos grupos logran menos, lo que puede reflejar barreras injustas.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué es una disparidad rural-urbana?", "options": ["Diferencias en el número de parques de la ciudad", "Diferencias en las lluvias", "Diferencias en los uniformes escolares", "Diferencias entre aprender en zonas rurales y en zonas urbanas"], "answer": 3, "explain": "Las zonas rurales suelen tener menos recursos, lo que puede ampliar las brechas de aprendizaje.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué mide un quintil de riqueza?", "options": ["Dividir los hogares en cinco grupos según su riqueza", "Cinco tipos de autobús escolar usados en toda la ciudad", "Cinco formas de hacer un examen a una clase entera cada año", "Cinco colores de tiza usados en cada aula de la escuela"], "answer": 0, "explain": "Los quintiles de riqueza dividen a las familias en cinco grupos para comparar los resultados educativos.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué es una política pro pobres en educación?", "options": ["Una política que solo ayuda a los más ricos", "Una política que se dirige a los estudiantes más pobres", "Una política que cierra escuelas en zonas pobres", "Una política que sube las cuotas a los pobres"], "answer": 1, "explain": "Las políticas pro pobres concentran los recursos en quienes más los necesitan.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es la igualdad de oportunidades en educación?", "options": ["Solo los mejores estudiantes tienen oportunidades", "Las oportunidades dependen de la riqueza familiar", "Tener la misma posibilidad de tener éxito, sin importar el origen", "Las oportunidades solo se dan en las ciudades"], "answer": 2, "explain": "La igualdad de oportunidades significa que el origen no debe decidir lo que un estudiante puede lograr.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué es la brecha salarial docente?", "options": ["Los maestros cobran más que los médicos", "Los maestros cobran en oro", "Los maestros nunca cobran", "Los maestros cobran menos que profesionales similares"], "answer": 3, "explain": "Una brecha salarial significa que los maestros ganan menos que trabajadores comparables, lo que hace la profesión menos atractiva.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué el salario docente importa para el aprendizaje?", "options": ["Afecta a quién se convierte en maestro y a quién se queda", "No tiene relación con el aprendizaje", "Solo afecta a los edificios escolares", "Solo afecta a las vacaciones"], "answer": 0, "explain": "El salario influye en que las personas capaces elijan la docencia y permanezcan en ella.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la habilitación docente?", "options": ["Un permiso para vender comida escolar", "El permiso oficial para enseñar", "Un permiso para construir escuelas", "Un permiso para operar un servicio de autobús"], "answer": 1, "explain": "La habilitación establece requisitos mínimos para las personas que enseñan.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un programa de inducción docente?", "options": ["Formación para conductores de autobuses escolares", "Formación para cocineros", "Apoyo a los maestros en sus primeros años", "Formación solo para padres"], "answer": 2, "explain": "La inducción ayuda a los nuevos maestros a adaptarse y mejorar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la movilidad docente?", "options": ["Maestros que viajan en avión", "Maestros que corren carreras", "Maestros que se quedan en una sola aula para siempre", "El traslado de maestros entre escuelas o zonas"], "answer": 3, "explain": "La movilidad docente influye en qué zonas tienen suficientes maestros cualificados.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la diversidad docente?", "options": ["Maestros de distintos orígenes en las escuelas", "Maestros que tienen todos el mismo aspecto", "Maestros que hablan solo un idioma", "Maestros sin formación"], "answer": 0, "explain": "Un cuerpo docente diverso puede ayudar a los estudiantes a verse reflejados en sus maestros.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "¿Qué es el liderazgo pedagógico?", "options": ["Directivos centrados solo en el deporte", "Directivos escolares centrados en la enseñanza y el aprendizaje", "Directivos centrados en las vacaciones", "Directivos que evitan a los maestros"], "answer": 1, "explain": "Los líderes pedagógicos ayudan a los maestros a mejorar su práctica en el aula.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué las escuelas necesitan directivos?", "options": ["Reemplazan a los maestros en cada aula", "Enseñan solo deporte y educación física", "Orientan la enseñanza y gestionan la escuela", "No se necesitan en una escuela bien gestionada"], "answer": 2, "explain": "Los directivos apoyan a los maestros y marcan la dirección del aprendizaje.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es la financiación sostenible para la educación?", "options": ["Dinero que se gasta una vez y nunca más", "Dinero recaudado solo con una lotería", "Dinero gastado solo en edificios", "Fondos que se mantienen a largo plazo"], "answer": 3, "explain": "La financiación sostenible significa fondos fiables que se mantienen durante muchos años.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué es la ayuda para la educación?", "options": ["Dinero o apoyo que dan otros países u organizaciones", "Dinero que los maestros dan a su escuela para materiales", "Dinero que procede solo de las cuotas que pagan los padres", "Dinero recaudado solo con ventas escolares, rifas y ferias"], "answer": 0, "explain": "La ayuda a la educación procede de donantes que apoyan a escuelas de otros países.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué significa AOD?", "options": ["Acceso Digital Oficial", "Asistencia Oficial para el Desarrollo", "Archivo Abierto de Documentos", "Asistencia Diaria en Línea"], "answer": 1, "explain": "AOD significa Asistencia Oficial para el Desarrollo, que incluye la ayuda a la educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la movilización de recursos nacionales?", "options": ["Recaudar dinero solo de otros países", "Recaudar dinero vendiendo escuelas", "Recaudar dinero dentro del país para los servicios públicos", "Recaudar dinero de la Luna"], "answer": 2, "explain": "Los países recaudan dinero mediante impuestos y otros ingresos internos para las escuelas.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Por qué algunos países dependen de la ayuda externa para la educación?", "options": ["Tienen dinero ilimitado", "No quieren escuelas", "No pueden gastar dinero", "Sus propios recursos son limitados"], "answer": 3, "explain": "Los recursos nacionales limitados pueden implicar depender de apoyo externo.", "src": "UNESCO"}, {"ch": 7, "q": "¿Para qué se usa un fondo para la educación?", "options": ["Pagar la escolarización y los programas de aprendizaje", "Pagar vacaciones familiares y viajes de verano", "Pagar coches nuevos para el personal de la escuela", "Pagar entradas para grandes eventos deportivos"], "answer": 0, "explain": "Los fondos para la educación pagan la escolarización, los materiales y los programas.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué produjo la conferencia de Jomtien de 1990?", "options": ["Un reglamento de fútbol solo para torneos escolares", "Una declaración sobre la satisfacción de las necesidades básicas de aprendizaje", "Una lista de las vacaciones escolares de todos los años", "Una nueva moneda introducida en toda la región ese año"], "answer": 1, "explain": "La Declaración Mundial sobre Educación para Todos se aprobó en Jomtien en 1990.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué es la Declaración Mundial sobre Educación para Todos?", "options": ["Un plan deportivo de 2030 para todas las selecciones nacionales", "Un código de uniforme escolar que se aplica a todos los estudiantes", "Una declaración de 1990 que promete educación para todos", "Una ley salarial docente aprobada por el parlamento el año pasado"], "answer": 2, "explain": "La declaración se aprobó en Jomtien en 1990 y estableció la Educación para Todos.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué evento de 2000 aprobó el Marco de Dakar?", "options": ["Una Copa Mundial de fútbol", "Unos Juegos Olímpicos", "Una cumbre comercial", "El Foro Mundial sobre la Educación"], "answer": 3, "explain": "El Marco de Dakar se aprobó en el Foro Mundial sobre la Educación de 2000.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿A qué se comprometió la Declaración de Incheon?", "options": ["A una educación inclusiva, equitativa y de calidad para el aprendizaje permanente", "Solo a estudios universitarios para un pequeño grupo de los mejores estudiantes", "Solo a deportes y juegos para el equipo de la escuela cada semana", "Solo a vacaciones y días libres para todos los estudiantes"], "answer": 0, "explain": "La Declaración de Incheon comprometió a los países con oportunidades de aprendizaje a lo largo de la vida.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Qué incluyó el Marco de Dakar además de la escolarización infantil?", "options": ["La alfabetización solo para maestros", "La alfabetización de adultos y la igualdad de género", "La alfabetización solo en deporte", "La alfabetización solo para países ricos"], "answer": 1, "explain": "El Marco de Dakar incluía objetivos de alfabetización de adultos e igualdad de género.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué Objetivo de Desarrollo del Milenio buscaba promover la igualdad de género?", "options": ["Objetivo 1", "Objetivo 5", "Objetivo 3", "Objetivo 6"], "answer": 2, "explain": "El ODM 3 buscaba promover la igualdad de género y el empoderamiento de las mujeres.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 8, "q": "¿Qué pretendían reducir los ODM?", "options": ["El deporte", "Las escuelas", "Las vacaciones", "La pobreza extrema y el hambre"], "answer": 3, "explain": "Entre otros objetivos, los ODM buscaban reducir la pobreza extrema y el hambre.", "src": "UN Millennium Development Goals (2000)"}, {"ch": 9, "q": "¿Qué es un aprendizaje temprano de calidad?", "options": ["Un aprendizaje receptivo, lúdico y de apoyo", "Un aprendizaje estricto y silencioso", "Un aprendizaje basado solo en fichas", "Un aprendizaje que evita a los adultos"], "answer": 0, "explain": "El aprendizaje temprano de calidad desarrolla habilidades mediante interacciones cálidas y lúdicas.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué es importante detectar pronto los retrasos?", "options": ["Los problemas deben ignorarse hasta la escuela", "El apoyo puede empezar mientras el cerebro se desarrolla rápidamente", "Los niños deben ser etiquetados de por vida", "Hay que culpar a los padres"], "answer": 1, "explain": "La detección temprana permite iniciar el apoyo mientras el cerebro se desarrolla con rapidez.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué es importante el personal de primera infancia?", "options": ["No se necesita personal", "El personal solo limpia las salas", "El personal cualificado marca una gran diferencia en los niños", "El personal no afecta a los niños"], "answer": 2, "explain": "El personal de primera infancia formado influye en el aprendizaje y el bienestar de los niños.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es un espacio amigable para la infancia?", "options": ["Una tienda que vende solo juguetes y caramelos para niños", "Un edificio sin ventanas ni puertas para los alumnos", "Una sala donde los niños están apartados de los demás todo el día", "Un lugar seguro donde los niños pueden aprender y jugar"], "answer": 3, "explain": "Los espacios amigables para la infancia ofrecen lugares seguros para aprender y jugar, sobre todo en crisis.", "src": "UNESCO GEM Report 2026"}, {"ch": 9, "q": "¿Qué significa un entorno estimulante para los bebés?", "options": ["Mucha conversación, contacto y juego", "Silencio total", "Habitaciones oscuras", "Ruido constante y fuerte"], "answer": 0, "explain": "Los entornos estimulantes favorecen el desarrollo del cerebro mediante la interacción.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué la primera infancia es una prioridad de política?", "options": ["No aporta ningún beneficio a niños ni familias", "La inversión temprana produce altos beneficios después", "Solo cuesta dinero y no devuelve nada", "Solo ayuda a adultos que ya trabajan"], "answer": 1, "explain": "La inversión temprana ayuda a los niños a aprender y reduce costos futuros.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es la alfabetización emergente?", "options": ["Alfabetización solo para adultos", "Leer solo en la universidad", "Habilidades tempranas que conducen a la lectura y la escritura", "Leer solo números"], "answer": 2, "explain": "La alfabetización emergente abarca habilidades tempranas, como el conocimiento de las letras y las rimas, que conducen a la lectura.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es la conciencia de rimas?", "options": ["Pintar rimas en las paredes", "Cantar solo canciones fuertes", "Escribir rimas solo en papel", "Oír y producir sonidos que riman"], "answer": 3, "explain": "La conciencia de rimas ayuda a los niños a oír los sonidos dentro de las palabras.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué incluye la alfabetización bilingüe?", "options": ["Leer y escribir en dos idiomas", "Solo leer números", "Solo dibujar", "Solo escuchar"], "answer": 0, "explain": "La alfabetización bilingüe desarrolla la lectura en dos idiomas.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "¿Por qué la alfabetización está relacionada con el empleo?", "options": ["Los empleos nunca necesitan leer", "Muchos empleos exigen leer y escribir", "La alfabetización es solo para maestros", "La alfabetización no tiene relación con los empleos"], "answer": 1, "explain": "La alfabetización ayuda a leer instrucciones, redactar informes y aprender nuevas habilidades.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es la alfabetización informacional?", "options": ["Ocultar la información a quienes te rodean", "Memorizar cada página de cada libro que lees", "Encontrar, valorar y usar bien la información", "Ignorar las noticias y los acontecimientos actuales"], "answer": 2, "explain": "La alfabetización informacional ayuda a valorar las fuentes y a usar la información de forma responsable.", "src": "UNESCO"}, {"ch": 10, "q": "¿Por qué muchos países usan lenguas locales en la lectura inicial?", "options": ["No se permiten las lenguas locales", "Las lenguas locales dificultan la lectura", "Las lenguas locales son solo para adultos", "Los niños aprenden mejor en una lengua que hablan"], "answer": 3, "explain": "La lectura inicial es más fácil cuando los niños entienden las palabras que ven.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "¿Por qué es importante la práctica de la escritura?", "options": ["Convierte el conocimiento de la lectura en comunicación", "No tiene ninguna relación con las habilidades de lectura", "Solo importa para los estudiantes de arte", "Reemplaza la lectura por dibujar imágenes"], "answer": 0, "explain": "La práctica de la escritura ayuda a los estudiantes a expresar ideas y profundizar la lectura.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "¿Qué es un currículo inclusivo?", "options": ["Un currículo que excluye a algunos estudiantes", "Un currículo que valora e incluye a todos los estudiantes", "Un currículo solo para un grupo", "Un currículo sin asignaturas"], "answer": 1, "explain": "Los currículos inclusivos reflejan las necesidades y las identidades de todos los estudiantes.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la enseñanza multisensorial?", "options": ["Usar solo el sonido", "Enseñar en silencio", "Usar la vista, el oído y el tacto en las lecciones", "Enseñar solo con los ojos vendados"], "answer": 2, "explain": "La enseñanza multisensorial ayuda a los estudiantes que aprenden mejor de distintas maneras.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la tecnología de apoyo en educación?", "options": ["Juegos que hacen mucho más difícil aprender para todos los estudiantes", "Herramientas que impiden que los estudiantes lean sus libros", "Equipos usados solo para deporte y juegos", "Herramientas que ayudan a los estudiantes con discapacidad a participar"], "answer": 3, "explain": "La tecnología de apoyo incluye lectores de pantalla, audífonos y ayudas para la comunicación.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es un ajuste razonable para los exámenes?", "options": ["Cambios como tiempo extra o un lector", "Eliminar el examen por completo para todos", "Hacer los exámenes más difíciles para algunos", "Cobrar más por los exámenes"], "answer": 0, "explain": "Los ajustes hacen que los exámenes sean justos sin cambiar lo que se evalúa.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué deberían las escuelas recopilar datos sobre discapacidad?", "options": ["Para clasificar a los niños por discapacidad", "Para planificar apoyos y hacer seguimiento de la inclusión", "Para impedir que los niños se matriculen", "Para vender material escolar"], "answer": 1, "explain": "Los datos sobre discapacidad ayudan a las escuelas a planificar apoyos y a comprobar si los niños están incluidos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es un estereotipo en educación?", "options": ["Un tipo de examen escolar que se hace una vez al año", "Una ruta de autobús escolar que pasa por la granja", "Una idea fija y a menudo injusta sobre un grupo", "Un tipo de mochila que contiene muchos libros"], "answer": 2, "explain": "Los estereotipos pueden limitar lo que los estudiantes creen que pueden lograr.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Qué es el sentido de pertenencia en una escuela?", "options": ["Estar solo en clase", "Ser apartado de las lecciones", "Ser trasladado a otra ciudad", "Sentirse aceptado y valorado"], "answer": 3, "explain": "El sentido de pertenencia ayuda a los estudiantes a implicarse y a permanecer en la escuela.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Qué significa acceso universal en discapacidad?", "options": ["Acceso para todos, incluidas las personas con discapacidad", "Acceso solo para personas sin discapacidad", "Acceso solo en un edificio", "Acceso solo en días especiales"], "answer": 0, "explain": "El acceso universal significa que la educación está abierta a todos, con el apoyo que cada persona necesita.", "src": "UN CRPD (2006), Article 24"}], "10": [{"ch": 0, "q": "¿Qué principio significa que la Agenda 2030 busca llegar primero a quienes están más rezagados?", "options": ["No dejar a nadie atrás", "La supervivencia del más apto", "El crecimiento a cualquier costo", "Cada país por su cuenta"], "answer": 0, "explain": "No dejar a nadie atrás significa dar prioridad a las personas más desfavorecidas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué indicador del ODS 4 mide la participación en el aprendizaje organizado un año antes de la primaria?", "options": ["Indicador 4.1.1", "Indicador 4.2.2", "Indicador 4.5.1", "Indicador 4.7.1"], "answer": 1, "explain": "El indicador 4.2.2 mide la participación en el aprendizaje organizado un año antes de la edad oficial de ingreso a la primaria.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "¿Cuál es el propósito de las metas 4.a a 4.c?", "options": ["Redactar las preguntas de los exámenes", "Elegir los colores de la escuela", "Proporcionar los medios para impartir educación", "Cerrar las universidades"], "answer": 2, "explain": "Estas metas se centran en instalaciones, becas y oferta de docentes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Por qué se miden las metas del ODS 4 con indicadores y datos?", "options": ["Para que los informes sean más largos", "Para evitar tomar decisiones", "Para reemplazar a los docentes", "Para comprobar si el progreso es real y justo"], "answer": 3, "explain": "Los indicadores y los datos desagregados muestran el progreso y la desigualdad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Cuál es la relación entre el ODS 4 y el ODS 1 (Fin de la pobreza)?", "options": ["La educación ayuda a reducir la pobreza y la pobreza limita la educación", "No tienen ninguna relación entre sí en ningún país", "La educación causa pobreza y empobrece a las familias cada año", "La pobreza solo afecta el rendimiento deportivo de los niños en la escuela"], "answer": 0, "explain": "La educación y la pobreza están estrechamente vinculadas en ambos sentidos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué es una línea de base en el seguimiento de los ODS?", "options": ["La meta que marca el final de una carrera larga", "El punto de partida con el que se mide el progreso", "El fondo de una mochila escolar donde se guardan libros viejos", "El precio de un libro de texto nuevo en la tienda local"], "answer": 1, "explain": "Una línea de base es el dato inicial que se usa para medir el cambio.", "src": "UN SDG Report 2026"}, {"ch": 1, "q": "¿Qué es la educación obligatoria?", "options": ["La educación optativa para todos", "La educación solo para adultos", "La educación que la ley exige que los niños cursen", "La educación prohibida"], "answer": 2, "explain": "La educación obligatoria significa que los niños deben asistir a la escuela hasta una edad legal.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es una transferencia monetaria condicionada para la educación?", "options": ["Dinero que se entrega a los docentes para sus vacaciones", "Dinero que pagan solo los donantes para las cuotas escolares", "Dinero que se usa solo para construir carreteras", "Dinero que se entrega a las familias si los niños asisten a la escuela"], "answer": 3, "explain": "Las transferencias monetarias condicionadas animan a las familias a enviar a sus hijos a la escuela.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué los gobiernos eliminan las cuotas escolares?", "options": ["Para ampliar el acceso de las familias pobres", "Para reducir el número de alumnos", "Para que las escuelas sean menos útiles", "Para dejar de pagar a los docentes"], "answer": 0, "explain": "Eliminar las cuotas ayuda a que los niños más pobres se matriculen y permanezcan.", "src": "UNESCO"}, {"ch": 1, "q": "¿Quiénes son los adolescentes fuera de la escuela?", "options": ["Adultos que estudian en línea desde casa con regularidad", "Jóvenes en edad de secundaria que no asisten a la escuela", "Niños de preescolar que juegan en el jardín todo el día", "Docentes que se encuentran de licencia en su escuela este año"], "answer": 1, "explain": "Los adolescentes fuera de la escuela son jóvenes que no están matriculados en ningún centro educativo.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es la escolarización flexible para los niños?", "options": ["Una escolarización sin reglas ni horario para los niños", "Una escolarización solo de noche para todos los habitantes del pueblo", "Una escolarización organizada en torno al trabajo o las necesidades familiares de los niños", "Una escolarización sin docentes presentes en el aula en ningún momento"], "answer": 2, "explain": "La escolarización flexible ayuda a los niños que no pueden asistir a tiempo completo.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué es importante el transporte seguro para el acceso de las niñas a la escuela?", "options": ["El transporte nunca es necesario para ningún viaje escolar", "Las niñas no pueden viajar a ningún lugar fuera de su casa", "Las niñas prefieren caminar muy lejos para llegar a la escuela", "Los trayectos inseguros o largos pueden mantener a las niñas en casa"], "answer": 3, "explain": "Un transporte seguro puede marcar una gran diferencia en la asistencia de las niñas.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 1, "q": "¿Qué es una campaña de matrícula?", "options": ["Una campaña para llevar a los niños a la escuela", "Una carrera de autos", "Solo una cena para recaudar fondos escolares", "Un torneo deportivo"], "answer": 0, "explain": "Las campañas de matrícula animan a las familias a inscribir a sus hijos en la escuela.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué significa completar la secundaria baja?", "options": ["Terminar el preescolar", "Terminar la primera etapa de la secundaria", "Terminar la universidad", "Terminar un curso de vacaciones"], "answer": 1, "explain": "La secundaria baja es la primera etapa de la educación secundaria.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué los adolescentes abandonan los estudios en muchos países?", "options": ["Terminan la escuela demasiado pronto cada año", "Todos obtienen becas para las mejores escuelas", "La presión del trabajo, el costo y un aprendizaje que parece irrelevante", "Tienen muchísimas vacaciones y días libres durante el trimestre"], "answer": 2, "explain": "La presión del trabajo, el costo y un aprendizaje que parece irrelevante suelen llevar a los estudiantes a abandonar.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué es una trayectoria de aprendizaje para jóvenes que dejaron la escuela?", "options": ["Una vía hacia una tienda donde se venden productos a los clientes", "Una vía que no conduce a ninguna titulación al final", "Una vía abierta solo a docentes y personal calificado", "Una vía para volver a estudiar con títulos reconocidos"], "answer": 3, "explain": "Las trayectorias ayudan a los jóvenes a regresar al aprendizaje y obtener titulaciones.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué completar la secundaria superior está vinculado con el empleo?", "options": ["Abre más opciones de trabajo y de formación", "Elimina todas las oportunidades de trabajo", "Significa que no habrá más aprendizaje", "Solo ayuda a los artistas"], "answer": 0, "explain": "Completar la secundaria superior amplía el acceso al empleo y a estudios posteriores.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es una intervención escolar para mantener a los niños en la escuela?", "options": ["Cerrar la escuela más temprano todos los días de la semana", "Una acción de apoyo dentro de la escuela, como la tutoría", "Quitar todas las clases del horario escolar cada semana", "Ignorar a los estudiantes que llevan semanas sin asistir"], "answer": 1, "explain": "El apoyo escolar ayuda a los estudiantes en riesgo de abandono.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué el apoyo en efectivo y en alimentos se relaciona con completar los estudios?", "options": ["Reemplazan toda la enseñanza que ocurre en el aula", "Hacen que más niños abandonen la escuela cada año", "Reducen los costos que empujan a los niños fuera de la escuela", "Hacen que la jornada escolar sea mucho más larga y agotadora"], "answer": 2, "explain": "El apoyo para cubrir costos puede ayudar a los niños a quedarse hasta terminar.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué algunos estudiantes abandonan tras reprobar exámenes repetidamente?", "options": ["Los exámenes nunca se reprueban", "Reprobar exámenes ayuda a los estudiantes", "Se premia el fracaso", "Los fracasos repetidos pueden desanimar a los estudiantes"], "answer": 3, "explain": "Los fracasos repetidos sin apoyo pueden hacer que los estudiantes pierdan la confianza y abandonen.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es la Enseñanza en el Nivel Adecuado?", "options": ["Agrupar a los estudiantes según su nivel de habilidad y no por su edad", "Enseñar solo a los estudiantes mayores", "Enseñar solo en inglés", "Enseñar sin ningún plan"], "answer": 0, "explain": "La Enseñanza en el Nivel Adecuado agrupa a los estudiantes según lo que ya saben hacer.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es el aprendizaje fundamental?", "options": ["Investigación universitaria avanzada en ciencias, derecho y medicina", "Lectura, escritura y cálculo básicos que sostienen el aprendizaje posterior", "Solo educación física y deporte durante todo el año escolar", "Solo historia del arte y estudio de la pintura y la escultura antiguas"], "answer": 1, "explain": "El aprendizaje fundamental es la base de toda la educación posterior.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué estudio internacional evalúa la lectura en primaria?", "options": ["PISA", "TIMSS", "PIRLS", "Prueba OACI"], "answer": 2, "explain": "PIRLS, el Estudio Internacional de Progreso en Comprensión Lectora, evalúa la lectura en primaria.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué mide TIMSS?", "options": ["La música y la danza", "El deporte y la condición física", "Las habilidades culinarias", "El logro en matemáticas y ciencias"], "answer": 3, "explain": "TIMSS, el Estudio de Tendencias en Matemáticas y Ciencias, mide el logro en matemáticas y ciencias.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es una prueba de bajo impacto?", "options": ["Una prueba cuyos resultados no deciden el futuro del estudiante", "Una prueba que decide quién es expulsado", "Una prueba sin preguntas", "Una prueba usada solo para contratar docentes"], "answer": 0, "explain": "Las pruebas de bajo impacto permiten a los docentes ver el aprendizaje sin presión alta.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué los resultados de aprendizaje varían dentro de un país?", "options": ["Solo el clima cambia los resultados de una escuela a otra", "El ingreso, el idioma, la ubicación y el género influyen", "Solo el color de la escuela determina el rendimiento de los alumnos", "Solo el horario del autobús determina el rendimiento de los alumnos"], "answer": 1, "explain": "Los resultados de aprendizaje están determinados por muchos factores sociales y económicos.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es una habilidad cognitiva en el aprendizaje?", "options": ["Habilidades para dormir profundamente cada noche", "Habilidades para jugar al fútbol en el equipo de la escuela todo el año", "Habilidades de pensamiento como la memoria, el razonamiento y la resolución de problemas", "Habilidades para cocinar comidas sencillas en casa para la familia"], "answer": 2, "explain": "Las habilidades cognitivas sostienen el razonamiento y el aprendizaje en todas las materias.", "src": "UNESCO"}, {"ch": 3, "q": "¿Por qué son importantes las evaluaciones del aprendizaje para las políticas?", "options": ["Reemplazan a las escuelas en cada comunidad del país", "Solo dan premios a los alumnos más destacados cada año", "Eliminan la necesidad de docentes en cualquier escuela", "Muestran dónde el aprendizaje es más débil y necesita apoyo"], "answer": 3, "explain": "Los datos de evaluación ayudan a los gobiernos a decidir dónde invertir y apoyar.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "¿Cuáles son las cuatro C de las habilidades del siglo XXI?", "options": ["Creatividad, pensamiento crítico, comunicación y colaboración", "Cocinar, limpiar, andar en bicicleta y colorear en la escuela cada semana", "Calcular, contar, copiar y programar en el laboratorio de informática", "Animar, entrenar, competir y cocinar para el equipo de la escuela"], "answer": 0, "explain": "Las cuatro C se usan ampliamente para describir habilidades clave para el trabajo y la vida modernos.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué significa STEM?", "options": ["Deportes, enseñanza, exámenes y música", "Ciencia, tecnología, ingeniería y matemáticas", "Expresión oral, teatro, edición y mercados", "Sociología, turismo, economía y medios"], "answer": 1, "explain": "STEM abarca ciencia, tecnología, ingeniería y matemáticas.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la seguridad digital para los estudiantes?", "options": ["Compartir contraseñas con todas las personas que se conocen en línea cada día", "Ignorar la privacidad en línea y compartir cada foto", "Proteger los datos personales y reconocer los riesgos en línea", "Conocer en persona a extraños de internet y mantenerlo en secreto"], "answer": 2, "explain": "La seguridad digital ayuda a los estudiantes a proteger su información y a estar seguros en línea.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es el uso ético de la tecnología en el aprendizaje?", "options": ["Copiar el trabajo de otros sin darles crédito", "Acosar a los compañeros en línea", "Compartir fotos privadas", "Usarla con honestidad, respeto y consentimiento"], "answer": 3, "explain": "El uso ético de la tecnología respeta a los demás y la honestidad académica.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es un marco de competencias?", "options": ["Una lista de habilidades y conocimientos que debe adquirir un estudiante", "Un tipo de edificio escolar con varios pisos y aulas", "Una lista de deportes, juegos y clubes escolares a los que unirse", "Un plan solo para exámenes y pruebas, sin otro aprendizaje"], "answer": 0, "explain": "Los marcos de competencias establecen lo que los estudiantes deben ser capaces de hacer.", "src": "UNESCO"}, {"ch": 4, "q": "¿Por qué el emprendimiento se relaciona con el ODS 4?", "options": ["No tiene ninguna relación con el empleo ni con la resolución de problemas", "Desarrolla habilidades para crear empleos y resolver problemas", "Enseña solo ventas y administración de tiendas", "Impide que las personas consigan algún trabajo"], "answer": 1, "explain": "El emprendimiento desarrolla la iniciativa y la capacidad para resolver problemas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es una brecha de habilidades?", "options": ["Una grieta en la pared de la escuela que necesita reparación urgente este trimestre", "Un recreo entre dos clases largas en un día escolar muy ocupado", "Un desajuste entre las habilidades que tienen las personas y las que exigen los empleos", "Un examen que falta en el horario escolar de este trimestre"], "answer": 2, "explain": "Las brechas de habilidades dificultan que las personas encuentren trabajo y que los empleadores cubran sus vacantes.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Por qué es importante la EFTP para el empleo juvenil?", "options": ["Reemplaza todo el aprendizaje académico", "Es solo para adultos", "Nunca resulta útil", "Ofrece habilidades prácticas vinculadas con el trabajo"], "answer": 3, "explain": "La EFTP ofrece a los jóvenes habilidades listas para el empleo y vías de acceso al trabajo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es una barrera de aprendizaje basada en el género?", "options": ["Una regla o norma que dificulta el aprendizaje de un género", "Una barrera que ayuda a todos los estudiantes a aprender mucho mejor", "Una barrera que solo afecta a los docentes de la escuela", "Una barrera que no tiene ningún efecto real en el aprendizaje"], "answer": 0, "explain": "Las barreras basadas en el género incluyen normas y prácticas que limitan el aprendizaje de niñas o niños.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Cómo puede afectar a las niñas en la escuela la falta de instalaciones de higiene?", "options": ["No tiene ninguna relación con la asistencia escolar en ningún país", "Las niñas pueden faltar a clase sin baños privados ni artículos de higiene", "Solo afecta a los niños que estudian en la misma escuela", "Es una asignatura que se imparte a los estudiantes de noveno grado"], "answer": 1, "explain": "El acceso a la higiene y a baños privados ayuda a que las niñas permanezcan en la escuela.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué busca una política contra el trabajo infantil?", "options": ["Obligar a los niños a trabajar muchas horas en el campo cada día", "Impedir toda educación para los niños del pueblo y de la ciudad", "Proteger a los niños de trabajos que perjudican su aprendizaje y su salud", "Pagar a los niños para que falten a la escuela y se queden en casa"], "answer": 2, "explain": "Las políticas contra el trabajo infantil protegen el derecho de los niños a aprender y a estar sanos.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué significa grupo minoritario en la educación?", "options": ["Un grupo que siempre es el más rico", "Un grupo que siempre obtiene los mejores resultados en los exámenes", "Un grupo que nunca asiste a la escuela", "Un grupo más pequeño que la población principal"], "answer": 3, "explain": "Un grupo minoritario es un grupo más pequeño dentro de una población, que puede enfrentar barreras.", "src": "UNESCO"}, {"ch": 5, "q": "¿Por qué los estudiantes indígenas suelen necesitar una educación culturalmente pertinente?", "options": ["Respeta su identidad y mejora el aprendizaje", "Reemplaza su idioma por otro por completo", "No es necesaria en ninguna escuela en ningún lugar", "Solo afecta los deportes y juegos de la escuela"], "answer": 0, "explain": "La educación culturalmente pertinente ayuda a los estudiantes indígenas a sentirse valorados y a aprender mejor.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es la focalización en una política de equidad?", "options": ["Dar recursos a los más ricos", "Concentrar los recursos en los grupos que quedan rezagados", "Dar los mismos recursos solo a los más fuertes", "Ignorar a los grupos necesitados"], "answer": 1, "explain": "La focalización concentra los esfuerzos en los grupos que más lo necesitan.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es un currículo sensible al género?", "options": ["Un currículo solo para niños, impartido en todas las escuelas", "Un currículo que enseña estereotipos sobre niñas y niños", "Un currículo que evita los estereotipos y trata a todos los estudiantes por igual", "Un currículo sin materias para ningún alumno"], "answer": 2, "explain": "Los currículos sensibles al género desafían los estereotipos y apoyan a todos los estudiantes.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué describe la discriminación interseccional?", "options": ["La discriminación en un solo lugar", "Una discriminación siempre justa", "La discriminación solo contra los docentes", "Varias formas de discriminación que se superponen"], "answer": 3, "explain": "La discriminación interseccional ocurre cuando varias identidades se combinan y generan desventajas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Qué es la oferta docente en la Meta 4.c?", "options": ["La cantidad de docentes calificados disponibles", "La cantidad de vacaciones", "La cantidad de timbres escolares", "La cantidad de pupitres"], "answer": 0, "explain": "La meta 4.c se centra en aumentar la oferta de docentes calificados.", "src": "UN 2030 Agenda (2015)"}, {"ch": 6, "q": "¿Por qué los países necesitan contratar más docentes?", "options": ["Porque los docentes no son necesarios", "Para satisfacer la demanda creciente y reemplazar a quienes se van", "Para reducir el tamaño de las clases a cero", "Para cerrar escuelas"], "answer": 1, "explain": "La contratación es necesaria para seguir el ritmo del crecimiento de la matrícula y las jubilaciones.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la docencia por contrato?", "options": ["Enseñar con una promesa de empleo de por vida", "Enseñar sin recibir pago", "Enseñar con contratos cortos y temporales", "Enseñar solo por teléfono"], "answer": 2, "explain": "Los docentes por contrato suelen tener menos estabilidad, lo que puede afectar su permanencia.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué significa la formación docente inicial?", "options": ["Formación después de jubilarse", "Formación solo para directores", "Formación para padres", "Formación antes de empezar a enseñar"], "answer": 3, "explain": "La formación inicial prepara a las personas antes de que comiencen a enseñar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué significa la formación docente en servicio?", "options": ["Formación mientras ya se está enseñando", "Formación para personas que no enseñan", "Formación solo durante las vacaciones por ley", "Formación que reemplaza toda la enseñanza"], "answer": 0, "explain": "La formación en servicio ayuda a los docentes a seguir mejorando en su trabajo.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es un código de conducta docente?", "options": ["Un lenguaje secreto de los docentes que solo usa el personal", "Normas que establecen el comportamiento profesional esperado", "Una lista de vacaciones de los docentes para todo el año", "Una norma de vestimenta escolar que solo se aplica a los docentes"], "answer": 1, "explain": "Los códigos de conducta establecen cómo deben comportarse los docentes con los estudiantes.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué los docentes necesitan formación en enseñanza inclusiva?", "options": ["No es necesaria", "Para poder evitar a los estudiantes", "Para apoyar a estudiantes con necesidades diferentes", "Para poder enseñar menos materias"], "answer": 2, "explain": "La formación inclusiva ayuda a los docentes a atender una gama amplia de necesidades.", "src": "UN CRPD (2006), Article 24"}, {"ch": 6, "q": "¿Qué es el agotamiento docente?", "options": ["Docentes demasiado enérgicos", "Docentes que enseñan demasiado bien", "Docentes que ganan demasiado", "Un cansancio prolongado causado por un trabajo estresante"], "answer": 3, "explain": "El agotamiento reduce el bienestar y puede llevar a los docentes a dejar la profesión.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué mide la brecha de financiamiento del ODS 4?", "options": ["El dinero adicional necesario además del gasto actual", "El dinero gastado en deportes", "El dinero ahorrado en bancos", "El dinero pagado a los vendedores de la escuela"], "answer": 0, "explain": "La brecha de financiamiento muestra cuánto más se necesita para alcanzar las metas educativas.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "¿Qué aporta la recaudación tributaria a la educación?", "options": ["El dinero que solo paga vacaciones", "El dinero que los gobiernos usan para financiar las escuelas", "El dinero que reemplaza a los docentes", "El dinero que siempre se desperdicia"], "answer": 1, "explain": "La recaudación tributaria es una fuente principal de financiamiento público para la educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es el financiamiento extrapresupuestario para la educación?", "options": ["Dinero gastado en vacaciones", "Dinero guardado debajo de la cama", "Dinero gastado fuera del presupuesto oficial", "Dinero gastado en jets privados"], "answer": 2, "explain": "El financiamiento extrapresupuestario puede dificultar el seguimiento del gasto total en educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué a veces los donantes financian la educación?", "options": ["Para obtener una gran ganancia al dirigir escuelas para niños", "Para cerrar escuelas en los países más pobres cada año", "Para impedir que los niños aprendan en cualquier escuela", "Para apoyar a los niños en países con menos recursos"], "answer": 3, "explain": "Los donantes suelen financiar la educación para ayudar a los países que necesitan apoyo adicional.", "src": "UNESCO"}, {"ch": 7, "q": "¿Cómo puede la deuda afectar el gasto en educación?", "options": ["Los pagos altos de deuda pueden reducir el dinero para las escuelas", "La deuda paga automáticamente las escuelas", "La deuda no tiene ningún efecto", "La deuda solo afecta a los deportes"], "answer": 0, "explain": "Los gobiernos que gastan mucho en pagar deuda pueden tener menos recursos para la educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es una auditoría de valor por dinero en educación?", "options": ["Una verificación del precio y la calidad de los uniformes escolares", "Una verificación de si el gasto logra buenos resultados", "Una verificación de cuántos días de vacaciones toma cada docente", "Una verificación de la comida escolar que se sirve cada día al mediodía"], "answer": 1, "explain": "Las auditorías de valor por dinero comprueban si el dinero de la educación produce resultados de aprendizaje.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué las escuelas necesitan un financiamiento estable?", "options": ["Para poder cambiar el clima", "Para poder prescindir de todos los docentes", "Para poder planificar docentes, materiales y reparaciones", "Para poder cerrar temprano"], "answer": 2, "explain": "Un financiamiento estable permite a las escuelas planificar y mantener el aprendizaje en marcha.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué hace una subvención a nivel escolar?", "options": ["Da vacaciones a los docentes", "Da premios solo a los niños", "Da automóviles a las familias", "Da dinero a las escuelas para atender necesidades locales"], "answer": 3, "explain": "Las subvenciones escolares permiten a las escuelas responder a prioridades locales.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué declaración de 1994 promovió escuelas inclusivas para todos los niños?", "options": ["La Declaración de Salamanca", "La Declaración de Tokio", "El Pacto de El Cairo", "El Plan de Lima"], "answer": 0, "explain": "La Declaración de Salamanca de 1994 promovió escuelas inclusivas para todos los niños.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "¿En qué año se adoptó la Declaración de Salamanca?", "options": ["1948", "1994", "1989", "2015"], "answer": 1, "explain": "La Declaración de Salamanca se adoptó en 1994.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "¿Qué pidió la conferencia de Jomtien de 1990 más allá de la escolarización?", "options": ["Solo la escuela para adultos", "Solo el deporte", "El aprendizaje de niños, jóvenes y adultos", "Ningún aprendizaje después de los diez años"], "answer": 2, "explain": "Jomtien destacó el aprendizaje a lo largo de la vida para todas las personas.", "src": "UNESCO"}, {"ch": 8, "q": "¿Cuántas metas estableció el Marco de Acción de Dakar para la Educación para Todos?", "options": ["Tres", "Diez", "Diecisiete", "Seis"], "answer": 3, "explain": "El Marco de Acción de Dakar estableció seis metas para la Educación para Todos.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué dijo sobre la educación la Declaración Universal de los Derechos Humanos de 1948?", "options": ["Es un derecho humano", "Es un lujo", "Es solo para niños", "Es opcional"], "answer": 0, "explain": "La DUDH establece que la educación es un derecho humano.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿Por qué fue importante la conferencia de Jomtien de 1990?", "options": ["Prohibió todas las escuelas del país entero", "Fijó el compromiso mundial con la Educación para Todos", "Fijó el precio de los libros en todas las tiendas del pueblo", "Puso fin a la formación docente en la mayoría de los países ese año"], "answer": 1, "explain": "Jomtien fijó el compromiso mundial con la Educación para Todos.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué tienen en común los grandes compromisos educativos mundiales?", "options": ["Nunca se cumplen", "Son solo para escuelas privadas", "Fijan metas que los gobiernos acuerdan perseguir", "Se aplican solo a un país"], "answer": 2, "explain": "Los compromisos mundiales fijan metas compartidas que los gobiernos acuerdan alcanzar.", "src": "UNESCO"}, {"ch": 8, "q": "¿Cuándo es el Día Internacional de la Educación?", "options": ["1 de mayo", "31 de octubre", "25 de diciembre", "24 de enero"], "answer": 3, "explain": "La UNESCO conmemora el Día Internacional de la Educación el 24 de enero de cada año.", "src": "UNESCO"}, {"ch": 9, "q": "¿Qué es el Marco de Cuidado Nutritivo?", "options": ["Un marco que reúne salud, nutrición, cuidado y aprendizaje en la primera infancia", "Un plan para construir escuelas solo en las grandes ciudades del país", "Una lista de normas escolares y castigos para niños pequeños", "Un plan de deportes y juegos en el patio cada semana"], "answer": 0, "explain": "El marco vincula la salud, la nutrición, el cuidado receptivo, la seguridad y el aprendizaje en la primera infancia.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué significa la arquitectura cerebral en la primera infancia?", "options": ["La forma de un edificio escolar", "La forma en que se forman las conexiones cerebrales en la vida temprana", "El diseño de los pupitres", "La distribución de una ciudad"], "answer": 1, "explain": "Las experiencias tempranas dan forma a las conexiones que constituyen la arquitectura del cerebro.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es la participación de las familias en el aprendizaje temprano?", "options": ["Que los padres nunca asistan a ningún evento escolar", "Que los padres paguen a docentes para dar clases particulares a sus hijos", "Que los padres participen activamente en el aprendizaje de sus hijos", "Que los padres eviten a sus hijos y sus tareas por completo"], "answer": 2, "explain": "Las familias comprometidas apoyan el aprendizaje en casa y en la escuela.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué son el juego y la exploración en la primera infancia?", "options": ["Permanecer sentado durante horas sin moverse en clase", "Copiar de la pizarra durante toda la clase", "Ejercicios silenciosos repetidos todos los días en la escuela", "Actividades prácticas que ayudan a los niños a descubrir ideas"], "answer": 3, "explain": "El juego y la exploración ayudan a los niños a conocer el mundo.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué hace de calidad a la educación infantil?", "options": ["Personal capacitado, buenos espacios e interacciones cálidas", "Clases numerosas sin adultos en el aula", "Solo hojas de ejercicios repartidas sin enseñanza", "Largas horas en silencio sin adultos ni actividades"], "answer": 0, "explain": "La calidad depende de personal capacitado, espacios seguros y relaciones cálidas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es el apego en la primera infancia?", "options": ["Un tipo de juguete", "Un vínculo seguro entre el niño y su cuidador", "Un horario escolar fijo", "Un impuesto para las familias"], "answer": 1, "explain": "El apego seguro favorece el desarrollo emocional y social de los niños.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué incluye la preparación para la escuela más allá de las habilidades académicas?", "options": ["Solo leer palabras en voz alta todos los días", "Solo escribir letras y números en papel durante horas", "La salud, el bienestar emocional y las habilidades sociales", "Solo la fuerza física y la velocidad en las carreras cada trimestre"], "answer": 2, "explain": "La preparación incluye la salud y las habilidades sociales y emocionales, además de las académicas.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es un entorno de alfabetización en el hogar?", "options": ["Habitaciones silenciosas sin libros", "Solo televisión", "Ningún contacto con la familia", "Libros, conversación y una rutina de lectura en casa"], "answer": 3, "explain": "Un entorno de alfabetización en casa favorece las habilidades de lectura.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es una cultura de lectura?", "options": ["Hábitos compartidos y el valor que se da a la lectura", "Un tipo de danza que se realiza en los salones de la escuela", "Un deporte que se juega en el campo escolar", "Un sistema de timbres escolares que suena todo el día"], "answer": 0, "explain": "Una cultura de lectura hace que leer forme parte de la vida cotidiana.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Por qué a los adultos con baja alfabetización les cuesta conseguir trabajo?", "options": ["Los empleos nunca requieren leer", "Muchos empleos exigen leer y escribir", "Los adultos no encuentran trabajo de todos modos", "Los empleadores prefieren el analfabetismo"], "answer": 1, "explain": "La baja alfabetización puede limitar el acceso a muchos empleos y formaciones.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es la alfabetización posprimaria?", "options": ["La alfabetización antes del nacimiento", "La alfabetización solo en preescolar", "Las habilidades de alfabetización después de la primaria", "La alfabetización solo para docentes"], "answer": 2, "explain": "La alfabetización posprimaria desarrolla y mantiene la lectura y la escritura tras la primaria.", "src": "UNESCO"}, {"ch": 10, "q": "¿Cuál es una causa de las dificultades de lectura?", "options": ["Un tipo de dieta", "Un tipo de examen", "Un tipo de clima", "La dislexia"], "answer": 3, "explain": "Algunas dificultades de lectura se deben a la dislexia, que requiere apoyo especializado.", "src": "UN CRPD (2006), Article 24"}, {"ch": 10, "q": "¿Qué ayuda a las comunidades rurales a acceder a libros?", "options": ["Bibliotecas cercanas o el reparto de libros", "Prohibir los libros", "Vender libros a precios muy altos", "Mantener los libros solo en las ciudades"], "answer": 0, "explain": "El acceso a libros en zonas rurales puede mejorarse con bibliotecas y servicios móviles.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es una biblioteca móvil?", "options": ["Una biblioteca en un estacionamiento solamente", "Una biblioteca que viaja hacia las comunidades", "Una biblioteca que vende teléfonos móviles", "Una biblioteca cerrada al público"], "answer": 1, "explain": "Las bibliotecas móviles llevan libros a personas que viven lejos de las bibliotecas.", "src": "UNESCO"}, {"ch": 11, "q": "¿Qué cubre el artículo 24 de la CDPD de la ONU?", "options": ["Deportes y juegos para todos los estudiantes", "Cocina y alimentación para las familias en casa", "La educación, incluida la educación inclusiva", "Vacaciones y turismo para grupos escolares"], "answer": 2, "explain": "El artículo 24 de la CDPD de la ONU establece el derecho a la educación inclusiva.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué significa accesibilidad en las escuelas?", "options": ["Una sola puerta en el frente del edificio para todos", "Materiales que solo los docentes pueden leer", "Información ocultada a las familias de los alumnos", "Edificios, materiales e información que todos pueden usar"], "answer": 3, "explain": "La accesibilidad hace que los espacios e información escolares sean utilizables por todos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la pedagogía inclusiva?", "options": ["Métodos de enseñanza diseñados para incluir a cada estudiante", "Enseñar solo a los mejores estudiantes de cada clase todos los días", "Enseñar de una sola forma fija que sirva a todos los estudiantes", "Enseñar sin materiales ni recursos en el aula"], "answer": 0, "explain": "La pedagogía inclusiva adapta la enseñanza para que todos participen y aprendan.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué las escuelas necesitan personal de apoyo para la inclusión?", "options": ["El personal de apoyo no es necesario", "Para ayudar a los estudiantes a acceder a las clases y a la vida diaria", "Para reemplazar a todos los docentes", "Para mantener a los estudiantes separados"], "answer": 1, "explain": "El personal de apoyo ayuda a los estudiantes con discapacidad a participar en la escuela.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es el entorno menos restrictivo?", "options": ["El aula más abarrotada de todo el edificio escolar", "La sala más alejada de todas las demás aulas", "El entorno en el que un estudiante puede aprender con la mayor inclusión", "La sala sin ventanas, sin luz y sin asientos"], "answer": 2, "explain": "El entorno menos restrictivo favorece el aprendizaje con la mayor inclusión posible.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué significa la participación plena para estudiantes con discapacidad?", "options": ["Asistir solo en días especiales", "Mirar desde afuera", "Estar en un aula separada", "Participar en igualdad de condiciones en todos los ámbitos de la vida escolar"], "answer": 3, "explain": "La participación plena significa que los estudiantes pueden unirse a todas las actividades y al aprendizaje.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es el modelo social de la discapacidad?", "options": ["La discapacidad está determinada por las barreras de la sociedad", "La discapacidad es una culpa personal", "La discapacidad puede ignorarse en las escuelas", "La discapacidad solo afecta al trabajo"], "answer": 0, "explain": "El modelo social sostiene que son las barreras de la sociedad, y no solo la deficiencia, las que limitan la participación.", "src": "UN CRPD (2006), Article 24"}, {"ch": 0, "q": "¿Cuál es la relación entre el ODS 4 y el ODS 5 (Igualdad de género)?", "options": ["No tienen ninguna relación", "La educación de las niñas favorece la igualdad de género", "La igualdad de género reduce el aprendizaje", "Las niñas no deberían estudiar"], "answer": 1, "explain": "La educación es una herramienta clave para la igualdad de género, que es el Objetivo 5.", "src": "UN 2030 Agenda (2015)"}], "11": [{"ch": 0, "q": "¿Cómo describe la Agenda 2030 la relación entre los objetivos?", "options": ["Integrados e indivisibles", "Separados y sin relación", "En competencia y en conflicto", "Optativos e ignorados"], "answer": 0, "explain": "La Agenda 2030 describe los objetivos como integrados e indivisibles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué proporciona un sistema nacional de seguimiento educativo?", "options": ["Solo las fechas de vacaciones de cada escuela del año", "Datos periódicos para seguir el progreso e identificar brechas", "Solo premios de examen para los mejores alumnos de cada clase", "Solo diseños de edificios para nuevas escuelas de la ciudad"], "answer": 1, "explain": "Los sistemas de seguimiento reúnen datos para que los gobiernos vean el progreso y las brechas.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "¿Qué es un SIGE?", "options": ["Un conjunto de instrumentos musicales electrónicos para bandas escolares", "Una herramienta de calificación de exámenes que usan solo los docentes al final", "Un sistema de información para la gestión educativa que recopila datos de las escuelas", "Un plan de gestión de energía para todos los edificios escolares"], "answer": 2, "explain": "SIGE significa sistema de información para la gestión educativa, que registra datos de escuelas y estudiantes.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "¿Qué es la coherencia de políticas para el desarrollo sostenible?", "options": ["Cada sector ignora a los demás y trabaja completamente solo", "Políticas que se contradicen a propósito cada año", "Políticas que se detienen exactamente en los límites de cada distrito", "Alinear las políticas de distintos sectores para que se apoyen mutuamente"], "answer": 3, "explain": "La coherencia de políticas significa que distintas áreas trabajan juntas hacia las mismas metas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué significa la localización del ODS 4?", "options": ["Adaptar los objetivos a las prioridades y contextos locales", "Copiar exactamente el plan de un solo país", "Ignorar las necesidades locales", "Trasladar las escuelas a la Luna"], "answer": 0, "explain": "La localización ayuda a las comunidades a adaptar las metas globales a su propia situación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué es la rendición de cuentas en la política educativa?", "options": ["Evitar toda responsabilidad por los resultados de la escuela", "Hacer responsables a los líderes por los resultados y el gasto", "Ocultar los resultados al público y a la prensa", "Culpar solo a los estudiantes de cada fracaso en clase"], "answer": 1, "explain": "La rendición de cuentas significa que los líderes responden por cómo se usan los recursos educativos.", "src": "UNESCO"}, {"ch": 0, "q": "¿Qué es la participación de múltiples actores en la educación?", "options": ["Involucrar solo a funcionarios del gobierno en cada decisión", "Involucrar solo a empresas privadas y su personal", "Involucrar al gobierno, las familias, los docentes y las comunidades", "No involucrar a nadie más que a los estudiantes en las decisiones"], "answer": 2, "explain": "Los enfoques multiactor reúnen a muchos grupos para planificar y vigilar la educación.", "src": "UN 2030 Agenda (2015)"}, {"ch": 0, "q": "¿Qué es un plan sectorial de educación?", "options": ["Un plan solo para canchas y patios de juego de cada pueblo", "Un horario para una escuela de un distrito durante un trimestre", "Una lista de fechas de vacaciones para todo el país cada año", "Un plan que establece prioridades y acciones para la educación"], "answer": 3, "explain": "Los planes sectoriales orientan cómo los gobiernos invierten y actúan en toda la educación.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es una encuesta de niños fuera de la escuela?", "options": ["Una encuesta que identifica a los niños que no asisten a la escuela", "Una encuesta de autobuses escolares en las principales vías de la ciudad", "Una encuesta de vacaciones de docentes en todo el país", "Una encuesta de uniformes escolares usados en cada pueblo cada año"], "answer": 0, "explain": "Las encuestas de niños fuera de la escuela ayudan a los gobiernos a ubicar a quienes deben matricularse.", "src": "UNESCO"}, {"ch": 1, "q": "¿Por qué el acceso universal requiere algo más que construir escuelas?", "options": ["Construir escuelas siempre basta por sí solo para todos", "También importan el costo, la distancia, la discriminación y la calidad", "El acceso depende solo del clima de cada estación", "El acceso nunca es un problema para ninguna familia en ninguna región"], "answer": 1, "explain": "El acceso depende de muchos factores, no solo del número de edificios escolares.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es la matrícula según la edad adecuada?", "options": ["Niños matriculados en cualquier grado sin importar su edad", "Niños que nunca se matriculan", "Niños matriculados en el grado que corresponde a su edad", "Niños matriculados solo en la universidad"], "answer": 2, "explain": "La matrícula según la edad adecuada ayuda a los niños a aprender en un nivel apropiado.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es un estudiante con sobreedad?", "options": ["Un docente demasiado mayor para enseñar en cualquier aula ahora", "Un estudiante que terminó el grado antes y dejó la escuela", "Un estudiante sin fecha de nacimiento registrada en ningún archivo", "Un estudiante mayor que la edad normal para su grado"], "answer": 3, "explain": "Los estudiantes con sobreedad suelen necesitar programas flexibles para ponerse al día.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es el aprendizaje a distancia durante el cierre de escuelas?", "options": ["Aprender a distancia mediante tecnología o materiales", "Aprender solo en la misma sala que el docente cada día", "Aprender solo en silencio y sin hablar en absoluto", "Aprender solo de noche cuando las escuelas están cerradas"], "answer": 0, "explain": "El aprendizaje a distancia mantiene la educación cuando las escuelas no pueden abrir.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué el cierre de escuelas perjudica el aprendizaje?", "options": ["No tiene ningún efecto", "Los niños pierden tiempo y pueden rezagarse", "Siempre mejora el aprendizaje", "Solo afecta a los docentes"], "answer": 1, "explain": "Los cierres prolongados pueden causar pérdida de aprendizajes, sobre todo en niños desfavorecidos.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es la inclusión digital para los estudiantes?", "options": ["Evitar toda tecnología en la vida diaria y en cada tarea de estudio", "Usar solo papel y lápiz para todas las clases cada día", "Acceso a dispositivos, conectividad y las habilidades para usarlos", "Tener un auto y llevarlo a la escuela con amigos cada día"], "answer": 2, "explain": "La inclusión digital significa que todos pueden acceder y usar herramientas de aprendizaje digital.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Por qué a algunos estudiantes les cuesta estudiar en casa?", "options": ["Prefieren aburrirse", "El hogar siempre es ideal", "No quieren aprender", "No tienen un espacio tranquilo, dispositivos ni apoyo en casa"], "answer": 3, "explain": "Las condiciones del hogar afectan qué tan bien pueden estudiar a distancia los estudiantes.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué significa la continuidad entre grados?", "options": ["Pasar de un grado al siguiente sin dejar la escuela", "Repetir el mismo grado para siempre sin avanzar nunca", "Dejar la escuela de forma permanente y no volver a ninguna clase", "Cambiarse a una nueva escuela en otro país cada año"], "answer": 0, "explain": "La continuidad significa que los estudiantes avanzan de grado en grado de forma constante.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es una política de prevención del abandono escolar?", "options": ["Medidas que expulsan a los estudiantes", "Medidas que mantienen en la escuela a los estudiantes en riesgo", "Medidas que cierran las escuelas", "Medidas que ignoran las inasistencias"], "answer": 1, "explain": "Las políticas de prevención del abandono se centran en el apoyo temprano a los estudiantes en riesgo.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué muestra una brecha de finalización entre niñas y niños?", "options": ["Qué grupo es más alto en promedio en cada escuela cada año", "Qué grupo lee más rápido en cada clase", "Si un grupo tiene menos probabilidades de terminar la escuela", "Qué grupo disfruta mucho más del deporte que los demás"], "answer": 2, "explain": "Las brechas de finalización revelan desigualdades que requieren políticas focalizadas.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 2, "q": "¿Qué es un programa de reincorporación para exestudiantes?", "options": ["Un programa que envía estudiantes a trabajar al extranjero", "Un programa que pone fin a la escolarización", "Un programa solo para docentes", "Un programa que ayuda a quienes dejaron la escuela a volver a ella"], "answer": 3, "explain": "Los programas de reincorporación apoyan a los estudiantes para que vuelvan a la educación.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué hace una buena política de transición para los estudiantes que cambian de sistema?", "options": ["Hace más fluidos los cambios entre escuelas o niveles", "Hace mucho más difíciles los cambios para cada estudiante", "Detiene todos los cambios entre escuelas y niveles", "Cancela los exámenes al final de cada año escolar"], "answer": 0, "explain": "Una buena política de transición reduce el riesgo de abandono entre niveles.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la separación temprana por trayectorias en las escuelas?", "options": ["Hacer seguimiento a los niños solo con GPS", "Dividir a los estudiantes en vías separadas a una edad temprana", "Enseñar lo mismo a todos los niños en todas las edades", "Registrar el clima"], "answer": 1, "explain": "La separación temprana puede limitar las oportunidades futuras y aumentar la desigualdad.", "src": "UNESCO"}, {"ch": 2, "q": "¿Por qué preocupa la separación por niveles desde el punto de vista de la equidad?", "options": ["Siempre ayuda a los estudiantes más débiles", "No tiene ningún efecto sobre la equidad", "Puede encerrar a los estudiantes desfavorecidos en vías más bajas", "Facilita el aprendizaje para todos"], "answer": 2, "explain": "La separación temprana puede reforzar la desventaja si no es flexible.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué significa la frase \"terminar no basta\"?", "options": ["Terminar es la única meta", "El aprendizaje no importa", "Las escuelas deberían cerrar temprano", "También hay que garantizar la calidad del aprendizaje"], "answer": 3, "explain": "Terminar la escuela es importante, pero los estudiantes también necesitan aprender bien.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es el valor agregado en la medición del aprendizaje?", "options": ["El progreso que una escuela añade más allá de lo que los estudiantes traían al inicio", "El dinero que una escuela suma a su presupuesto anual cada año", "El peso de todos los libros guardados en los estantes de la escuela", "La cantidad de docentes que una escuela contrata cada año"], "answer": 0, "explain": "El valor agregado mide cuánto ayuda una escuela a que los estudiantes progresen.", "src": "UNESCO"}, {"ch": 3, "q": "¿Cómo se llama la brecha de aprendizaje vinculada al ingreso familiar?", "options": ["Una brecha climática", "Una brecha de aprendizaje socioeconómica", "Una brecha deportiva", "Una brecha de calzado"], "answer": 1, "explain": "Las brechas de aprendizaje vinculadas al ingreso familiar muestran oportunidades desiguales.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Por qué los países comparan sus resultados de aprendizaje con referentes?", "options": ["Para evitar enseñar", "Para clasificar a los docentes por su estatura", "Para comparar el progreso y fijar metas realistas", "Para castigar a los estudiantes"], "answer": 2, "explain": "La comparación con referentes ayuda a los países a comparar resultados y aprender unos de otros.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué favorece el aprendizaje en la lengua materna?", "options": ["Solo escribir en inglés", "Solo cantar", "Ningún aprendizaje", "La comprensión y la lectura inicial"], "answer": 3, "explain": "La enseñanza en lengua materna ayuda a los estudiantes a comprender y a desarrollar la lectura inicial.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "¿Qué es la alineación entre el currículo y la evaluación?", "options": ["Pruebas que miden lo que enseña el currículo", "Pruebas que nunca coinciden con las clases", "Pruebas que abarcan temas que no se enseñaron", "Pruebas que nunca se corrigen"], "answer": 0, "explain": "Una buena alineación asegura que las pruebas midan el aprendizaje que el currículo pretende.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es la analítica del aprendizaje?", "options": ["Contar el número de pupitres", "Usar datos sobre el aprendizaje para mejorar la enseñanza", "Adivinar el clima", "Vender datos a empresas"], "answer": 1, "explain": "La analítica del aprendizaje usa datos para comprender el aprendizaje y orientar el apoyo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 3, "q": "¿Qué es la metacognición?", "options": ["Pensar solo en deportes", "Olvidar todos los pensamientos", "Pensar sobre el propio pensamiento", "Pensar en un solo idioma"], "answer": 2, "explain": "La metacognición ayuda a los estudiantes a planificar, supervisar y mejorar su aprendizaje.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es el aprendizaje profundo en la educación?", "options": ["Aprender lo más hondo posible en una piscina", "Memorizar sin comprender", "Aprender solo en cuartos oscuros", "Comprender las ideas lo suficiente como para aplicarlas"], "answer": 3, "explain": "El aprendizaje profundo va más allá de memorizar: implica comprender y aplicar ideas.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la empleabilidad en la educación?", "options": ["Las habilidades que ayudan a las personas a encontrar y conservar un empleo", "No poder trabajar en ningún oficio ni profesión", "Tener una empresa pero nunca trabajar en ella", "Evitar todo tipo de empleo durante toda la vida"], "answer": 0, "explain": "La empleabilidad combina habilidades, conocimientos y actitudes que favorecen el trabajo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la pertinencia de la educación para el mercado laboral?", "options": ["Un aprendizaje que ignora por completo los empleos", "Un aprendizaje que coincide con las habilidades que necesita la economía", "Un aprendizaje solo para artistas", "Un aprendizaje que nunca cambia"], "answer": 1, "explain": "La educación pertinente prepara a los estudiantes para el trabajo que existe o está surgiendo.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es un aprendizaje en el puesto de trabajo (aprendiz)?", "options": ["Un tipo de examen escolar que se toma al final de cada año", "Unas vacaciones para docentes tomadas a mitad de cada trimestre", "Aprender un oficio trabajando bajo la supervisión de una persona con experiencia", "Un tipo de uniforme escolar usado en cada clase todos los días"], "answer": 2, "explain": "Los aprendizajes combinan la formación en el trabajo con el aprendizaje formal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la competencia digital para docentes y estudiantes?", "options": ["Evitar toda la tecnología", "Usar solo papel", "Romper computadoras", "Usar herramientas digitales de forma segura y eficaz"], "answer": 3, "explain": "La competencia digital ayuda a las personas a usar la tecnología para aprender, trabajar y comunicarse.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la alfabetización en inteligencia artificial?", "options": ["Comprender lo que la IA puede y no puede hacer", "Creer que la IA siempre tiene razón", "Negarse a aprender sobre IA", "Pensar que la IA reemplaza todo pensamiento"], "answer": 0, "explain": "La alfabetización en IA ayuda a los estudiantes a usarla de forma responsable y a cuestionar sus resultados.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué busca una política de aprendizaje a lo largo de la vida?", "options": ["Terminar todo aprendizaje al acabar los años escolares", "Crear oportunidades para aprender en cada etapa de la vida", "Limitar todo el aprendizaje solo a los jóvenes del pueblo", "Detener todos los programas de educación de adultos del país"], "answer": 1, "explain": "Las políticas de aprendizaje a lo largo de la vida apoyan el aprendizaje desde la infancia hasta la vejez.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es el reconocimiento de competencias adquiridas de forma informal?", "options": ["Ignorar todas las competencias aprendidas en el trabajo durante años", "Contar solo las notas de los exámenes escritos de la escuela cada año", "Otorgar crédito formal por competencias aprendidas fuera de la escuela", "Retirar certificados que las personas ya obtuvieron en su trabajo"], "answer": 2, "explain": "El reconocimiento ayuda a las personas a usar las competencias adquiridas en el trabajo y la vida comunitaria.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la innovación en la educación?", "options": ["Mantener métodos antiguos para siempre", "Copiar libros de texto antiguos", "Detener todas las ideas nuevas", "Nuevas ideas que mejoran el aprendizaje"], "answer": 3, "explain": "La innovación educativa introduce enfoques nuevos que mejoran el aprendizaje.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es la presupuestación con perspectiva de género en la educación?", "options": ["Presupuestos que consideran las necesidades de niñas y niños", "Presupuestos que ignoran por completo el género en cada decisión", "Presupuestos solo para niños de cada escuela del distrito", "Presupuestos solo para docentes, sus salarios y vacaciones"], "answer": 0, "explain": "La presupuestación sensible al género asigna dinero para atender necesidades diferentes.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué es la permanencia de las niñas en la secundaria?", "options": ["Mantener a las niñas fuera de la escuela", "Mantener a las niñas matriculadas hasta que terminen", "Mantener a las niñas en una sola clase", "Mantener a las niñas en casa"], "answer": 1, "explain": "La permanencia de las niñas significa que se quedan en la escuela hasta completar sus estudios.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué hace la protección social para las familias pobres?", "options": ["Aleja a los niños de sus familias y sus hogares", "Agrega nuevas cuotas escolares para cada familia pobre de la zona", "Ayuda a las familias a afrontar choques y a mantener a los niños en la escuela", "Suspende la alimentación escolar gratuita para los niños pobres cada día"], "answer": 2, "explain": "La protección social puede ayudar a las familias a mantener a los niños en la escuela en tiempos difíciles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué es la pobreza infantil?", "options": ["Tener demasiados juguetes", "Ser demasiado alto", "Ser demasiado listo", "Vivir en pobreza durante la niñez"], "answer": 3, "explain": "La pobreza infantil limita el acceso a la alimentación, la salud, la vivienda y el aprendizaje.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es la segregación étnica en las escuelas?", "options": ["Separar a los estudiantes de distintos grupos étnicos", "Que todos los estudiantes compartan un mismo patio", "Que todos los estudiantes hablen un mismo idioma", "Que todos los estudiantes usen el mismo uniforme"], "answer": 0, "explain": "La segregación separa a los estudiantes y limita el aprendizaje y la comprensión compartidos.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Por qué las políticas deben llegar a las comunidades nómadas y móviles?", "options": ["Nunca necesitan ninguna escuela y no la quieren", "Con frecuencia quedan excluidas de la escolarización sin opciones flexibles", "Siempre son ricas y no tienen necesidades educativas", "Prefieren no tener escuela en toda su vida"], "answer": 1, "explain": "Las comunidades móviles necesitan una escolarización flexible para acceder a la educación.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es una cuota afirmativa en la educación?", "options": ["Una cuota que prohíbe el acceso a grupos desfavorecidos", "Una cuota solo para docentes", "Una proporción de plazas reservada para grupos desfavorecidos", "Una cuota solo para deporte"], "answer": 2, "explain": "Las cuotas pueden ayudar a los estudiantes desfavorecidos a acceder a plazas que de otro modo perderían.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa el acceso igualitario para las niñas en zonas de conflicto?", "options": ["Cerrar todas las escuelas de niñas", "Enviar a las niñas lejos de su hogar", "Ignorar las necesidades de las niñas", "Rutas y escuelas seguras y protegidas"], "answer": 3, "explain": "Los espacios protegidos y las rutas seguras ayudan a las niñas a seguir aprendiendo en un conflicto.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "¿Cuál es una causa común de la pérdida de docentes?", "options": ["Salarios bajos, malas condiciones y falta de crecimiento profesional", "Demasiados ascensos y un crecimiento profesional rápido para todos", "Mucha estabilidad laboral y contratos de largo plazo para todo el personal", "Largas vacaciones y jornadas cortas para cada docente"], "answer": 0, "explain": "Los docentes se van cuando el salario, las condiciones y las perspectivas profesionales son débiles.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el aseguramiento de la calidad docente?", "options": ["Sistemas que eliminan a todos los docentes", "Sistemas que verifican que la enseñanza cumpla con los estándares", "Sistemas que fijan las vacaciones de los docentes", "Sistemas que ignoran a los estudiantes"], "answer": 1, "explain": "El aseguramiento de la calidad ayuda a mantener la enseñanza en un nivel alto.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la evaluación del desempeño docente?", "options": ["Una prueba de velocidad de carrera de los docentes en la pista de la escuela", "Una clasificación de los docentes según su estatura en la sala de profesores", "Una revisión del desempeño de un docente para apoyar su mejora", "Una revisión de los planes de vacaciones de los docentes durante todo el verano"], "answer": 2, "explain": "La evaluación ayuda a los docentes a reflexionar y mejorar, cuando se hace de forma justa.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el currículo de formación docente?", "options": ["Un horario escolar para niños", "Una lista de uniformes escolares", "Un menú para la alimentación escolar", "Las materias y habilidades que se enseñan a los futuros docentes"], "answer": 3, "explain": "Los currículos de formación docente preparan a los maestros en las materias y en la pedagogía.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué los docentes necesitan formación en evaluación?", "options": ["Para juzgar el aprendizaje con precisión y apoyarlo", "Para evitar calificar", "Para dejar de tomar pruebas", "Para calificar sin evidencias"], "answer": 0, "explain": "La formación en evaluación ayuda a los docentes a usar evidencias para apoyar a los estudiantes.", "src": "UNESCO GEM Report 2026"}, {"ch": 6, "q": "¿Qué es la capacidad de decisión del docente (agencia docente)?", "options": ["Docentes que obedecen todas las órdenes sin pensar", "La capacidad de los docentes para dar forma a su propia práctica", "Docentes que nunca planifican", "Docentes que trabajan solo de noche"], "answer": 1, "explain": "La agencia docente significa que los docentes pueden tomar decisiones que mejoran el aprendizaje.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es una comunidad profesional de aprendizaje docente?", "options": ["Un grupo que compite por obtener más vacaciones", "Un club que vende solo materiales didácticos", "Docentes que aprenden juntos para mejorar su práctica", "Un grupo de estudiantes que enseñan"], "answer": 2, "explain": "Las comunidades de aprendizaje ayudan a los docentes a compartir ideas y mejorar juntos.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué afecta el sentido de propósito de un docente?", "options": ["Solo el precio de la tiza", "Solo el costo de los edificios escolares", "Nada importante", "La motivación y el compromiso con los estudiantes"], "answer": 3, "explain": "El propósito y el compromiso influyen en cómo los docentes se relacionan con los estudiantes.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es una alianza público-privada en la educación?", "options": ["Cooperación entre gobiernos y proveedores privados", "Empresas privadas que dirigen todas las escuelas por ley", "Gobiernos que renuncian a todas sus responsabilidades", "Escuelas que pagan a los gobiernos"], "answer": 0, "explain": "Las alianzas pueden ampliar la oferta, pero deben regularse para garantizar calidad y equidad.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la regulación de las escuelas privadas?", "options": ["Prohibir por defecto todas las escuelas privadas en la ley nacional", "Normas que aseguran que las escuelas privadas cumplan estándares de calidad y seguridad", "Dejar que las escuelas privadas redacten y fijen sus propias leyes libremente", "Ignorar por completo las escuelas privadas y nunca revisarlas"], "answer": 1, "explain": "La regulación protege a los estudiantes de las escuelas privadas.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es el margen fiscal para la educación?", "options": ["Espacio para construir autos y camiones en el centro de la ciudad", "Espacio en los pasillos de la escuela para nuevos casilleros y bancos", "Espacio en el presupuesto del gobierno para aumentar el gasto", "Espacio para campamentos de vacaciones en el campo cada verano"], "answer": 2, "explain": "El margen fiscal es la flexibilidad que tiene un gobierno para financiar la educación.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué es el gasto tributario en educación?", "options": ["Dinero gastado en exámenes, calificaciones e impresión cada año", "Dinero gastado en vacaciones y días libres de los docentes cada año", "Dinero gastado en equipamiento deportivo y juegos escolares cada trimestre", "Beneficios fiscales que reducen los ingresos del gobierno destinados a la educación"], "answer": 3, "explain": "Los gastos tributarios son beneficios que pueden reducir el dinero disponible para la educación.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la costo-efectividad en la educación?", "options": ["Lograr avances en el aprendizaje al menor costo", "Gastar lo máximo posible", "Gastar solo en edificios", "Evitar todo gasto"], "answer": 0, "explain": "Los programas costo-efectivos logran más aprendizaje por cada unidad de dinero.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es una exención de cuotas?", "options": ["Una cuota por matrícula tardía para nuevas familias", "Una exención de las cuotas escolares para familias que no pueden pagarlas", "Un bono pagado a los docentes por buen trabajo cada temporada", "Un cobro por usar el autobús escolar durante todo el trimestre"], "answer": 1, "explain": "Las exenciones de cuotas ayudan a las familias pobres a mantener a sus hijos en la escuela.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es la credibilidad presupuestaria en la educación?", "options": ["El dinero nunca se gasta en las escuelas durante todo el año", "Los presupuestos se elaboran en secreto por unas pocas personas cada año", "El dinero educativo planificado se gasta realmente en las escuelas", "Los presupuestos cambian cada hora sin ninguna razón clara"], "answer": 2, "explain": "La credibilidad presupuestaria significa que el dinero educativo planificado llega efectivamente.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué papel pueden tener las asociaciones de padres y docentes en el financiamiento escolar?", "options": ["Pagar solas todos los salarios docentes", "Reemplazar por completo el financiamiento público", "Cerrar la escuela", "Recaudar dinero o apoyo para atender las necesidades de la escuela"], "answer": 3, "explain": "Las asociaciones de padres pueden ayudar a las escuelas, aunque no deberían reemplazar el financiamiento público.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué convención de 2006 trata sobre las personas con discapacidad?", "options": ["La Convención de la ONU sobre los Derechos de las Personas con Discapacidad", "La Convención de Ginebra sobre comercio internacional y aranceles", "El Acuerdo de Tokio sobre deporte y formación de atletas", "La Convención de Lima sobre agricultura, alimentos y uso de la tierra"], "answer": 0, "explain": "La CDPD se adoptó en 2006 e incluye el derecho a la educación.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "¿En qué año se adoptó la CDPD?", "options": ["1994", "2006", "1989", "2015"], "answer": 1, "explain": "La CDPD de la ONU se adoptó en 2006.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "¿Qué dice el artículo 29 de la Convención sobre los Derechos del Niño sobre la educación?", "options": ["La educación debe ser costosa", "La educación debe ser solo para niños", "La educación debe desarrollar la personalidad y los talentos de cada niño", "La educación debe prohibirse a los niños con discapacidad"], "answer": 2, "explain": "El artículo 29 establece los fines de la educación, incluido el respeto a los derechos y a la cultura.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "¿Cuál es la sigla habitual de Educación para Todos?", "options": ["ELT", "EAT", "EPR", "EPT"], "answer": 3, "explain": "EPT es la sigla habitual de Educación para Todos.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué dijo la Declaración de Incheon de 2015 sobre el aprendizaje a lo largo de la vida?", "options": ["Debe formar parte de la educación en todas las edades", "Debe terminar a los 14 años", "Debe prohibirse", "Debe aplicarse solo a los docentes"], "answer": 0, "explain": "La Declaración de Incheon promovió oportunidades de aprendizaje a lo largo de la vida para todos.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Qué organismo publica datos mundiales sobre educación?", "options": ["La Asociación Mundial de Fútbol", "El Instituto de Estadística de la UNESCO", "El Consejo Internacional de Hoteles", "El Fondo Mundial de Música"], "answer": 1, "explain": "El Instituto de Estadística de la UNESCO publica datos educativos a nivel mundial.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "¿Cuál es la relación entre los ODM y los ODS?", "options": ["Los ODS no reemplazaron nada", "Los ODS cancelaron todas las metas", "Los ODS se construyeron sobre las lecciones de los ODM", "Los ODM siguen vigentes"], "answer": 2, "explain": "Los ODS se construyeron sobre los ODM y ampliaron la agenda.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Para qué se fundó la Alianza Mundial por la Educación?", "options": ["Vender libros de texto en todo el mundo", "Organizar eventos deportivos", "Financiar viajes espaciales", "Apoyar la educación en países de bajos ingresos"], "answer": 3, "explain": "La Alianza Mundial por la Educación apoya a los países de bajos ingresos para mejorar el aprendizaje.", "src": "UNESCO GEM Report 2026"}, {"ch": 8, "q": "¿Qué dijo la Declaración Universal de Derechos Humanos sobre los padres y la educación?", "options": ["Los padres tienen un derecho preferente a elegir la educación de sus hijos", "Los padres no tienen ningún papel en la escolarización de sus hijos", "Los padres deben elegir solo deporte y juegos para sus hijos", "Los padres deben pagar todas las escuelas de su pueblo"], "answer": 0, "explain": "El artículo 26 establece que los padres tienen un derecho preferente a elegir el tipo de educación de sus hijos.", "src": "UN General Assembly (1948)"}, {"ch": 9, "q": "¿Qué es la educación y atención de la primera infancia (AEPI)?", "options": ["Cursos de educación de adultos solo para personas que trabajan", "Servicios de aprendizaje y cuidado para niños pequeños antes de la primaria", "Cursos de formación docente para nuevos maestros del país", "Exámenes de secundaria y evaluaciones finales para todos los alumnos"], "answer": 1, "explain": "La AEPI abarca servicios que apoyan el desarrollo y el aprendizaje de los niños pequeños.", "src": "UN 2030 Agenda (2015)"}, {"ch": 9, "q": "¿Qué es un enfoque multisectorial en la primera infancia?", "options": ["Solo la educación trabajando aislada en cada escuela y aula", "Solo la salud trabajando aislada en cada clínica y hospital local", "Salud, nutrición, educación y protección trabajando juntas", "Solo el deporte trabajando aislado en el patio y el campo"], "answer": 2, "explain": "Los enfoques multisectoriales atienden las necesidades de los niños en todos los servicios.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es la proporción niños por adulto?", "options": ["El número de juguetes por niño", "El número de ventanas de una sala", "El número de personal de vacaciones", "El número de niños que atiende cada adulto"], "answer": 3, "explain": "Las proporciones más bajas permiten más atención e interacción con cada niño.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué los niños pequeños necesitan cuidadores constantes?", "options": ["Las relaciones estables favorecen el crecimiento emocional y cognitivo", "La constancia no es importante para los niños pequeños", "Los niños prefieren a muchos extraños antes que a la familia cercana", "Los cuidadores deberían cambiar cada día para variar"], "answer": 0, "explain": "Los cuidadores estables y constantes ayudan a los niños a sentirse seguros y a aprender.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es el apoyo temprano a niños con discapacidad?", "options": ["Esperar hasta la escuela para empezar", "Ayuda temprana para desarrollar habilidades y desarrollo", "Mantener a los niños alejados de los demás", "Ignorar las necesidades de desarrollo"], "answer": 1, "explain": "La intervención temprana ayuda a los niños con discapacidad a desarrollar habilidades más pronto.", "src": "UN CRPD (2006), Article 24"}, {"ch": 9, "q": "¿Qué es el tamizaje del desarrollo?", "options": ["Pruebas para elegir el calzado escolar de cada alumno", "Exámenes que los docentes aprueban al final de cada año", "Controles rápidos que detectan niños que podrían necesitar apoyo", "Un control de los planes de vacaciones de la escuela local cada año"], "answer": 2, "explain": "El tamizaje ayuda a identificar niños que podrían necesitar una evaluación o ayuda adicional.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es una experiencia adversa en la infancia (EAI)?", "options": ["Un viaje feliz de vacaciones con toda la familia cada verano", "Un premio escolar por buen trabajo y esfuerzo cada trimestre", "Un tipo de examen que rinden los alumnos de primaria cada año", "Un evento estresante o dañino en la niñez que puede afectar el desarrollo"], "answer": 3, "explain": "Las EAI pueden afectar la salud y el aprendizaje, por lo que el apoyo temprano es importante.", "src": "Harvard Center on the Developing Child"}, {"ch": 10, "q": "¿Qué es una estrategia nacional de alfabetización?", "options": ["Un plan para mejorar la alfabetización en todo el país", "Un plan para vender periódicos", "Un plan para cerrar bibliotecas", "Un plan para una sola escuela"], "answer": 0, "explain": "Las estrategias nacionales de alfabetización fijan metas y acciones para mejorar la lectura y la escritura.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es la alfabetización en la era digital?", "options": ["Evitar todas las pantallas y dispositivos digitales en cada clase", "Leer, escribir y comprender información en formatos digitales", "Leer solo libros de papel y nada más en ningún momento", "Escribir solo con lápiz sobre papel en todas las materias"], "answer": 1, "explain": "La alfabetización digital extiende la lectura y la escritura a los entornos en línea.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es una encuesta de alfabetización de adultos?", "options": ["Una encuesta de vacaciones y planes de viaje de adultos cada año", "Una encuesta de autos y sus dueños en cada pueblo", "Una encuesta que mide la lectura y el cálculo en adultos", "Una encuesta de deportes y hábitos de condición física de adultos en cada pueblo"], "answer": 2, "explain": "Las encuestas de alfabetización de adultos miden habilidades para orientar la política.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Por qué son importantes las bibliotecas para la alfabetización de adultos?", "options": ["Son solo para niños y alumnos pequeños de cada pueblo", "Solo venden libros y nunca los prestan a nadie", "Están cerradas para todos los adultos a todas horas del día", "Dan acceso gratuito a libros y apoyo para aprender"], "answer": 3, "explain": "Las bibliotecas apoyan a los adultos que quieren leer, aprender y desarrollar habilidades.", "src": "UNESCO, International Literacy Day"}, {"ch": 10, "q": "¿Qué es la diversidad lingüística en la alfabetización?", "options": ["La variedad de idiomas que se usan en una comunidad", "Usar un solo idioma en todas partes", "Prohibir las lenguas locales", "Enseñar solo lengua de señas"], "answer": 0, "explain": "La diversidad lingüística importa porque los estudiantes leen y aprenden en muchos idiomas.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "¿Qué es el compromiso con la lectura entre los estudiantes?", "options": ["Qué tan rápido caminan los estudiantes", "Cuánto disfrutan los estudiantes leer y cuánto eligen hacerlo", "Qué tan fuerte hablan los estudiantes", "Cuántos libros se venden"], "answer": 1, "explain": "El compromiso con la lectura muestra cuán motivados están los estudiantes para leer.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es un programa puente de alfabetización?", "options": ["Un programa que construye puentes reales sobre ríos y caminos", "Un programa que cierra bibliotecas de la ciudad cada año", "Un programa que ayuda a los estudiantes a pasar de la alfabetización básica a una más avanzada", "Un programa solo de deportes y juegos, sin nada de lectura"], "answer": 2, "explain": "Los programas puente de alfabetización ayudan a los estudiantes a avanzar desde la lectura básica.", "src": "UNESCO, International Literacy Day"}, {"ch": 11, "q": "¿Qué es un sistema educativo inclusivo?", "options": ["Un sistema donde los estudiantes se separan por discapacidad", "Un sistema sin docentes", "Un sistema sin reglas", "Un sistema donde todos los estudiantes están incluidos en la educación regular"], "answer": 3, "explain": "Un sistema inclusivo acoge a los estudiantes y adapta la educación regular a ellos.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la no discriminación en la educación?", "options": ["Tratar a los estudiantes con equidad sin importar su discapacidad, género o origen", "Tratar a los estudiantes de forma distinta según su grupo en cada escuela", "Negar la entrada a la escuela a los estudiantes de un grupo", "Cobrar cuotas adicionales a algunos estudiantes según su origen"], "answer": 0, "explain": "La no discriminación es un principio básico de la educación inclusiva.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Cuál es el principio de representación del Diseño Universal para el Aprendizaje?", "options": ["Presentar un solo formato", "Presentar la información en múltiples formatos", "Ocultar información a los estudiantes", "Presentar todo en silencio"], "answer": 1, "explain": "Los múltiples medios de representación ayudan a los estudiantes a acceder al contenido de distintas formas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué los estudiantes con discapacidad deben tener voz en las decisiones?", "options": ["Nunca deben ser consultados", "Solo los adultos pueden decidir", "Conocen mejor sus propias necesidades", "Las decisiones deben tomarse sin ellos"], "answer": 2, "explain": "Los estudiantes con discapacidad deben ser consultados sobre las decisiones que los afectan.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la participación de los estudiantes en las decisiones escolares?", "options": ["Que los estudiantes guarden silencio", "Que los estudiantes tomen todas las decisiones solos", "Que los estudiantes nunca asistan a las reuniones", "Que los estudiantes tomen parte en las decisiones que los afectan"], "answer": 3, "explain": "La participación estudiantil desarrolla la responsabilidad y respeta los derechos de los estudiantes.", "src": "UN Convention on the Rights of the Child (1989), Article 12"}, {"ch": 11, "q": "¿Qué es el clima escolar?", "options": ["El ambiente de la escuela para estudiantes y personal", "Solo la temperatura dentro de la escuela", "La cantidad de luz solar en la escuela", "El número de autobuses escolares"], "answer": 0, "explain": "El clima escolar determina si los estudiantes se sienten seguros, respetados y motivados.", "src": "UNESCO GEM Report 2026"}, {"ch": 11, "q": "¿Qué es una política contra el acoso escolar?", "options": ["Normas que fomentan el acoso entre alumnos en cada escuela", "Normas y acciones para detener el acoso y proteger a los estudiantes", "Políticas que ignoran por completo el acoso en cada escuela", "Políticas que castigan a las víctimas del acoso cada trimestre"], "answer": 1, "explain": "Las políticas contra el acoso protegen a los estudiantes y favorecen un entorno de aprendizaje seguro.", "src": "UN 2030 Agenda (2015)"}, {"ch": 11, "q": "¿Por qué es buena para la sociedad la educación inclusiva?", "options": ["Crea división", "Reduce el aprendizaje de todos", "Construye equidad y cohesión social", "Solo sirve a unos pocos"], "answer": 2, "explain": "La educación inclusiva construye cohesión social y equidad para todos.", "src": "UN CRPD (2006), Article 24"}], "12": [{"ch": 0, "q": "¿Qué es principalmente el Marco de Acción Educación 2030?", "options": ["Una guía para que los países apliquen el ODS 4", "Un reglamento deportivo para torneos escolares", "Una ley bancaria para el banco nacional", "Un código de vestimenta escolar para todos los uniformes"], "answer": 0, "explain": "Ofrece orientación para aplicar el ODS 4 en todos los países.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "¿Qué es el marco mundial de indicadores de los ODS?", "options": ["Un calendario de días festivos para cada escuela del año", "Un conjunto acordado de indicadores para medir el progreso", "Una lista de libros prohibidos para cada biblioteca escolar", "Un mapa que muestra dónde están todos los edificios escolares"], "answer": 1, "explain": "El marco mundial proporciona indicadores comunes para seguir el progreso de los ODS.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "¿Qué muestran los niveles de clasificación de los indicadores de los ODS?", "options": ["Qué tan alto es cada estudiante al inicio del año", "Cuántas escuelas ha construido un país a lo largo del tiempo", "Qué tan consolidada está la metodología de cada indicador", "Cuánto dinero recauda una escuela con eventos cada año"], "answer": 2, "explain": "Los niveles muestran la preparación metodológica y la disponibilidad de datos de los indicadores.", "src": "UN SDG Report 2026"}, {"ch": 0, "q": "¿Por qué los indicadores del ODS 4 se desglosan por nivel de riqueza?", "options": ["Para clasificar a las familias según la estatura de cada miembro", "Para elegir los uniformes escolares", "Para fijar las fechas de vacaciones", "Para revelar las brechas entre estudiantes ricos y pobres"], "answer": 3, "explain": "El desglose por riqueza muestra si el progreso llega a los estudiantes más pobres.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "¿Qué mide el seguimiento de la financiación del ODS 4?", "options": ["Cuánto dinero se invierte y a dónde va", "Cuántos árboles se plantan", "Cuántos clubes deportivos existen", "Cuántos libros se imprimen"], "answer": 0, "explain": "El seguimiento de la financiación muestra los niveles de inversión y si llegan a los grupos prioritarios.", "src": "Incheon Framework for Action (2015)"}, {"ch": 0, "q": "¿Qué es la evaluación de políticas en educación?", "options": ["Elegir nuevos colores oficiales para pintar la fachada de la escuela", "Valorar si las políticas logran sus objetivos", "Contar las ventanas de la fachada de todos los edificios escolares", "Escribir poemas sobre las vacaciones de verano de cada año"], "answer": 1, "explain": "La evaluación ayuda a decidir si las políticas deben continuar, cambiar o detenerse.", "src": "UNESCO"}, {"ch": 0, "q": "¿Qué es una política basada en evidencia?", "options": ["Una política hecha sin ningún tipo de dato o evidencia", "Una política hecha a ciegas, sin ninguna base", "Una política informada por la investigación y los datos", "Una política copiada de las películas y la televisión"], "answer": 2, "explain": "Una política basada en evidencia usa la investigación para orientar las decisiones.", "src": "UNESCO"}, {"ch": 0, "q": "¿Por qué los gobiernos necesitan sistemas de datos educativos?", "options": ["Para evitar tomar decisiones sobre la educación cada año", "Para ocultar información a la ciudadanía y a la prensa", "Para reemplazar a los docentes por sistemas automáticos", "Para planificar, monitorear y mejorar la educación"], "answer": 3, "explain": "Los sistemas de datos apoyan la planificación, el seguimiento y la rendición de cuentas.", "src": "UNESCO GEM Report 2026"}, {"ch": 0, "q": "¿Qué significa que el ODS 4 tenga sinergias con otros objetivos?", "options": ["El avance en educación ayuda a avanzar en otros objetivos", "La educación bloquea todos los demás objetivos", "La educación no tiene ninguna relación con otros objetivos", "Otros objetivos solo afectan al deporte"], "answer": 0, "explain": "La educación apoya las metas de salud, igualdad de género, empleo y clima.", "src": "UN 2030 Agenda (2015)"}, {"ch": 1, "q": "¿Qué es la no matriculación?", "options": ["Estar matriculado pero no asistir", "Estar en edad escolar pero no estar matriculado", "Asistir a la escuela solo en el extranjero", "Enseñar sin cobrar"], "answer": 1, "explain": "La no matriculación significa que los niños en edad escolar no están inscritos en la escuela.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué es el acceso efectivo a la educación?", "options": ["Un acceso que solo existe sobre el papel, sin aulas reales", "Un acceso que no incluye a ningún docente en ninguna parte", "Un acceso que también lleva a un aprendizaje real", "Un acceso que solo dura un día y luego desaparece"], "answer": 2, "explain": "El acceso efectivo significa que los niños asisten y aprenden, no solo que se matriculan.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es una vía de recuperación para niños con escolarización interrumpida?", "options": ["Una ruta que les permite dejar la escuela sin más trámites", "Una ruta para saltar grados sin aprender nada en realidad", "Una ruta que cierra escuelas y aleja a los niños de ellas", "Una ruta que les ayuda a ponerse al día y reincorporarse"], "answer": 3, "explain": "Las vías de recuperación ayudan a los niños que perdieron escolarización a reincorporarse a la educación.", "src": "UNESCO"}, {"ch": 1, "q": "¿Qué exige el derecho a la educación a los Estados?", "options": ["Hacer la educación disponible, accesible, aceptable y adaptable", "Ofrecer educación solo para las familias ricas del país", "Ofrecer educación solo en las grandes ciudades del país", "Hacer la educación totalmente opcional para cada familia"], "answer": 0, "explain": "Las cuatro A describen las obligaciones básicas del derecho a la educación.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "¿Qué significa disponibilidad en el derecho a la educación?", "options": ["Que las escuelas nunca abran para ningún estudiante durante el año", "Que existan suficientes escuelas y programas que funcionen", "Que las escuelas solo abran los fines de semana y festivos", "Que las escuelas sean solo para uso de los docentes algunos días"], "answer": 1, "explain": "La disponibilidad significa contar con suficientes instituciones y programas en funcionamiento.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "¿Qué significa aceptabilidad en el derecho a la educación?", "options": ["Una educación que siempre resulta aburrida para el alumnado", "Una educación que se mantiene en secreto ante las familias", "Una educación de buena calidad y culturalmente apropiada", "Una educación que se imparte en una sola lengua y nada más"], "answer": 2, "explain": "La aceptabilidad significa que la educación es pertinente, segura y de buena calidad.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "¿Qué significa adaptabilidad en el derecho a la educación?", "options": ["Una educación que nunca cambia con las necesidades de cada época", "Una educación que ignora las necesidades de estudiantes y familias", "Una educación que permanece igual para siempre en todas las escuelas", "Una educación que se adapta a las necesidades de los estudiantes y la sociedad"], "answer": 3, "explain": "La adaptabilidad significa que la educación responde a las necesidades cambiantes.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 1, "q": "¿Por qué preocupa el gasto de bolsillo en educación?", "options": ["Las familias pagan directamente, lo que puede alejar a los niños de la escuela", "Las familias nunca tienen que pagar nada por la educación", "El gasto de bolsillo siempre ayuda a las escuelas y a todos los alumnos por igual", "Solo afecta a los docentes y a su salario mensual"], "answer": 0, "explain": "Los altos costos directos pueden impedir que las familias pobres envíen a sus hijos a la escuela.", "src": "UNESCO GEM Report 2026"}, {"ch": 1, "q": "¿Qué es una respuesta educativa humanitaria?", "options": ["Educación que se imparte solo en tiempos de paz y estabilidad", "Apoyo a la educación en emergencias y crisis", "Una respuesta que directamente cierra las escuelas afectadas", "Una respuesta que se limita solo al ámbito del deporte escolar"], "answer": 1, "explain": "Las respuestas educativas humanitarias mantienen el aprendizaje durante las crisis.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué es una vía de aprendizaje de la secundaria a la educación terciaria?", "options": ["Una ruta para dejar la educación para siempre y no volver", "Una ruta solo para adultos que ya dejaron la escuela", "Una ruta de la secundaria a la educación superior", "Una ruta a un club deportivo para cada estudiante tras la escuela"], "answer": 2, "explain": "Las vías conectan la educación secundaria con los estudios y la formación terciarios.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la educación terciaria?", "options": ["La educación previa al jardín de infantes para niños muy pequeños", "La educación solo para docentes en sus cursos de formación", "La educación solo para el deporte y el entrenamiento en clubes", "La educación posterior a la secundaria, como la universitaria"], "answer": 3, "explain": "La educación terciaria incluye universidades, institutos superiores y formación técnica avanzada.", "src": "UNESCO"}, {"ch": 2, "q": "¿Qué es la equidad en la finalización?", "options": ["Tasas de finalización similares entre grupos", "Tasas de finalización que favorecen solo a los ricos", "Tasas de finalización que nunca se miden", "Tasas de finalización que siempre son cero"], "answer": 0, "explain": "La equidad en la finalización significa que los grupos terminan la escuela en tasas similares.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Quiénes son los jóvenes que abandonan la educación y la formación tempranamente?", "options": ["Jóvenes que dejan la escuela antes por unas vacaciones", "Jóvenes que se van sin completar la educación secundaria", "Docentes que se van antes", "Estudiantes que terminan primero"], "answer": 1, "explain": "Los abandonos tempranos son jóvenes que salen sin un título de secundaria.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es un programa profesional en la educación secundaria superior?", "options": ["Un curso de cocina y repostería enseñado solo en casa", "Una licenciatura universitaria en historia, derecho y política", "Un curso que da habilidades prácticas y títulos", "Un campamento de vacaciones para niños pequeños en verano"], "answer": 2, "explain": "Los programas profesionales de la secundaria superior dan habilidades prácticas y títulos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Por qué es importante terminar la escuela para la vida posterior?", "options": ["No tiene ningún efecto apreciable en la vida adulta posterior", "Solo afecta a las vacaciones familiares y a los viajes de ocio", "Solo afecta a la práctica del deporte y a las competiciones", "Influye mucho en la salud, el empleo y los ingresos"], "answer": 3, "explain": "Terminar la escuela se relaciona con mejor salud, empleo y bienestar.", "src": "UNESCO GEM Report 2026"}, {"ch": 2, "q": "¿Qué es la finalización a lo largo de la vida?", "options": ["Completar el aprendizaje a cualquier edad", "Completar el aprendizaje solo antes de los diez años", "Dejar de aprender al terminar la escuela", "Aprender solo para los docentes"], "answer": 0, "explain": "La finalización a lo largo de la vida significa que las personas pueden terminar su aprendizaje a cualquier edad.", "src": "UN 2030 Agenda (2015)"}, {"ch": 2, "q": "¿Qué es la reversión del abandono escolar?", "options": ["Estudiantes que dejan la escuela más rápido y sin trámites", "Estudiantes que vuelven a la educación tras haberla dejado", "Estudiantes que retroceden de curso solo cuando hay exámenes", "Estudiantes que reducen el pago de las cuotas escolares cada año"], "answer": 1, "explain": "La reversión del abandono significa que los estudiantes vuelven a entrar y terminan su educación.", "src": "UNESCO"}, {"ch": 3, "q": "¿Cuál es la meta de competencias fundamentales para los países?", "options": ["Que los niños aprendan solo música y canto durante toda la primaria", "Que los niños nunca aprendan a leer en la primaria", "Que la mayoría domine lectura y cálculo básicos al terminar la primaria", "Que los niños falten a clase y se queden en casa en la primaria"], "answer": 2, "explain": "Muchos países buscan que los niños alcancen las competencias básicas al inicio de la primaria.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué significa calidad en el aprendizaje?", "options": ["Un aprendizaje solo rápido y apresurado en cada clase", "Un aprendizaje solo largo y agotador para cada alumno", "Un aprendizaje que evita todos los exámenes y pruebas para cada alumno", "Un aprendizaje pertinente, eficaz y equitativo"], "answer": 3, "explain": "La calidad del aprendizaje responde a las necesidades de los estudiantes y conduce a un progreso real.", "src": "UNESCO GEM Report 2026"}, {"ch": 3, "q": "¿Qué es la pertinencia del currículo?", "options": ["Vincular el aprendizaje con la vida de los estudiantes y el trabajo futuro", "Enseñar contenidos que nunca se usan en ninguna situación real", "Ignorar por completo la vida y los intereses de los estudiantes", "Enseñar únicamente en lenguas muertas y sin ninguna aplicación práctica"], "answer": 0, "explain": "Los currículos pertinentes conectan las lecciones con la vida real y las necesidades futuras.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es una política educativa basada en resultados?", "options": ["Fijar metas según el tamaño de la escuela", "Fijar metas según lo que los estudiantes pueden hacer", "Fijar metas según la estatura de los docentes", "Fijar metas según la duración de las vacaciones"], "answer": 1, "explain": "La política basada en resultados se centra en las habilidades y logros que alcanzan los estudiantes.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es el translanguaging en el aula?", "options": ["Prohibir todas las lenguas salvo una en la escuela para cada estudiante", "Usar solo lengua de señas en cada clase de la jornada escolar", "Usar todas las lenguas del estudiante para apoyar el aprendizaje", "Enseñar solo en silencio, sin hablar en ninguna clase"], "answer": 2, "explain": "El translanguaging usa todo el repertorio lingüístico del estudiante para ayudarle a aprender.", "src": "UNESCO, International Mother Language Day"}, {"ch": 3, "q": "¿Qué es la carga cognitiva?", "options": ["El peso de una mochila escolar", "El número de páginas de un libro", "La cantidad de luz solar en una habitación", "La cantidad de esfuerzo mental que exige una tarea"], "answer": 3, "explain": "La carga cognitiva importa para cómo los estudiantes procesan y recuerdan la información.", "src": "Harvard Center on the Developing Child"}, {"ch": 3, "q": "¿Qué es la práctica espaciada?", "options": ["Repartir las sesiones de aprendizaje en el tiempo para mejorar la memoria", "Memorizar todo en una sola noche justo antes del examen final", "No volver a practicar nunca el mismo material en ningún momento", "Practicar solo durante las largas vacaciones escolares de cada año"], "answer": 0, "explain": "La práctica espaciada ayuda a recordar mejor la información con el tiempo.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es la práctica de recuperación?", "options": ["Copiar apuntes una y otra vez sin intentar recordar nada después", "Evocar la información de la memoria para reforzar el aprendizaje", "Leer únicamente el título del tema y nada más de su contenido", "Ignorar por completo lo que se enseñó en la clase de ayer"], "answer": 1, "explain": "La práctica de recuperación fortalece la memoria al evocar lo aprendido.", "src": "UNESCO"}, {"ch": 3, "q": "¿Qué es el sesgo en la evaluación?", "options": ["Pruebas que siempre son totalmente justas con todo el alumnado", "Pruebas que nunca miden realmente lo que han aprendido los alumnos", "Pruebas que favorecen injustamente a unos grupos sobre otros", "Pruebas que solo sirven para medir la estatura de los alumnos"], "answer": 2, "explain": "El sesgo en la evaluación puede perjudicar a los estudiantes por razones ajenas a su capacidad.", "src": "UNESCO GEM Report 2026"}, {"ch": 4, "q": "¿Qué son las habilidades transversales?", "options": ["Habilidades que sirven para una única materia escolar concreta", "Habilidades para aprender a dormir mejor cada noche del año", "Habilidades que solo sirven para cruzar la calle con seguridad", "Habilidades útiles en muchas materias y trabajos"], "answer": 3, "explain": "Las habilidades transversales, como la comunicación y el trabajo en equipo, se aplican en todas partes.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la pedagogía digital?", "options": ["Métodos de enseñanza que usan bien la tecnología", "Enseñanza que prescinde por completo de cualquier tecnología", "Enseñanza que se realiza solo con máquinas rotas y sin uso", "Enseñanza que se imparte solo en silencio absoluto del aula"], "answer": 0, "explain": "La pedagogía digital usa la tecnología para apoyar el aprendizaje, no solo para reemplazar el papel.", "src": "UNESCO"}, {"ch": 4, "q": "¿Qué es la privacidad de datos en la tecnología educativa?", "options": ["Compartir los datos de los estudiantes con desconocidos", "Proteger la información personal de los estudiantes", "Vender los datos de los estudiantes", "Ignorar las normas de privacidad"], "answer": 1, "explain": "La privacidad de datos protege a los estudiantes del mal uso de su información personal.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la mejora de habilidades (upskilling)?", "options": ["Perder habilidades que ya se tienen mientras se trabaja a diario", "Aprender solo para los niños de primaria cada año escolar completo", "Aprender nuevas habilidades para seguir el ritmo de un trabajo cambiante", "Terminar toda formación al empezar un nuevo empleo o carrera"], "answer": 2, "explain": "La mejora de habilidades ayuda a los trabajadores a adaptarse a nuevas tecnologías y empleos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es el reciclaje profesional (reskilling)?", "options": ["Olvidar todas las habilidades y conocimientos del pasado", "Aprender solo deportes y juegos por diversión en el tiempo libre", "Dejar de trabajar por completo y quedarse en casa para siempre", "Aprender nuevas habilidades para cambiar a otro tipo de trabajo"], "answer": 3, "explain": "El reciclaje profesional prepara a las personas para nuevos roles cuando cambian los empleos.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la formación para empleos verdes?", "options": ["Preparar a los trabajadores para empleos que ayudan al medio ambiente", "Formación para empleos que dañan la naturaleza y el entorno", "Formación únicamente para pintar paredes y muros de los edificios", "Formación centrada exclusivamente en practicar algún deporte escolar"], "answer": 0, "explain": "La formación para empleos verdes prepara a las personas para trabajos sostenibles.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es la competencia global?", "options": ["Ignorar por completo a otros países y sus habitantes", "Comprender el mundo y las demás culturas y participar en él", "Conocer solo la historia de un país y nada más", "Negarse a viajar o a conocer personas de otros países"], "answer": 1, "explain": "La competencia global ayuda a los estudiantes a entender los problemas mundiales y comunicarse entre culturas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 4, "q": "¿Qué es el aprendizaje socioemocional (SEL)?", "options": ["Aprender a evitar todos los sentimientos y emociones en cualquier situación", "Aprender solo matemáticas y nada más en la escuela cada día", "Aprender a gestionar las emociones y relacionarse bien con los demás", "Aprender a guardar silencio en cada entorno social al que se entra"], "answer": 2, "explain": "El SEL desarrolla la autoconciencia, la empatía y las habilidades de relación.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué son las normas de género?", "options": ["Reglas sobre lo que los niños comen en el comedor de cada escuela", "Medidas del tamaño de cada edificio escolar en toda la ciudad", "Reglas sobre las vacaciones y los días libres solo del personal", "Expectativas compartidas sobre cómo deben comportarse niñas y niños"], "answer": 3, "explain": "Las normas de género moldean los roles y las oportunidades de niñas y niños.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué relación tiene mantener a las niñas en la escuela con el matrimonio infantil?", "options": ["Es una de las formas más eficaces de retrasar el matrimonio infantil", "Anima a las niñas a casarse muy jóvenes cada año", "No tiene ninguna relación con el matrimonio en ninguna comunidad", "Cierra las escuelas para niñas de la comunidad cada trimestre"], "answer": 0, "explain": "Mantener a las niñas en la escuela es una de las formas más eficaces de retrasar el matrimonio infantil.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Cuál es el impacto del embarazo adolescente en la escolarización?", "options": ["Siempre mejora la escolarización de las estudiantes y sus familias", "Puede interrumpir la educación de las niñas", "No tiene ninguna relación con la vida escolar de las personas", "Solo afecta a los niños varones de la misma edad"], "answer": 1, "explain": "El embarazo puede interrumpir la escolarización, por lo que importan las políticas de reincorporación y apoyo.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Qué es el saneamiento inclusivo en las escuelas?", "options": ["Baños solo para los docentes y el personal de la escuela", "Ningún baño ni instalación de lavado para ningún alumno", "Baños e instalaciones de lavado que cubren las necesidades de todos", "Baños que siempre están cerrados a los estudiantes durante el día"], "answer": 2, "explain": "El saneamiento inclusivo incluye instalaciones para niñas y para estudiantes con discapacidad.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 5, "q": "¿Más allá del dinero, qué incluye la pobreza de los estudiantes?", "options": ["Tener demasiados libros para leer en casa cada noche", "Tener demasiados amigos con quienes jugar después de clase", "Tener demasiado tiempo libre para jugar cada día después de clase", "Falta de comida, transporte, materiales y espacio para estudiar"], "answer": 3, "explain": "La pobreza de los estudiantes incluye la falta de comida, transporte, materiales y espacio tranquilo para estudiar.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué es la desventaja múltiple?", "options": ["Enfrentar varias barreras a la vez", "No tener ninguna barrera", "Enfrentar solo una pequeña barrera", "Tener demasiado apoyo"], "answer": 0, "explain": "La desventaja múltiple significa que varias barreras se combinan y requieren respuestas conjuntas.", "src": "UN 2030 Agenda (2015)"}, {"ch": 5, "q": "¿Qué significa la inclusión de las personas refugiadas en los sistemas nacionales?", "options": ["Separar de forma permanente a los estudiantes refugiados", "Incluir a los estudiantes refugiados en el sistema nacional", "Rechazar a los estudiantes refugiados", "Enseñar a los refugiados solo en línea"], "answer": 1, "explain": "La inclusión de personas refugiadas en los sistemas nacionales les ayuda a acceder a la educación y a títulos reconocidos.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué es la educación nómada?", "options": ["Escolarización siempre en un mismo edificio", "Escolarización solo para niños de la ciudad", "Escolarización diseñada para comunidades móviles", "Escolarización sin docentes"], "answer": 2, "explain": "La educación nómada adapta la enseñanza y los horarios a las familias móviles.", "src": "UNESCO"}, {"ch": 5, "q": "¿Qué mide un índice de equidad en la educación?", "options": ["La altura de los edificios escolares de cada barrio de la ciudad", "El número de timbres que suenan en los recreos del colegio", "La duración de las vacaciones de los docentes de cada región", "Cómo se comparan el acceso o los resultados entre grupos"], "answer": 3, "explain": "Los índices de equidad resumen qué tan justamente se distribuye la educación.", "src": "UNESCO GEM Report 2026"}, {"ch": 5, "q": "¿Qué significa el equilibrio de género entre el profesorado?", "options": ["Un número equilibrado de mujeres y hombres entre los docentes", "Solo se permite enseñar a hombres en las escuelas de aquí", "Solo se permite enseñar a mujeres en las escuelas de aquí", "No se necesitan docentes en ninguna de las escuelas de aquí"], "answer": 0, "explain": "El equilibrio de género entre docentes puede influir en los modelos a seguir y en la cultura escolar.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 6, "q": "¿Qué es el análisis de oferta y demanda de docentes?", "options": ["Comparar los colores y la ropa favoritos de los docentes cada año", "Comparar cuántos docentes se necesitan con cuántos hay disponibles", "Contar cuántas vacaciones y días libres toman los docentes cada año", "Comparar la estatura de los docentes en la sala de profesores cada año"], "answer": 1, "explain": "El análisis de oferta y demanda ayuda a los gobiernos a planificar la contratación.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la reforma de la formación docente?", "options": ["Eliminar toda la formación inicial y continua del profesorado", "Acabar con las carreras profesionales de los docentes", "Cambiar la forma en que se forma a los docentes", "Cerrar solo las escuelas normales y mantener el resto abiertas"], "answer": 2, "explain": "La reforma de la formación docente actualiza la preparación para que coincida con las aulas actuales.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el desarrollo del liderazgo escolar?", "options": ["Formar a los directivos para no enseñar en ninguna clase que visiten", "Formar a los directivos solo en deporte y juegos para la escuela", "Formar a los directivos para cerrar las escuelas pronto cada trimestre", "Formar a los directivos para orientar la enseñanza y el aprendizaje"], "answer": 3, "explain": "Desarrollar líderes mejora la calidad de la escuela.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué incluye la progresión profesional docente?", "options": ["Pasos claros para crecer en habilidades y responsabilidades", "Ningún paso para que los docentes avancen en su carrera", "Solo vacaciones y pausas largas cada año para los docentes", "Solo recortes salariales y menos personal cada trimestre"], "answer": 0, "explain": "Una progresión clara ayuda a los docentes a crecer y permanecer en la profesión.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es la relación entre docente y estudiante?", "options": ["Una relación sin ningún contacto personal ni comunicación", "Un vínculo positivo que apoya el aprendizaje", "Solo un negocio que se rige por intereses económicos", "Una rivalidad que acaba frenando por completo el aprendizaje"], "answer": 1, "explain": "Las relaciones sólidas ayudan a los estudiantes a sentirse seguros y motivados.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Qué es el tiempo de trabajo docente?", "options": ["Solo el número de minutos que dura una jornada escolar completa", "El tiempo que se pasa disfrutando de vacaciones y días libres", "El tiempo total que un docente dedica a enseñar y tareas afines", "El tiempo que se pasa cada mañana viajando en el autobús escolar"], "answer": 2, "explain": "El tiempo de trabajo incluye la planificación, la corrección y otras tareas fuera de clase.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 6, "q": "¿Por qué algunos docentes necesitan apoyo adicional en zonas de crisis?", "options": ["No enfrentan ninguna dificultad especial en su trabajo diario", "Nunca necesitan apoyo de ningún tipo en su práctica docente", "Tienen demasiadas vacaciones y días libres durante el curso", "Enfrentan condiciones inseguras y traumas"], "answer": 3, "explain": "Los docentes en crisis pueden necesitar formación y apoyo para su bienestar.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 7, "q": "¿Qué es el gasto en educación por estudiante?", "options": ["El gasto promedio en cada estudiante", "El número de libros por escuela", "El costo de un examen", "El costo de una ruta de autobús"], "answer": 0, "explain": "El gasto por estudiante permite comparar los recursos entre sistemas.", "src": "UNESCO"}, {"ch": 7, "q": "¿Por qué puede preocupar el reparto de costos para el acceso?", "options": ["Siempre reduce los costos que pagan las familias de la comunidad", "Puede trasladar costos a familias que no pueden pagarlos", "No tiene ningún impacto sobre el acceso de los estudiantes", "Elimina por completo todas las cuotas que pagan las familias"], "answer": 1, "explain": "El reparto de costos puede crear barreras para las familias pobres si no se gestiona bien.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es el alivio de deuda para la educación?", "options": ["Aumentar la deuda pública para financiar únicamente el deporte escolar", "Cerrar todas las escuelas públicas del país de forma inmediata", "Reducir los pagos de deuda para que el dinero vaya a las escuelas", "Obligar a los docentes a pagar las deudas de la administración"], "answer": 2, "explain": "El alivio de deuda puede liberar fondos para la educación.", "src": "UNESCO GEM Report 2026"}, {"ch": 7, "q": "¿Qué es el financiamiento innovador para la educación?", "options": ["Pagar a los docentes solo en oro y piedras preciosas", "Vender solo pupitres y mobiliario escolar usado cada año", "Cerrar escuelas de forma sistemática para ahorrar dinero", "Nuevas formas de recaudar dinero para la educación"], "answer": 3, "explain": "El financiamiento innovador incluye nuevos mecanismos para movilizar fondos.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué es un plan de financiamiento educativo?", "options": ["Un plan que muestra cómo se financiará la educación a lo largo del tiempo", "Un plan solo para las vacaciones escolares, sin clases", "Un plan para comprar autos y furgonetas para el personal escolar", "Un plan sin cifras, costos ni fechas"], "answer": 0, "explain": "Un plan de financiamiento vincula las metas educativas con el dinero necesario para alcanzarlas.", "src": "Incheon Framework for Action (2015)"}, {"ch": 7, "q": "¿Qué es la descentralización fiscal en educación?", "options": ["Llevar cada año todo el dinero de la educación a la capital del país", "Dar a los gobiernos locales más control sobre el dinero de la educación", "Prohibir por completo que los gobiernos locales tomen cualquier decisión", "Cerrar las escuelas locales una a una hasta que no quede ninguna"], "answer": 1, "explain": "La descentralización puede mejorar la respuesta local, pero necesita salvaguardas de equidad.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es una subvención de nivelación?", "options": ["Dinero que hace aún más ricas a las zonas ricas cada año", "Dinero solo para vacaciones y días libres de los docentes cada verano", "Fondos extra que ayudan a las zonas más pobres a igualar a las más ricas", "Dinero para cerrar escuelas en las zonas pobres cada año"], "answer": 2, "explain": "Las subvenciones de nivelación reducen las brechas entre regiones.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué es una cláusula de caducidad en el financiamiento educativo?", "options": ["Una cláusula que trata sobre los atardeceres y la puesta de sol", "Una regla para organizar las noches de baile en las escuelas", "Una regla que duplica automáticamente la financiación cada día", "Regla que pone fin a la financiación tras un plazo, salvo renovación"], "answer": 3, "explain": "Las cláusulas de caducidad terminan los programas salvo que se revisen y renueven.", "src": "UNESCO"}, {"ch": 7, "q": "¿Qué son los ingresos del gobierno para la educación?", "options": ["El dinero que el gobierno recauda de impuestos y otras fuentes", "El dinero de las entradas deportivas vendidas en el estadio nacional cada año", "El dinero de las cuotas escolares pagadas solo por las familias, sin impuestos", "El dinero que se gana solo con el turismo y los viajes cada año"], "answer": 0, "explain": "Los ingresos del gobierno son la base principal del financiamiento público de la educación.", "src": "UNESCO"}, {"ch": 8, "q": "¿Qué promovió la Declaración de Salamanca?", "options": ["Escuelas solo para niños separados", "Escuelas inclusivas para todos los niños", "Escuelas solo para adultos", "Escuelas solo para docentes"], "answer": 1, "explain": "La Declaración de Salamanca promovió la inclusión de niños con necesidades especiales.", "src": "UN CRPD (2006), Article 24"}, {"ch": 8, "q": "¿En qué año se aprobó la Declaración Universal de Derechos Humanos?", "options": ["1989", "1990", "1948", "2015"], "answer": 2, "explain": "La DUDH fue aprobada por la Asamblea General de la ONU en 1948.", "src": "UN General Assembly (1948)"}, {"ch": 8, "q": "¿Qué convención establece los derechos de la infancia, incluida la educación?", "options": ["El Tratado de Comercio", "La Carta Deportiva de Ginebra", "El Código de Navegación de Tokio", "La Convención sobre los Derechos del Niño"], "answer": 3, "explain": "La CDN, aprobada en 1989, establece los derechos de la infancia, incluido el derecho a la educación.", "src": "UN Convention on the Rights of the Child (1989), Article 28"}, {"ch": 8, "q": "¿A qué se comprometieron los objetivos de Dakar en la primera infancia?", "options": ["Ampliar y mejorar la atención y educación de la primera infancia", "Cerrar los servicios de primera infancia en todo el país", "Ignorar por completo a los niños pequeños y sus familias", "Prohibir los jardines de infancia en cada pueblo y ciudad"], "answer": 0, "explain": "Los objetivos de Dakar incluían ampliar y mejorar la atención y educación de la primera infancia.", "src": "UNESCO, World Education Forum (2000)"}, {"ch": 8, "q": "¿Qué pretendía la Declaración de Incheon para 2030?", "options": ["Solo educación terciaria para los mejores estudiantes de cada año", "Educación inclusiva, equitativa, de calidad y aprendizaje permanente", "Solo deporte y juegos para cada escuela de todo el país", "Solo escuelas de verano en cada región durante los meses estivales"], "answer": 1, "explain": "La Declaración de Incheon fijó este objetivo para 2030.", "src": "World Education Forum, Incheon Declaration (2015)"}, {"ch": 8, "q": "¿Por qué los ODS de 2015 fueron más allá de los ODM?", "options": ["Son solo para los países pobres del mundo y nadie más", "Cubren solo la educación y nada más en el mundo", "Son universales y cubren temas más amplios como el clima y la desigualdad", "Pusieron fin a toda la ayuda a los países más pobres del mundo"], "answer": 2, "explain": "Los ODS se aplican a todos los países y abarcan más temas que los ODM.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Cuál es el objetivo de la Educación para el Desarrollo Sostenible (EDS)?", "options": ["Enseñar únicamente leyes ambientales y normas de contaminación", "Cerrar las clases de ciencias y de biología en todos los centros", "Dejar de estudiar cualquier tema ambiental en todos los niveles", "Preparar a los estudiantes para actuar por un futuro sostenible"], "answer": 3, "explain": "La EDS ayuda a los estudiantes a comprender la sostenibilidad y a actuar.", "src": "UN 2030 Agenda (2015)"}, {"ch": 8, "q": "¿Qué hace el Relator Especial de la ONU sobre el derecho a la educación?", "options": ["Informa sobre el derecho a la educación en todo el mundo", "Dirige una escuela y coordina a su personal docente en la ciudad", "Arbitra partidos de fútbol en las ligas profesionales de cada país", "Gestiona un banco y supervisa sus operaciones financieras"], "answer": 0, "explain": "El Relator Especial de la ONU informa sobre el derecho a la educación en el mundo.", "src": "UN Special Rapporteur on the Right to Education"}, {"ch": 9, "q": "¿Qué moldea principalmente el desarrollo del cerebro en los primeros años?", "options": ["El color de los juguetes", "Las experiencias y las relaciones", "El número de autobuses escolares", "El precio de los uniformes escolares"], "answer": 1, "explain": "Las relaciones y las experiencias moldean el desarrollo del cerebro en la primera infancia.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Por qué las políticas de primera infancia necesitan coordinación intersectorial?", "options": ["Los niños solo necesitan educación en el aula para aprender bien", "Los niños solo necesitan atención sanitaria para prosperar", "Las necesidades de la infancia abarcan salud, nutrición y aprendizaje", "Los niños no necesitan nada de ningún servicio ni familia"], "answer": 2, "explain": "La coordinación ayuda a atender las necesidades de los niños en distintos servicios.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es un índice de desarrollo de la primera infancia?", "options": ["Una medida del tamaño y del estado de los edificios escolares", "Un recuento de las mascotas que tienen los docentes en casa", "Una lista de los festivos nacionales y locales de cada año", "Una medida de la preparación de los niños en áreas clave"], "answer": 3, "explain": "Los índices de desarrollo siguen la preparación de los niños en distintos ámbitos.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es la interacción rica en lenguaje en la primera infancia?", "options": ["Una conversación que construye vocabulario y comprensión", "Juego silencioso con juguetes y sin hablar en toda la sala", "Gritar constantemente a los niños durante todo el día en casa", "Ver solo televisión durante horas y horas cada día"], "answer": 0, "explain": "La interacción rica en lenguaje favorece la lectura y el aprendizaje posteriores.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es la detección temprana y la derivación?", "options": ["Ignorar a los niños que necesitan ayuda en la escuela y en casa", "Encontrar a los niños que necesitan ayuda y conectarlos con los servicios", "Etiquetar a los niños de forma permanente con una etiqueta fija y dura", "Mandar a casa a los niños cada vez que muestran que necesitan ayuda"], "answer": 1, "explain": "Los sistemas de derivación conectan a los niños con el apoyo adecuado a tiempo.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Qué es el apoyo a las familias en la primera infancia?", "options": ["Apartar a los niños de sus familias y de sus hogares", "Prohibir las visitas de familias a la escuela durante todo el año", "Ayuda para que las familias cuiden y eduquen a los niños pequeños", "Ignorar por completo a las familias en cada decisión sobre la escuela"], "answer": 2, "explain": "El apoyo a las familias refuerza el aprendizaje en el hogar y el bienestar.", "src": "Harvard Center on the Developing Child"}, {"ch": 9, "q": "¿Cómo se relaciona la salud infantil con el aprendizaje?", "options": ["La salud no tiene ninguna relación con el aprendizaje en ninguna escuela", "Los niños enfermos aprenden más rápido que los sanos en clase", "La salud solo importa cuando termina la jornada escolar para siempre", "La buena salud favorece la asistencia, la atención y el desarrollo"], "answer": 3, "explain": "La salud infantil está estrechamente ligada a los resultados de aprendizaje.", "src": "UN 2030 Agenda (2015)"}, {"ch": 10, "q": "¿Qué es la alfabetización a lo largo de la vida?", "options": ["Seguir desarrollando las habilidades de lectura y escritura durante toda la vida", "Leer solo en la infancia y nunca más después", "Leer solo en la escuela y nunca en casa ni fuera de ella", "Leer solo por motivos laborales y nada más en toda la vida"], "answer": 0, "explain": "La alfabetización a lo largo de la vida significa seguir leyendo y escribiendo a lo largo de la vida.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué son las habilidades de lectura para informarse?", "options": ["Leer solo ficción, sobre todo novelas y cuentos de ficción", "Encontrar y usar datos en los textos", "Leer solo poesía y textos de creación literaria", "Leer sin ningún propósito concreto, por simple costumbre"], "answer": 1, "explain": "Leer para informarse ayuda a encontrar datos para tomar decisiones.", "src": "UNESCO"}, {"ch": 10, "q": "¿Qué es la legibilidad de un texto?", "options": ["Qué tan pesado y voluminoso resulta un libro en la mano", "Cuántas páginas y capítulos tiene exactamente un libro", "Qué tan fácil es de leer y entender un texto", "Cuánto dinero cuesta comprar un libro nuevo en la tienda"], "answer": 2, "explain": "La legibilidad depende del idioma, la longitud de las frases y el vocabulario.", "src": "UNESCO GEM Report 2026"}, {"ch": 10, "q": "¿Qué es la brecha de género en la alfabetización?", "options": ["Diferencias de estatura media que existen entre niñas y niños", "Diferencias de talla de zapato que hay entre niñas y niños", "Diferencias en los colores favoritos que eligen niñas y niños", "Diferencias en las habilidades lectoras entre niñas y niños"], "answer": 3, "explain": "Las brechas de género en alfabetización varían según el país y requieren respuestas específicas.", "src": "UNESCO GEM Gender Report 2026"}, {"ch": 10, "q": "¿Qué es el acceso a materiales impresos en contextos con pocos recursos?", "options": ["Acceso a materiales impresos para leer", "Prohibir por completo la impresión de cualquier material escrito", "Imprimir únicamente billetes y moneda para el uso del Estado", "Imprimir solo mapas detallados de la superficie de la Luna"], "answer": 0, "explain": "El acceso a materiales impresos ayuda a los estudiantes de contextos con pocos recursos a practicar la lectura.", "src": "UNESCO"}, {"ch": 10, "q": "¿Qué es una política de alfabetización en lengua materna?", "options": ["Una política para prohibir las lenguas maternas en todas las escuelas del país", "Una política para enseñar la lectura inicial en la lengua que hablan los niños", "Una política para enseñar solo inglés en todas las clases de todas las escuelas", "Una política para enseñar solo lengua de señas en todas las clases desde los seis años"], "answer": 1, "explain": "La alfabetización en lengua materna favorece la lectura inicial y la identidad.", "src": "UNESCO, International Mother Language Day"}, {"ch": 10, "q": "¿Qué es la alfabetización para el desarrollo?", "options": ["Alfabetización sin ningún propósito en la vida diaria o el trabajo", "Alfabetización solo para turistas que visitan el país cada año", "Usar la alfabetización para mejorar la salud, el empleo y la vida comunitaria", "Alfabetización que termina cuando cada niño cumple diez años"], "answer": 2, "explain": "La alfabetización favorece el desarrollo en la salud, el trabajo y la vida cívica.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 10, "q": "¿Qué es un programa de lectura por placer?", "options": ["Un programa que prohíbe por completo los libros de cuentos infantiles", "Un programa que solo evalúa la ortografía de los estudiantes", "Un programa que deja de enseñar la lectura a los diez años", "Un programa que anima a los niños a leer por disfrute"], "answer": 3, "explain": "La lectura por placer crea motivación y hábitos que favorecen la alfabetización a lo largo de la vida.", "src": "UNESCO, International Literacy Day 2026"}, {"ch": 11, "q": "¿Qué significa la inclusión como principio de derechos humanos en la educación?", "options": ["Todo estudiante pertenece y participa", "Algunos estudiantes son separados", "Los estudiantes se mantienen apartados según su capacidad", "Los estudiantes son excluidos por diseño"], "answer": 0, "explain": "La inclusión es un principio de derechos humanos que garantiza la pertenencia y la participación.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la formación docente inclusiva?", "options": ["Formar al profesorado para enseñar solo a los mejores estudiantes", "Formar al profesorado para enseñar a todo el alumnado", "Formar al profesorado para evitar a estudiantes con discapacidad", "Formar al profesorado solo en deporte"], "answer": 1, "explain": "La formación docente inclusiva prepara al profesorado para aulas diversas.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué significa el apoyo individual en una escuela inclusiva?", "options": ["Apoyo solo para toda la escuela en su conjunto y no para alumnos", "Apoyo solo para los mejores estudiantes de cada curso escolar", "Ayuda adaptada a las necesidades específicas de cada estudiante", "Ningún tipo de apoyo en absoluto para ningún estudiante nunca"], "answer": 2, "explain": "El apoyo individual adapta la ayuda a cada estudiante.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la inclusión de la discapacidad en los currículos?", "options": ["Excluir la discapacidad de todas las lecciones impartidas en clase", "Enseñar la discapacidad como castigo para los alumnos que se portan mal", "Enseñar la discapacidad solo en la clase de deporte cada semana", "Incluir la discapacidad como parte del aprendizaje sobre la diversidad"], "answer": 3, "explain": "La inclusión de la discapacidad en los currículos fomenta el respeto y la comprensión.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la evaluación participativa para la inclusión?", "options": ["Involucrar a los estudiantes en juzgar su propio progreso", "Evaluar a los estudiantes en secreto sin decírselo", "Ignorar la opinión de los estudiantes sobre su propio trabajo", "Evaluar a los estudiantes solo por su estatura"], "answer": 0, "explain": "La evaluación participativa desarrolla la autoconciencia y la inclusión.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Qué es la contratación inclusiva de docentes?", "options": ["Contratar solo a un grupo", "Contratar docentes de grupos diversos", "Rechazar a todas las personas candidatas", "Contratar solo por vínculos familiares"], "answer": 1, "explain": "La contratación inclusiva ayuda a que las escuelas reflejen las comunidades a las que sirven.", "src": "UNESCO Global Report on Teachers (2024)"}, {"ch": 11, "q": "¿Qué son los datos inclusivos sobre discapacidad?", "options": ["Datos que ocultan por completo la discapacidad a la vista del público", "Datos sobre discapacidad solo en deporte y juegos cada temporada", "Datos que incluyen a las personas con discapacidad y sus necesidades", "Datos que nunca se recogen en ninguna escuela o distrito"], "answer": 2, "explain": "Los datos inclusivos ayudan a que las políticas respondan a la discapacidad.", "src": "UN CRPD (2006), Article 24"}, {"ch": 11, "q": "¿Por qué se llama multiplicador al derecho a la educación?", "options": ["Porque multiplica el precio de los libros de texto y materiales", "Porque duplica las cuotas escolares que pagan las familias", "Porque solo se aplica a los docentes y a su formación", "Porque ayuda a las personas a acceder a otros derechos"], "answer": 3, "explain": "La educación ayuda a las personas a acceder a la salud, el trabajo, la participación política y otros derechos.", "src": "UN Special Rapporteur on the Right to Education"}]};
